INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f7f7c78-d246-4b88-a1a0-a688e373ecda', '長相思', '长相思', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["九月西風興，月冷露華凝。","思君秋夜長，一夜魂九升。","二月東風來，草拆花心開。","思君春日遲，一日腸九迴。","妾住洛橋北，君住洛橋南。","十五即相識，今年二十三。","有如女蘿草，生在松之側。","蔓短枝苦高，縈迴上不得。","人言人有願，願至天必成。","願作遠方獸，步步比肩行。","願作深山木，枝枝連理生。"]', '["九月西风兴，月冷露华凝。","思君秋夜长，一夜魂九升。","二月东风来，草拆花心开。","思君春日遲，一日腸九迴。","妾住洛橋北，君住洛橋南。","十五即相識，今年二十三。","有如女蘿草，生在松之側。","蔓短枝苦高，縈迴上不得。","人言人有願，願至天必成。","願作远方獸，步步比肩行。","願作深山木，枝枝連理生。"]', '诗', 'shi', '', NULL, '長相思 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94f2ece1-4d41-41c5-81a5-3f6c91f86cc2', '山鷓鴣', '山鷓鴣', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["山鷓鴣，朝朝暮暮啼復啼，啼時露白風淒淒。","黃茅岡頭秋日晚，苦竹嶺下寒月低。","畬田有粟何不啄，石楠有枝何不棲？","迢迢不緩復不急，樓上舟中聲闇入。","夢鄉遷客展轉臥，抱兒寡婦彷徨立。","山鷓鴣，爾本此鄉鳥。","生不辭巢不別羣，何苦聲聲啼到曉。","啼到曉，唯能愁北人，南人慣聞如不聞。"]', '["山鷓鴣，朝朝暮暮啼复啼，啼时露白风淒淒。","黄茅岡头秋日晚，苦竹嶺下寒月低。","畬田有粟何不啄，石楠有枝何不棲？","迢迢不緩复不急，楼上舟中声闇入。","梦乡遷客展轉臥，抱兒寡婦彷徨立。","山鷓鴣，爾本此乡鸟。","生不辞巢不別羣，何苦声声啼到晓。","啼到晓，唯能愁北人，南人慣闻如不闻。"]', '诗', 'shi', '', NULL, '山鷓鴣 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45ca0762-7bc6-4a29-94a9-edd1ca287568', '放旅雁', '放旅雁', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["九江十年冬大雪，江水生冰樹枝折。","百鳥無食東西飛，中有旅鴈聲最飢。","雪中啄草冰上宿，翅冷騰空飛動遲。","江童持網捕將去，手攜入市生賣之。","我本北人今譴謫，人鳥雖殊同是客。","見此客鳥傷客人，贖汝放汝飛入雲。","鴈鴈汝飛向何處？第一莫飛西北去。","淮西有賊討未平，百萬甲兵久屯聚。","官軍賊軍相守老，食盡兵窮將及汝。","健兒飢餓射汝喫，拔汝翅翎爲箭羽。"]', '["九江十年冬大雪，江水生冰樹枝折。","百鸟無食东西飞，中有旅鴈声最飢。","雪中啄草冰上宿，翅冷腾空飞动遲。","江童持網捕將去，手携入市生賣之。","我本北人今譴謫，人鸟雖殊同是客。","见此客鸟傷客人，贖汝放汝飞入云。","鴈鴈汝飞向何处？第一莫飞西北去。","淮西有賊討未平，百万甲兵久屯聚。","官軍賊軍相守老，食尽兵窮將及汝。","健兒飢餓射汝喫，拔汝翅翎爲箭羽。"]', '诗', 'shi', '', NULL, '放旅雁 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('634f34d5-c116-4417-b2f3-4ec76f027659', '送春歸', '送春归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["送春歸，三月盡日日暮時。","去年杏園花飛御溝綠，何處送春曲江曲。","今年杜鵑花落子規啼，送春何處西江西。","帝城送春猶怏怏，天涯送春能不加惆悵。","莫惆悵，送春人。","冗員無替五年罷，應須準擬再送潯陽春。","五年炎涼凡十變，又知此身健不健。","好去今年江上春，明年未死還相見。"]', '["送春归，三月尽日日暮时。","去年杏园花飞御溝綠，何处送春曲江曲。","今年杜鵑花落子規啼，送春何处西江西。","帝城送春猶怏怏，天涯送春能不加惆悵。","莫惆悵，送春人。","冗員無替五年罷，應須準擬再送潯陽春。","五年炎涼凡十变，又知此身健不健。","好去今年江上春，明年未死還相见。"]', '诗', 'shi', '', NULL, '送春歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d8a000b-b06d-4320-bd30-e9aa8e9a14b0', '山石榴寄元九', '山石榴寄元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["山石榴，一名山躑躅，一名杜鵑花。","杜鵑啼時花撲撲，九江三月杜鵑來，一聲催得一枝開。","江城上佐閑無事，山下斸得廳前栽。","爛熳一闌十八樹，根株有數花無數。","千房萬葉一時新，嫩紫殷紅鮮麴塵。","淚痕裛損燕支臉，剪刀裁破紅綃巾。","謫仙初墮愁在世，姹女新嫁嬌泥春。","日射血珠將滴地，風飜火燄欲燒人。","閑折兩枝持在手，細看不似人間有。","花中此物似西施，芙蓉芍藥皆嫫母。","奇芳絕豔別者誰，通州遷客元拾遺。","拾遺初貶江陵去，去時正值青春暮。","商山秦嶺愁殺君，山石榴花紅夾路。","題詩報我何所云，苦云色似石榴帬。","當時叢畔唯思我，今日闌前只憶君。","憶君不見坐銷落，日西風起紅紛紛。"]', '["山石榴，一名山躑躅，一名杜鵑花。","杜鵑啼时花撲撲，九江三月杜鵑来，一声催得一枝开。","江城上佐闲無事，山下斸得廳前栽。","爛熳一闌十八樹，根株有數花無數。","千房万葉一时新，嫩紫殷紅鲜麴塵。","泪痕裛損燕支臉，剪刀裁破紅綃巾。","謫仙初墮愁在世，姹女新嫁嬌泥春。","日射血珠將滴地，风飜火燄欲燒人。","闲折兩枝持在手，細看不似人间有。","花中此物似西施，芙蓉芍藥皆嫫母。","奇芳絕豔別者誰，通州遷客元拾遺。","拾遺初貶江陵去，去时正值青春暮。","商山秦嶺愁殺君，山石榴花紅夾路。","題诗報我何所云，苦云色似石榴帬。","當时叢畔唯思我，今日闌前只憶君。","憶君不见坐銷落，日西风起紅紛紛。"]', '诗', 'shi', '', NULL, '山石榴寄元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f29124d-9d42-45c3-affe-8d2699e155fe', '畫竹歌', '畫竹歌', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["植物之中竹難寫，故今雖畫無似者。","蕭郎下筆獨逼真，丹青以來唯一人。","人畫竹身肥擁腫，蕭畫莖瘦節節竦。","人畫竹梢死羸垂，蕭畫枝活葉葉動。","不根而生從意生，不筍而成由筆成。","野塘水邊碕岸側，森森兩叢十五莖。","嬋娟不失筠粉態，蕭颯盡得風煙情。","舉頭忽看不似畫，低耳靜聽疑有聲。","西叢七莖勁而健，省向天竺寺前石上見。","東叢八莖疎且寒，憶曾湘妃廟裏雨中看。","幽姿遠思少人別，與君相顧空長歎。","蕭郎蕭郎老可惜，手顫眼昏頭雪色。","自言便是絕筆時，從今此竹尤難得。"]', '["植物之中竹难寫，故今雖畫無似者。","蕭郎下笔独逼真，丹青以来唯一人。","人畫竹身肥擁腫，蕭畫莖瘦節節竦。","人畫竹梢死羸垂，蕭畫枝活葉葉动。","不根而生從意生，不筍而成由笔成。","野塘水邊碕岸側，森森兩叢十五莖。","嬋娟不失筠粉態，蕭颯尽得风煙情。","舉头忽看不似畫，低耳静听疑有声。","西叢七莖勁而健，省向天竺寺前石上见。","东叢八莖疎且寒，憶曾湘妃廟裏雨中看。","幽姿远思少人別，與君相顧空长歎。","蕭郎蕭郎老可惜，手顫眼昏头雪色。","自言便是絕笔时，從今此竹尤难得。"]', '诗', 'shi', '', NULL, '畫竹歌 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d496aa33-4887-4b07-8076-cb6c242d4ba7', '真娘墓', '真娘墓', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["真娘墓，虎丘道。","不識真娘鏡中面，唯見真娘墓頭草。","霜摧桃李風折蓮，真娘死時猶少年。","脂膚荑手不牢固，世間尤物難留連。","難留連，易銷歇，塞北花，江南雪。"]', '["真娘墓，虎丘道。","不識真娘镜中面，唯见真娘墓头草。","霜摧桃李风折蓮，真娘死时猶少年。","脂膚荑手不牢固，世间尤物难留連。","难留連，易銷歇，塞北花，江南雪。"]', '诗', 'shi', '', NULL, '真娘墓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a0f9231-d88c-4f81-b941-83b67a736194', '長恨歌', '长恨歌', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["漢皇重色思傾國，御宇多年求不得。","楊家有女初長成，養在深閨人未識。","天生麗質難自棄，一朝選在君王側。","回眸一笑百媚生，六宮粉黛無顏色。","春寒賜浴華清池，溫泉水滑洗凝脂。","侍兒扶起嬌無力，始是新承恩澤時。","雲鬢花顏金步搖，芙蓉帳暖度春宵。","春宵苦短日高起，從此君王不早朝。","承歡侍宴無閑暇，春從春遊夜專夜。","後宮佳麗三千人，三千寵愛在一身。","金屋妝成嬌侍夜，玉樓宴罷醉和春。","姊妹弟兄皆列土，可憐光彩生門戶。","遂令天下父母心，不重生男重生女。","驪宮高處入青雲，仙樂風飄處處聞。","緩歌慢舞凝絲竹，盡日君王看不足。","漁陽鞞鼓動地來，驚破霓裳羽衣曲。","九重城闕煙塵生，千乘萬騎西南行。","翠華搖搖行復止，西出都門百餘里。","六軍不發無奈何，宛轉蛾眉馬前死。","花鈿委地無人收，翠翹金雀玉搔頭。","君王掩面救不得，回看血淚相和流。","黃埃散漫風蕭索，雲棧縈紆登劒閣。","峨嵋山下少人行，旌旗無光日色薄。","蜀江水碧蜀山青，聖主朝朝暮暮情。","行宮見月傷心色，夜雨聞鈴腸斷聲。","天旋日轉迴龍馭，到此躊躇不能去。","馬嵬坡下泥土中，不見玉顏空死處。","君臣相顧盡霑衣，東望都門信馬歸。","歸來池苑皆依舊，太液芙蓉未央柳。","芙蓉如面柳如眉，對此如何不淚垂？","春風桃李花開夜，秋雨梧桐葉落時。","西宮南苑多秋草，宮葉滿階紅不埽。","棃園弟子白髮新，椒房阿監青娥老。","夕殿螢飛思悄然，孤燈挑盡未成眠。","遲遲鐘鼓初長夜，耿耿星河欲曙天。","鴛鴦瓦冷霜華重，翡翠衾寒誰與共。","悠悠生死別經年，魂魄不曾來入夢。","臨邛道士鴻都客，能以精誠致魂魄。","爲感君王展轉思，遂教方士殷勤覓。","排空馭氣奔如電，升天入地求之徧。","上窮碧落下黃泉，兩處茫茫皆不見。","忽聞海上有仙山，山在虛無縹緲間。","樓閣玲瓏五雲起，其中綽約多仙子。","中有一人字太真，雪膚花貌參差是。","金闕西廂叩玉扃，轉教小玉報雙成。","聞道漢家天子使，九華帳裏夢魂驚。","攬衣推枕起裴回，珠箔銀屏邐迤開。","雲鬢半偏新睡覺，花冠不整下堂來。","風吹仙袂飄颻舉，猶似霓裳羽衣舞。","玉容寂莫淚闌干，棃花一枝春帶雨。","含情凝睇謝君王，一別音容兩渺茫。","昭陽殿裏恩愛絕，蓬萊宮中日月長。","回頭下望人寰處，不見長安見塵霧。","唯將舊物表深情，鈿合金釵寄將去。","釵留一股合一扇，釵擘黃金合分鈿。","但教心似金鈿堅，天上人間會相見。","臨別殷勤重寄詞，詞中有誓兩心知。","七月七日長生殿，夜半無人私語時。","在天願作比翼鳥，在地願爲連理枝。","天長地久有時盡，此恨緜緜無絕期。"]', '["漢皇重色思傾国，御宇多年求不得。","楊家有女初长成，養在深閨人未識。","天生丽質难自棄，一朝選在君王側。","回眸一笑百媚生，六宮粉黛無顏色。","春寒賜浴华清池，溫泉水滑洗凝脂。","侍兒扶起嬌無力，始是新承恩澤时。","云鬢花顏金步搖，芙蓉帳暖度春宵。","春宵苦短日高起，從此君王不早朝。","承歡侍宴無闲暇，春從春游夜專夜。","後宮佳丽三千人，三千寵愛在一身。","金屋妝成嬌侍夜，玉楼宴罷醉和春。","姊妹弟兄皆列土，可怜光彩生门戶。","遂令天下父母心，不重生男重生女。","驪宮高处入青云，仙乐风飄处处闻。","緩歌慢舞凝絲竹，尽日君王看不足。","漁陽鞞鼓动地来，驚破霓裳羽衣曲。","九重城闕煙塵生，千乘万騎西南行。","翠华搖搖行复止，西出都门百餘里。","六軍不發無奈何，宛轉蛾眉马前死。","花鈿委地無人收，翠翹金雀玉搔头。","君王掩面救不得，回看血泪相和流。","黄埃散漫风蕭索，云棧縈紆登劒閣。","峨嵋山下少人行，旌旗無光日色薄。","蜀江水碧蜀山青，聖主朝朝暮暮情。","行宮见月傷心色，夜雨闻鈴腸斷声。","天旋日轉迴龙馭，到此躊躇不能去。","马嵬坡下泥土中，不见玉顏空死处。","君臣相顧尽霑衣，东望都门信马归。","归来池苑皆依旧，太液芙蓉未央柳。","芙蓉如面柳如眉，对此如何不泪垂？","春风桃李花开夜，秋雨梧桐葉落时。","西宮南苑多秋草，宮葉满階紅不埽。","棃园弟子白髮新，椒房阿監青娥老。","夕殿螢飞思悄然，孤灯挑尽未成眠。","遲遲鐘鼓初长夜，耿耿星河欲曙天。","鴛鴦瓦冷霜华重，翡翠衾寒誰與共。","悠悠生死別經年，魂魄不曾来入梦。","臨邛道士鴻都客，能以精誠致魂魄。","爲感君王展轉思，遂教方士殷勤覓。","排空馭氣奔如電，升天入地求之徧。","上窮碧落下黄泉，兩处茫茫皆不见。","忽闻海上有仙山，山在虛無縹緲间。","楼閣玲瓏五云起，其中綽約多仙子。","中有一人字太真，雪膚花貌參差是。","金闕西廂叩玉扃，轉教小玉報雙成。","闻道漢家天子使，九华帳裏梦魂驚。","攬衣推枕起裴回，珠箔銀屏邐迤开。","云鬢半偏新睡覺，花冠不整下堂来。","风吹仙袂飄颻舉，猶似霓裳羽衣舞。","玉容寂莫泪闌干，棃花一枝春带雨。","含情凝睇謝君王，一別音容兩渺茫。","昭陽殿裏恩愛絕，蓬萊宮中日月长。","回头下望人寰处，不见长安见塵霧。","唯將旧物表深情，鈿合金釵寄將去。","釵留一股合一扇，釵擘黄金合分鈿。","但教心似金鈿堅，天上人间會相见。","臨別殷勤重寄词，词中有誓兩心知。","七月七日长生殿，夜半無人私語时。","在天願作比翼鸟，在地願爲連理枝。","天长地久有时尽，此恨緜緜無絕期。"]', '诗', 'shi', '', NULL, '長恨歌 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f24ba5d0-86c3-4632-94c7-8334c17cb325', '婦人苦', '婦人苦', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蟬鬢加意梳，蛾眉用心埽。","幾度曉妝成，君看不言好。","妾身重同穴，君意輕偕老。","惆悵去年來，心知未能道。","今朝一開口，語少意何深。","願引他時事，移君此日心。","人言夫婦親，義合如一身。","及至死生際，何曾苦樂均。","婦人一喪夫，終身守孤孑。","有如林中竹，忽被風吹折。","一折不重生，枯死猶抱節。","男兒若喪婦，能不暫傷情。","應似門前柳，逢春易發榮。","風吹一枝折，還有一枝生。","爲君委曲言，願君再三聽。","須知婦人苦，從此莫相輕。"]', '["蟬鬢加意梳，蛾眉用心埽。","幾度晓妝成，君看不言好。","妾身重同穴，君意轻偕老。","惆悵去年来，心知未能道。","今朝一开口，語少意何深。","願引他时事，移君此日心。","人言夫婦親，義合如一身。","及至死生際，何曾苦乐均。","婦人一喪夫，終身守孤孑。","有如林中竹，忽被风吹折。","一折不重生，枯死猶抱節。","男兒若喪婦，能不暫傷情。","應似门前柳，逢春易發榮。","风吹一枝折，還有一枝生。","爲君委曲言，願君再三听。","須知婦人苦，從此莫相轻。"]', '诗', 'shi', '', NULL, '婦人苦 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afa751bd-268f-4f53-b8cd-be33b62f9fee', '長安道', '长安道', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["花枝缺處青樓開，豔歌一曲酒一杯。","美人勸我急行樂，自古朱顏不再來。","君不見外州客，長安道，一迴來，一迴老。"]', '["花枝缺处青楼开，豔歌一曲酒一杯。","美人勸我急行乐，自古朱顏不再来。","君不见外州客，长安道，一迴来，一迴老。"]', '诗', 'shi', '', NULL, '長安道 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2302b508-8d5f-4e43-aaf7-2463d0717e0a', '潛別離', '潛別離', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不得哭，潛別離，不得語，闇相思。","兩心之外無人知，深籠夜鏁獨棲鳥。","利劒春斷連理枝，河水雖濁有清日。","烏頭雖黑有白時，唯有潛離與暗別。"]', '["不得哭，潛別離，不得語，闇相思。","兩心之外無人知，深籠夜鏁独棲鸟。","利劒春斷連理枝，河水雖濁有清日。","烏头雖黑有白时，唯有潛離與暗別。"]', '诗', 'shi', '', NULL, '潛別離 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a4aebc8-e23e-42b7-8ccb-8a40366adcee', '隔浦蓮', '隔浦蓮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["隔浦愛紅蓮，昨日看猶在。","夜來風吹落，只得一回采。","花開雖有明年期，復愁明年還暫時。"]', '["隔浦愛紅蓮，昨日看猶在。","夜来风吹落，只得一回采。","花开雖有明年期，复愁明年還暫时。"]', '诗', 'shi', '', NULL, '隔浦蓮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31f3bef9-f227-4ea2-9f4e-8ffb59c8a171', '寒食野望吟', '寒食野望吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["丘墟郭門外，寒食誰家哭。","風吹曠野紙錢飛，古墓纍纍春草綠。","棠棃花映白楊樹，盡是死生離別處。","冥寞重泉哭不聞，蕭蕭暮雨人歸去。"]', '["丘墟郭门外，寒食誰家哭。","风吹曠野紙錢飞，古墓纍纍春草綠。","棠棃花映白楊樹，尽是死生離別处。","冥寞重泉哭不闻，蕭蕭暮雨人归去。"]', '诗', 'shi', '', NULL, '寒食野望吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fb0189c-8ff3-4106-af94-f6d26d528a1d', '琵琶引', '琵琶引', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["潯陽江頭夜送客，楓葉荻花秋索索。","主人下馬客在船，舉酒欲飲無管弦。","醉不成歡慘將別，別時茫茫江浸月。","忽聞水上琵琶聲，主人忘歸客不發。","尋聲暗問彈者誰，琵琶聲停欲語遲。","移船相近邀相見，添酒迴燈重開宴。","千呼萬喚始出來，猶抱琵琶半遮面。","轉軸撥弦三兩聲，未成曲調先有情。","弦弦掩抑聲聲思，似訴平生不得意。","低眉信手續續彈，說盡心中無限事。","輕攏慢撚抹復挑，初爲霓裳後六幺。","大弦嘈嘈如急雨，小弦切切如私語。","嘈嘈切切錯雜彈，大珠小珠落玉盤。","間關鶯語花底滑，幽咽泉流水下灘。","水泉冷澀弦疑絕，疑絕不通聲暫歇。","別有幽愁暗恨生，此時無聲勝有聲。","銀缾乍破水漿迸，鐵騎突出刀槍鳴。","曲終收撥當心畫，四弦一聲如裂帛。","東舟西舫悄無言，唯見江心秋月白。","沈吟放撥插弦中，整頓衣裳起斂容。","自言本是京城女，家在蝦蟇陵下住。","十三學得琵琶成，名蜀教坊第一部。","曲罷曾教善才伏，妝成每被秋娘妬。","五陵年少爭纏頭，一曲紅綃不知數。","鈿頭雲箆擊節碎，血色羅帬飜酒汙。","今年歡笑復明年，秋月春風等閑度。","弟走從軍阿姨死，暮去朝來顏色故。","門前冷落鞍馬稀，老大嫁作商人婦。","商人重利輕別離，前月浮梁買茶去。","去來江口守空船，繞船月明江水寒。","夜深忽夢少年事，夢啼妝淚紅闌干。","我聞琵琶已歎息，又聞此語重唧唧。","同是天涯淪落人，相逢何必曾相識。","我從去年辭帝京，謫居臥病潯陽城。","潯陽小處無音樂，終歲不聞絲竹聲。","住近湓江地低濕，黃蘆苦竹繞宅生。","其間旦暮聞何物，杜鵑啼血猨哀鳴。","春江花朝秋月夜，往往取酒還獨傾。","豈無山歌與村笛，嘔啞嘲哳難爲聽。","今夜聞君琵琶語，如聽仙樂耳暫明。","莫辭更坐彈一曲，爲君飜作琵琶行。","感我此言良久立，却坐促弦弦轉急。","淒淒不似向前聲，滿座重聞皆掩泣。","座中泣下誰最多，江州司馬青衫濕。"]', '["潯陽江头夜送客，楓葉荻花秋索索。","主人下马客在船，舉酒欲饮無管弦。","醉不成歡慘將別，別时茫茫江浸月。","忽闻水上琵琶声，主人忘归客不發。","尋声暗问彈者誰，琵琶声停欲語遲。","移船相近邀相见，添酒迴灯重开宴。","千呼万喚始出来，猶抱琵琶半遮面。","轉軸撥弦三兩声，未成曲調先有情。","弦弦掩抑声声思，似訴平生不得意。","低眉信手續續彈，说尽心中無限事。","轻攏慢撚抹复挑，初爲霓裳後六幺。","大弦嘈嘈如急雨，小弦切切如私語。","嘈嘈切切錯杂彈，大珠小珠落玉盤。","间关鶯語花底滑，幽咽泉流水下灘。","水泉冷澀弦疑絕，疑絕不通声暫歇。","別有幽愁暗恨生，此时無声勝有声。","銀缾乍破水漿迸，鐵騎突出刀槍鳴。","曲終收撥當心畫，四弦一声如裂帛。","东舟西舫悄無言，唯见江心秋月白。","沈吟放撥插弦中，整頓衣裳起斂容。","自言本是京城女，家在蝦蟇陵下住。","十三学得琵琶成，名蜀教坊第一部。","曲罷曾教善才伏，妝成每被秋娘妬。","五陵年少爭纏头，一曲紅綃不知數。","鈿头云箆擊節碎，血色羅帬飜酒汙。","今年歡笑复明年，秋月春风等闲度。","弟走從軍阿姨死，暮去朝来顏色故。","门前冷落鞍马稀，老大嫁作商人婦。","商人重利轻別離，前月浮梁買茶去。","去来江口守空船，繞船月明江水寒。","夜深忽梦少年事，梦啼妝泪紅闌干。","我闻琵琶已歎息，又闻此語重唧唧。","同是天涯淪落人，相逢何必曾相識。","我從去年辞帝京，謫居臥病潯陽城。","潯陽小处無音乐，終歲不闻絲竹声。","住近湓江地低濕，黄蘆苦竹繞宅生。","其间旦暮闻何物，杜鵑啼血猨哀鳴。","春江花朝秋月夜，往往取酒還独傾。","豈無山歌與村笛，嘔啞嘲哳难爲听。","今夜闻君琵琶語，如听仙乐耳暫明。","莫辞更坐彈一曲，爲君飜作琵琶行。","感我此言良久立，却坐促弦弦轉急。","淒淒不似向前声，满座重闻皆掩泣。","座中泣下誰最多，江州司马青衫濕。"]', '诗', 'shi', '', NULL, '琵琶引 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('021b47d2-ef8a-42ca-a7c6-8a8bbb39a98a', '簡簡吟', '簡簡吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蘇家小女名簡簡，芙蓉花顋柳葉眼。","十一把鏡學點妝，十二抽鍼能繡裳。","十三行坐事調品，不肯迷頭白地藏。","玲瓏雲髻生花樣，飄颻風袖薔薇香。","殊姿異態不可狀，忽忽轉動如有光。","二月繁霜殺桃李，明年欲嫁今年死。","丈人阿母勿悲啼，此女不是凡夫妻。","恐是天仙謫人世，只合人間十三歲。","大都好物不堅牢，彩雲易散琉璃脆。"]', '["蘇家小女名簡簡，芙蓉花顋柳葉眼。","十一把镜学点妝，十二抽鍼能繡裳。","十三行坐事調品，不肯迷头白地藏。","玲瓏云髻生花樣，飄颻风袖薔薇香。","殊姿異態不可狀，忽忽轉动如有光。","二月繁霜殺桃李，明年欲嫁今年死。","丈人阿母勿悲啼，此女不是凡夫妻。","恐是天仙謫人世，只合人间十三歲。","大都好物不堅牢，彩云易散琉璃脆。"]', '诗', 'shi', '', NULL, '簡簡吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ee8cc24-814b-4a1a-8167-be749659a959', '花非花', '花非花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["花非花，霧非霧，夜半來，天明去。","來如春夢幾多時，去似朝雲無覓處。"]', '["花非花，霧非霧，夜半来，天明去。","来如春梦幾多时，去似朝云無覓处。"]', '诗', 'shi', '', NULL, '花非花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5618f10a-fb25-47ed-81fc-fe37d0cfcf5d', '醉後狂言酬贈蕭殷二協律', '醉後狂言酬贈蕭殷二協律', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["餘杭邑客多羇貧，其間甚者蕭與殷。","天寒身上猶衣葛，日高甑中未拂塵。","江城山寺十一月，北風吹沙雪紛紛。","賓客不見綈袍惠，黎庶未霑襦袴恩。","此時太守自慙媿，重衣複衾有餘溫。","因命染人與鍼女，先製兩裘贈二君。","吳緜細輭桂布密，柔如狐腋白似雲。","勞將詩書投贈我，如此小惠何足論。","我有大裘君未見，寬廣和暖如陽春。","此裘非繒亦非纊，裁以法度絮以仁。","刀尺鈍拙製未畢，出亦不獨裹一身。","若令在郡得五考，與君展覆杭州人。"]', '["餘杭邑客多羇貧，其间甚者蕭與殷。","天寒身上猶衣葛，日高甑中未拂塵。","江城山寺十一月，北风吹沙雪紛紛。","賓客不见綈袍惠，黎庶未霑襦袴恩。","此时太守自慙媿，重衣複衾有餘溫。","因命染人與鍼女，先製兩裘贈二君。","吳緜細輭桂布密，柔如狐腋白似云。","勞將诗书投贈我，如此小惠何足論。","我有大裘君未见，寬廣和暖如陽春。","此裘非繒亦非纊，裁以法度絮以仁。","刀尺鈍拙製未畢，出亦不独裹一身。","若令在郡得五考，與君展覆杭州人。"]', '诗', 'shi', '', NULL, '醉後狂言酬贈蕭殷二協律 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d20ee30-f31f-42ca-9616-e35b29c5f783', '醉歌', '醉歌', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["罷胡琴，掩秦瑟，玲瓏再拜歌初畢。","誰道使君不解歌，聽唱黃雞與白日。","黃雞催曉丑時鳴，白日催年酉前沒。","腰間紅綬繫未穩，鏡裏朱顏看已失。","玲瓏玲瓏奈老何，使君歌了汝更歌。"]', '["罷胡琴，掩秦瑟，玲瓏再拜歌初畢。","誰道使君不解歌，听唱黄雞與白日。","黄雞催晓丑时鳴，白日催年酉前沒。","腰间紅綬繫未穩，镜裏朱顏看已失。","玲瓏玲瓏奈老何，使君歌了汝更歌。"]', '诗', 'shi', '', NULL, '醉歌 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4dcf8ed-501b-488a-9f96-3411d3531008', '代書詩一百韻寄微之', '代书诗一百韻寄微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憶在貞元歲，初登典校司。","身名同日授，心事一言知。","肺腑都無隔，形骸兩不羈。","疎狂屬年少，閑散爲官卑。","分定金蘭契，言通藥石規。","交賢方汲汲，友直每偲偲。","有月多同賞，無杯不共持。","秋風拂琴匣，夜雪卷書帷。","高上慈恩塔，幽尋皇子陂。","唐昌玉蘂會，崇敬牡丹期。","笑勸迂辛酒，閑吟短李詩。","儒風愛敦質，佛理賞玄師。","度日曾無悶，通宵靡不爲。","雙聲聯律句，八面對宮棊。","往往遊三省，騰騰出九逵。","寒銷直城路，春到曲江池。","樹暖枝條弱，山晴彩翠奇。","峰攢石綠點，柳宛麴塵絲。","岸草煙鋪地，園花雪壓枝。","早光紅照耀，新溜碧逶迤。","幄幕侵堤布，盤筵占地施。","徵伶皆絕藝，選伎悉名姬。","粉黛凝春態，金鈿耀水嬉。","風流誇墮髻，時世鬬啼眉。","密坐隨歡促，華尊逐勝移。","香飄歌袂動，翠落舞釵遺。","籌插紅螺椀，觥飛白玉巵。","打嫌調笑易，飲訝卷波遲。","殘席諠譁散，歸鞍酩酊騎。","酡顏烏帽側，醉袖玉鞭垂。","紫陌傳鐘鼓，紅塵塞路岐。","幾時曾蹔別，何處不相隨？","茌苒星霜換，迴環節候催。","兩衙多請告，三考欲成資。","運啓千年聖，天成萬物宜。","皆當少壯日，同惜盛明時。","光景嗟虛擲，雲霄竊暗窺。","攻文朝矻矻，講學夜孜孜。","策目穿如札，鋒毫銳若錐。","繁張獲鳥網，堅守釣魚坻。","竝受夔龍薦，齊陳鼂董詞。","萬言經濟略，三策太平基。","中第爭無敵，專場戰不疲。","輔車排勝陣，掎角搴降旗。","雙闕紛容衛，千僚儼等衰。","恩隨紫泥降，名向白麻披。","既在高科選，還從好爵縻。","東垣君諫諍，西邑我驅馳。","再喜登烏府，多慙侍赤墀。","官班分內外，遊處遂參差。","每列鵷鸞序，偏瞻獬豸姿。","簡威霜凜冽，衣彩繡葳蕤。","正色摧強禦，剛腸嫉喔咿。","常憎持祿位，不擬保妻兒。","養勇期除惡，輸忠在滅私。","下韝驚燕雀，當道懾狐貍。","南國人無怨，東臺吏不欺。","理冤多定國，切諫甚辛毗。","造次行於是，平生志在茲。","道將心共直，言與行兼危。","水暗波飜覆，山藏路險巇。","未爲明主識，已被倖臣疑。","木秀遭風折，蘭芳遇霰萎。","千鈞勢易壓，一柱力難搘。","騰口因成痏，吹毛遂得疵。","憂來吟貝錦，謫去詠江蘺。","邂逅塵中遇，殷勤馬上辭。","賈生離魏闕，王粲向荆夷。","水過清源寺，山經綺季祠。","心搖漢臯珮，淚墮峴亭碑。","驛路緣雲際，城樓枕水湄。","思鄉多繞澤，望闕獨登陴。","林晚青蕭索，江平綠渺瀰。","野秋鳴蟋蟀，沙冷聚鸕鷀。","官舍黃茅屋，人家苦竹籬。","白醪充夜酌，紅粟備晨炊。","寡鶴摧風翮，鰥魚失水鬐。","闇雛啼渴旦，涼葉墜相思。","一點寒燈滅，三聲曉角吹。","藍衫經雨故，驄馬臥霜羸。","念涸誰濡沫，嫌醒自歠醨。","耳垂無伯樂，舌在有張儀。","負氣衝星劒，傾心向日葵。","金言自銷鑠，玉性肯磷緇。","伸屈須看蠖，窮通莫問龜。","定知身是患，應用道爲醫。","想子今如彼，嗟予獨在斯。","無憀當歲杪，有夢到天涯。","坐阻連襟帶，行乖接履綦。","潤銷衣上霧，香散室中芝。","念遠緣遷貶，驚時爲別離。","素書三往復，明月七盈虧。","舊里非難到，餘歡不可追。","樹依興善老，草傍靜安衰。","前事思如昨，中懷寫向誰。","北村尋古柏，南宅訪辛夷。","此日空搔首，何人共解頤。","病多知夜永，年長覺秋悲。","不飲長如醉，加餐亦似飢。","狂吟一千字，因使寄微之。"]', '["憶在貞元歲，初登典校司。","身名同日授，心事一言知。","肺腑都無隔，形骸兩不羈。","疎狂屬年少，闲散爲官卑。","分定金蘭契，言通藥石規。","交賢方汲汲，友直每偲偲。","有月多同賞，無杯不共持。","秋风拂琴匣，夜雪卷书帷。","高上慈恩塔，幽尋皇子陂。","唐昌玉蘂會，崇敬牡丹期。","笑勸迂辛酒，闲吟短李诗。","儒风愛敦質，佛理賞玄師。","度日曾無悶，通宵靡不爲。","雙声聯律句，八面对宮棊。","往往游三省，腾腾出九逵。","寒銷直城路，春到曲江池。","樹暖枝條弱，山晴彩翠奇。","峰攢石綠点，柳宛麴塵絲。","岸草煙鋪地，园花雪壓枝。","早光紅照耀，新溜碧逶迤。","幄幕侵堤布，盤筵占地施。","徵伶皆絕藝，選伎悉名姬。","粉黛凝春態，金鈿耀水嬉。","风流誇墮髻，时世鬬啼眉。","密坐隨歡促，华尊逐勝移。","香飄歌袂动，翠落舞釵遺。","籌插紅螺椀，觥飞白玉巵。","打嫌調笑易，饮訝卷波遲。","殘席諠譁散，归鞍酩酊騎。","酡顏烏帽側，醉袖玉鞭垂。","紫陌傳鐘鼓，紅塵塞路岐。","幾时曾蹔別，何处不相隨？","茌苒星霜換，迴环節候催。","兩衙多請告，三考欲成資。","運啓千年聖，天成万物宜。","皆當少壯日，同惜盛明时。","光景嗟虛擲，云霄竊暗窺。","攻文朝矻矻，講学夜孜孜。","策目穿如札，鋒毫銳若錐。","繁張獲鸟網，堅守釣鱼坻。","竝受夔龙薦，齊陳鼂董词。","万言經濟略，三策太平基。","中第爭無敵，專場戰不疲。","輔车排勝陣，掎角搴降旗。","雙闕紛容衛，千僚儼等衰。","恩隨紫泥降，名向白麻披。","既在高科選，還從好爵縻。","东垣君諫諍，西邑我驱驰。","再喜登烏府，多慙侍赤墀。","官班分內外，游处遂參差。","每列鵷鸾序，偏瞻獬豸姿。","簡威霜凜冽，衣彩繡葳蕤。","正色摧強禦，剛腸嫉喔咿。","常憎持祿位，不擬保妻兒。","養勇期除惡，輸忠在滅私。","下韝驚燕雀，當道懾狐貍。","南国人無怨，东台吏不欺。","理冤多定国，切諫甚辛毗。","造次行於是，平生志在茲。","道將心共直，言與行兼危。","水暗波飜覆，山藏路險巇。","未爲明主識，已被倖臣疑。","木秀遭风折，蘭芳遇霰萎。","千鈞勢易壓，一柱力难搘。","腾口因成痏，吹毛遂得疵。","憂来吟貝錦，謫去詠江蘺。","邂逅塵中遇，殷勤马上辞。","賈生離魏闕，王粲向荆夷。","水過清源寺，山經綺季祠。","心搖漢臯珮，泪墮峴亭碑。","驛路緣云際，城楼枕水湄。","思乡多繞澤，望闕独登陴。","林晚青蕭索，江平綠渺瀰。","野秋鳴蟋蟀，沙冷聚鸕鷀。","官舍黄茅屋，人家苦竹籬。","白醪充夜酌，紅粟備晨炊。","寡鹤摧风翮，鰥鱼失水鬐。","闇雛啼渴旦，涼葉墜相思。","一点寒灯滅，三声晓角吹。","藍衫經雨故，驄马臥霜羸。","念涸誰濡沫，嫌醒自歠醨。","耳垂無伯乐，舌在有張儀。","負氣衝星劒，傾心向日葵。","金言自銷鑠，玉性肯磷緇。","伸屈須看蠖，窮通莫问龟。","定知身是患，應用道爲醫。","想子今如彼，嗟予独在斯。","無憀當歲杪，有梦到天涯。","坐阻連襟带，行乖接履綦。","潤銷衣上霧，香散室中芝。","念远緣遷貶，驚时爲別離。","素书三往复，明月七盈虧。","旧里非难到，餘歡不可追。","樹依兴善老，草傍静安衰。","前事思如昨，中懷寫向誰。","北村尋古柏，南宅訪辛夷。","此日空搔首，何人共解頤。","病多知夜永，年长覺秋悲。","不饮长如醉，加餐亦似飢。","狂吟一千字，因使寄微之。"]', '诗', 'shi', '', NULL, '代書詩一百韻寄微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be1503e6-a995-45e0-bcfc-347a0fbd5f2f', '和鄭元及第後秋歸洛下閑居', '和鄭元及第後秋归洛下闲居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["勤苦成名後，優游得意間。","玉憐同匠琢，桂恨隔年攀。","山靜豹難隱，谷幽鶯暫還。","微吟詩引步，淺酌酒開顏。","門迥暮臨水，窗深朝對山。","雲衢日相待，莫誤許身閑。"]', '["勤苦成名後，優游得意间。","玉怜同匠琢，桂恨隔年攀。","山静豹难隐，谷幽鶯暫還。","微吟诗引步，淺酌酒开顏。","门迥暮臨水，窗深朝对山。","云衢日相待，莫誤許身闲。"]', '诗', 'shi', '', NULL, '和鄭元及第後秋歸洛下閑居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dd27dbc-9eea-4a37-ab9e-aa2cb87bfb08', '與諸同年賀座主侍郎新拜太常同宴蕭尚書亭子', '與諸同年賀座主侍郎新拜太常同宴蕭尚书亭子', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["寵新卿典禮，會盛客徵文。","不失遷鶯侶，因成賀燕羣。","池臺晴間雪，冠蓋暮和雲。","共仰曾攀處，年深桂尚熏。"]', '["寵新卿典禮，會盛客徵文。","不失遷鶯侶，因成賀燕羣。","池台晴间雪，冠蓋暮和云。","共仰曾攀处，年深桂尚熏。"]', '诗', 'shi', '', NULL, '與諸同年賀座主侍郎新拜太常同宴蕭尚書亭子 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee0bc226-3aff-4294-98b5-40eb1358ebfd', '東都冬日會諸同年宴鄭家林亭', '东都冬日會諸同年宴鄭家林亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["盛時陪上第，暇日會羣賢。","桂折因同樹，鶯遷各異年。","賓階紛組佩，妓席儼花鈿。","促膝齊榮賤，差肩次後先。","助歌林下水，銷酒雪中天。","他日升沈者，無忘共此筵。"]', '["盛时陪上第，暇日會羣賢。","桂折因同樹，鶯遷各異年。","賓階紛組佩，妓席儼花鈿。","促膝齊榮賤，差肩次後先。","助歌林下水，銷酒雪中天。","他日升沈者，無忘共此筵。"]', '诗', 'shi', '', NULL, '東都冬日會諸同年宴鄭家林亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c63e71a-bfc5-4c8a-9545-8317db89a9cf', '敘德書情四十韻上宣歙翟中丞', '敘德书情四十韻上宣歙翟中丞', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["元聖生乘運，忠賢出應期。","還將稽古力，助立太平基。","土控吳兼越，州連歙與池。","山河地襟帶，軍鎮國藩維。","廉察安江甸，澄清肅海夷。","股肱分外守，耳目付中司。","楚老歌來暮，秦人詠去思。","望如時雨至，福是歲星移。","政靜民無訟，刑行吏不欺。","撝謙驚主寵，陰德畏人知。","白玉慙溫色，朱繩讓直辭。","行爲時領袖，言作世蓍龜。","盛幕招賢士，連營訓銳師。","光華下鵷鷺，氣色動熊羆。","出入麾幢引，登臨劒戟隨。","好風迎解榻，美景待搴帷。","晴野霞飛綺，春郊柳宛絲。","城烏驚畫角，江雁避紅旗。","藉草朱輪駐，攀花紫綬垂。","山宜謝公屐，洲稱柳家詩。","酒氣和芳杜，弦聲亂子規。","分毬齊馬首，列舞匝蛾眉。","醉惜年光晚，歡憐日影遲。","迴塘排玉櫂，歸路擁金羈。","自顧龍鍾者，嘗蒙噢咻之。","仰山塵不讓，涉海水難爲。","身忝鄉人薦，名因國士推。","提攜增善價，拂拭長妍姿。","射策端心術，遷喬整羽儀。","幸穿楊遠葉，謬折桂高枝。","佩德潛書帶，銘仁暗勒肌。","飭躬趨館舍，拜手挹階墀。","霄漢程雖在，風塵迹尚卑。","敝衣羞布素，敗屋厭茅茨。","養乏晨昏膳，居無伏臘資。","盛時貧可恥，壯歲病堪嗤。","擢第名方立，耽書力未疲。","磨鉛重剸割，策蹇再奔馳。","相馬須憐瘦，呼鷹正及飢。","扶搖重即事，會有荅恩時。"]', '["元聖生乘運，忠賢出應期。","還將稽古力，助立太平基。","土控吳兼越，州連歙與池。","山河地襟带，軍鎮国藩維。","廉察安江甸，澄清肅海夷。","股肱分外守，耳目付中司。","楚老歌来暮，秦人詠去思。","望如时雨至，福是歲星移。","政静民無訟，刑行吏不欺。","撝謙驚主寵，陰德畏人知。","白玉慙溫色，朱繩讓直辞。","行爲时領袖，言作世蓍龟。","盛幕招賢士，連營訓銳師。","光华下鵷鷺，氣色动熊羆。","出入麾幢引，登臨劒戟隨。","好风迎解榻，美景待搴帷。","晴野霞飞綺，春郊柳宛絲。","城烏驚畫角，江雁避紅旗。","藉草朱輪駐，攀花紫綬垂。","山宜謝公屐，洲稱柳家诗。","酒氣和芳杜，弦声亂子規。","分毬齊马首，列舞匝蛾眉。","醉惜年光晚，歡怜日影遲。","迴塘排玉櫂，归路擁金羈。","自顧龙鍾者，嘗蒙噢咻之。","仰山塵不讓，涉海水难爲。","身忝乡人薦，名因国士推。","提携增善價，拂拭长妍姿。","射策端心術，遷喬整羽儀。","幸穿楊远葉，謬折桂高枝。","佩德潛书带，銘仁暗勒肌。","飭躬趨館舍，拜手挹階墀。","霄漢程雖在，风塵迹尚卑。","敝衣羞布素，敗屋厭茅茨。","養乏晨昏膳，居無伏臘資。","盛时貧可恥，壯歲病堪嗤。","擢第名方立，耽书力未疲。","磨鉛重剸割，策蹇再奔驰。","相马須怜瘦，呼鷹正及飢。","扶搖重即事，會有荅恩时。"]', '诗', 'shi', '', NULL, '敘德書情四十韻上宣歙翟中丞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d673641-9811-425e-bd06-30d7dafcce13', '和渭北劉大夫借便秋遮虜寄朝中親友', '和渭北劉大夫借便秋遮虜寄朝中親友', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["巨鎮爲邦屏，全材作國楨。","韜鈐漢上將，文墨魯諸生。","豹虎關西卒，金湯渭北城。","寵深初受棨，威重正揚兵。","陣占山河布，軍諳水草行。","夏苗侵虎落，宵遁失蕃營。","雲隊攢戈戟，風行卷斾旌。","堠空烽火滅，氣勝鼓鼙鳴。","胡馬辭南牧，周師罷北征。","迴頭問天下，何處有欃槍。"]', '["巨鎮爲邦屏，全材作国楨。","韜鈐漢上將，文墨魯諸生。","豹虎关西卒，金湯渭北城。","寵深初受棨，威重正揚兵。","陣占山河布，軍諳水草行。","夏苗侵虎落，宵遁失蕃營。","云隊攢戈戟，风行卷斾旌。","堠空烽火滅，氣勝鼓鼙鳴。","胡马辞南牧，周師罷北征。","迴头问天下，何处有欃槍。"]', '诗', 'shi', '', NULL, '和渭北劉大夫借便秋遮虜寄朝中親友 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3b1a889-a678-4e76-bdb8-d2eaa8e1377d', '題故曹王宅', '題故曹王宅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["甲第何年置，朱門此地開。","山當賓閣出，溪繞妓堂迴。","覆井桐新長，陰窗竹舊栽。","池荒紅菡萏，砌老綠莓苔。","捐館梁王去，思人楚客來。","西園飛蓋處，依舊月裴回。"]', '["甲第何年置，朱门此地开。","山當賓閣出，溪繞妓堂迴。","覆井桐新长，陰窗竹旧栽。","池荒紅菡萏，砌老綠莓苔。","捐館梁王去，思人楚客来。","西园飞蓋处，依旧月裴回。"]', '诗', 'shi', '', NULL, '題故曹王宅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a93e907d-4493-4817-8471-644e8d12886d', '自江陵之徐州路上寄兄弟', '自江陵之徐州路上寄兄弟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["岐路南將北，離憂弟與兄。","關河千里別，風雪一身行。","夕宿勞鄉夢，晨裝慘旅情。","家貧憂後事，日短念前程。","煙鴈飜寒渚，霜烏聚古城。","誰憐陟岡者，西楚望南荆。"]', '["岐路南將北，離憂弟與兄。","关河千里別，风雪一身行。","夕宿勞乡梦，晨裝慘旅情。","家貧憂後事，日短念前程。","煙鴈飜寒渚，霜烏聚古城。","誰怜陟岡者，西楚望南荆。"]', '诗', 'shi', '', NULL, '自江陵之徐州路上寄兄弟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79de9132-ef7d-41be-933b-5975a4990939', '酬哥舒大見贈', '酬哥舒大见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["去歲歡遊何處去？曲江西岸杏園東。","花下忘歸因美景，尊前勸酒是春風。","各從微宦風塵裏，共度流年離別中。","今日相逢愁又喜，八人分散兩人同。"]', '["去歲歡游何处去？曲江西岸杏园东。","花下忘归因美景，尊前勸酒是春风。","各從微宦风塵裏，共度流年離別中。","今日相逢愁又喜，八人分散兩人同。"]', '诗', 'shi', '', NULL, '酬哥舒大見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdc21b7e-f366-40b6-ba46-e735209ddcbc', '和談校書秋夜感懷呈朝中親友', '和談校书秋夜感懷呈朝中親友', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["遙夜涼風楚客悲，清砧繁漏月高時。","秋霜似鬢年空長，春草如袍位尚卑。","詞賦擅名來已久，煙霄得路去何遲。","漢庭卿相皆知己，不薦揚雄欲薦誰。"]', '["遙夜涼风楚客悲，清砧繁漏月高时。","秋霜似鬢年空长，春草如袍位尚卑。","词賦擅名来已久，煙霄得路去何遲。","漢庭卿相皆知己，不薦揚雄欲薦誰。"]', '诗', 'shi', '', NULL, '和談校書秋夜感懷呈朝中親友 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('954cfeec-37cd-44aa-a7d6-d58f5838a9b5', '感秋寄遠', '感秋寄远', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["惆悵時節晚，兩情千里同。","離憂不散處，庭樹正秋風。","燕影動歸翼，蕙香銷故叢。","佳期與芳歲，牢落兩成空。"]', '["惆悵时節晚，兩情千里同。","離憂不散处，庭樹正秋风。","燕影动归翼，蕙香銷故叢。","佳期與芳歲，牢落兩成空。"]', '诗', 'shi', '', NULL, '感秋寄遠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4774c672-1e99-4a1d-b388-7c3b341c8499', '春題華陽觀', '春題华陽观', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["帝子吹簫逐鳳皇，空留仙洞號華陽。","落花何處堪惆悵，頭白宮人埽影堂。"]', '["帝子吹簫逐鳳皇，空留仙洞號华陽。","落花何处堪惆悵，头白宮人埽影堂。"]', '诗', 'shi', '', NULL, '春題華陽觀 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ec2706c-b474-43e4-a06f-bdb2b24aa7b9', '秋雨中贈元九', '秋雨中贈元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不堪紅葉青苔地，又是涼風暮雨天。","莫怪獨吟秋思苦，比君校近二毛年。"]', '["不堪紅葉青苔地，又是涼风暮雨天。","莫怪独吟秋思苦，比君校近二毛年。"]', '诗', 'shi', '', NULL, '秋雨中贈元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d61d22ec-4e21-487d-a7dc-5f8f98db83ab', '城東閑遊', '城东闲游', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["寵辱憂歡不到情，任他朝市自營營。","獨尋秋景城東去，白鹿原頭信馬行。"]', '["寵辱憂歡不到情，任他朝市自營營。","独尋秋景城东去，白鹿原头信马行。"]', '诗', 'shi', '', NULL, '城東閑遊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b14acee-b0cb-4d95-9f75-305e88d21837', '荅韋八', '荅韋八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["麗句勞相贈，佳期恨有違。","早知留酒待，悔不趁花歸。","春盡綠醅老，雨多紅萼稀。","今朝如一醉，猶得及芳菲。"]', '["丽句勞相贈，佳期恨有違。","早知留酒待，悔不趁花归。","春尽綠醅老，雨多紅萼稀。","今朝如一醉，猶得及芳菲。"]', '诗', 'shi', '', NULL, '荅韋八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c704db41-2508-4a1f-bc63-964c708285d6', '華陽觀桃花時招李六拾遺飲', '华陽观桃花时招李六拾遺饮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["華陽觀裏仙桃發，把酒看花心自知。","爭忍開時不同醉，明朝後日即空枝。"]', '["华陽观裏仙桃發，把酒看花心自知。","爭忍开时不同醉，明朝後日即空枝。"]', '诗', 'shi', '', NULL, '華陽觀桃花時招李六拾遺飲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6162b204-6640-4d84-a068-6d870b10f290', '和友人洛中春感', '和友人洛中春感', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫悲金谷園中月，莫歎天津橋上春。","若學多情尋往事，人間何處不傷神。"]', '["莫悲金谷园中月，莫歎天津橋上春。","若学多情尋往事，人间何处不傷神。"]', '诗', 'shi', '', NULL, '和友人洛中春感 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c90085e-b3c0-4c71-95fb-395232cd3933', '送張南簡入蜀', '送張南簡入蜀', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昨日詔書下，求賢訪陸沈。","無論能與否，皆起徇名心。","君獨南遊去，雲山蜀路深。"]', '["昨日詔书下，求賢訪陸沈。","無論能與否，皆起徇名心。","君独南游去，云山蜀路深。"]', '诗', 'shi', '', NULL, '送張南簡入蜀 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb7a7e89-d789-432a-a00b-e7710329c6f1', '寄陸補闕', '寄陸補闕', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["忽憶前年科第後，此時雞鶴暫同羣。","秋風惆悵須吹散，雞在中庭鶴在雲。"]', '["忽憶前年科第後，此时雞鹤暫同羣。","秋风惆悵須吹散，雞在中庭鹤在云。"]', '诗', 'shi', '', NULL, '寄陸補闕 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8f7f42a-fd85-40b0-b374-83ee63f28247', '華陽觀中八月十五日夜招友玩月', '华陽观中八月十五日夜招友玩月', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人道秋中明月好，欲邀同賞意如何。","華陽洞裏秋壇上，今夜清光此處多。"]', '["人道秋中明月好，欲邀同賞意如何。","华陽洞裏秋壇上，今夜清光此处多。"]', '诗', 'shi', '', NULL, '華陽觀中八月十五日夜招友玩月 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15938255-e44a-447c-93aa-7a657324458a', '曲江憶元九', '曲江憶元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["春來無伴閑遊少，行樂三分減二分。","何況今朝杏園裏，閑人逢盡不逢君。"]', '["春来無伴闲游少，行乐三分減二分。","何況今朝杏园裏，闲人逢尽不逢君。"]', '诗', 'shi', '', NULL, '曲江憶元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58438519-9454-428f-a313-8648598f5f89', '過劉三十二故宅', '過劉三十二故宅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不見劉君來近遠，門前兩度滿枝花。","朝來惆悵宣平過，柳巷當頭第一家。"]', '["不见劉君来近远，门前兩度满枝花。","朝来惆悵宣平過，柳巷當头第一家。"]', '诗', 'shi', '', NULL, '過劉三十二故宅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf2bb174-c237-4b8d-a9a9-17a698553cc6', '下邽莊南桃花', '下邽莊南桃花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["村南無限桃花發，唯我多情獨自來。","日暮風吹紅滿地，無人解惜爲誰開。"]', '["村南無限桃花發，唯我多情独自来。","日暮风吹紅满地，無人解惜爲誰开。"]', '诗', 'shi', '', NULL, '下邽莊南桃花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1b4e21a-27bf-47bb-a016-239ece08114b', '三月三十日題慈恩寺', '三月三十日題慈恩寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["慈恩春色今朝盡，盡日裴回倚寺門。","惆悵春歸留不得，紫藤花下漸黃昏。"]', '["慈恩春色今朝尽，尽日裴回倚寺门。","惆悵春归留不得，紫藤花下漸黄昏。"]', '诗', 'shi', '', NULL, '三月三十日題慈恩寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b07d6b8d-a5f4-466d-8e67-c7dc5f4db5c6', '看惲家牡丹花戲贈李二十', '看惲家牡丹花戲贈李二十', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["香勝燒蘭紅勝霞，城中最數令公家。","人人散後君須看，歸到江南無此花。"]', '["香勝燒蘭紅勝霞，城中最數令公家。","人人散後君須看，归到江南無此花。"]', '诗', 'shi', '', NULL, '看惲家牡丹花戲贈李二十 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f7eeffd-5f59-4e9d-a2b2-0ff35561e93c', '春中與盧四周諒華陽觀同居', '春中與盧四周諒华陽观同居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["性情嬾慢好相親，門巷蕭條稱作鄰。","背燭共憐深夜月，蹋花同惜少年春。","杏壇住僻雖宜病，芸閣官微不救貧。","文行如君尚顦顇，不知霄漢待何人。"]', '["性情嬾慢好相親，门巷蕭條稱作鄰。","背燭共怜深夜月，蹋花同惜少年春。","杏壇住僻雖宜病，芸閣官微不救貧。","文行如君尚顦顇，不知霄漢待何人。"]', '诗', 'shi', '', NULL, '春中與盧四周諒華陽觀同居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bec4f5b-2b75-4b00-8c23-6ac25ea0d08e', '自城東至以詩代書戲招李六拾遺崔二十六先輩', '自城东至以诗代书戲招李六拾遺崔二十六先輩', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["青門走馬趁心期，惆悵歸來已校遲。","應過唐昌玉蘂後，猶當崇敬牡丹時。","暫遊還憶崔先輩，欲醉先邀李拾遺。","尚殘半月芸香俸，不作歸糧作酒貲。"]', '["青门走马趁心期，惆悵归来已校遲。","應過唐昌玉蘂後，猶當崇敬牡丹时。","暫游還憶崔先輩，欲醉先邀李拾遺。","尚殘半月芸香俸，不作归糧作酒貲。"]', '诗', 'shi', '', NULL, '自城東至以詩代書戲招李六拾遺崔二十六先輩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('768175e5-04d5-47e2-bbc3-b2d90d14ffb5', '盩厔縣北樓望山', '盩厔縣北楼望山', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一爲趨走吏，塵土不開顏。","孤負平生眼，今朝始見山。"]', '["一爲趨走吏，塵土不开顏。","孤負平生眼，今朝始见山。"]', '诗', 'shi', '', NULL, '盩厔縣北樓望山 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('947db2a2-41fb-4caa-b0e1-bbed25927a99', '縣西郊秋寄贈馬造', '縣西郊秋寄贈马造', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紫閣峰西清渭東，野煙深處夕陽中。","風荷老葉蕭條綠，水蓼殘花寂寞紅。","我厭宦遊君失意，可憐秋思兩心同。"]', '["紫閣峰西清渭东，野煙深处夕陽中。","风荷老葉蕭條綠，水蓼殘花寂寞紅。","我厭宦游君失意，可怜秋思兩心同。"]', '诗', 'shi', '', NULL, '縣西郊秋寄贈馬造 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d882f4e-ce70-4336-a430-b644335028f3', '別韋蘇州', '別韋蘇州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["百年愁裏過，萬感醉中來。","惆悵城西別，愁眉兩不開。"]', '["百年愁裏過，万感醉中来。","惆悵城西別，愁眉兩不开。"]', '诗', 'shi', '', NULL, '別韋蘇州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d2a307b-1202-4a89-ba1e-34d3b51af3d5', '戲題新栽薔薇', '戲題新栽薔薇', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["移根易地莫顦顇，野外庭前一種春。","少府無妻春寂寞，花開將爾當夫人。"]', '["移根易地莫顦顇，野外庭前一種春。","少府無妻春寂寞，花开將爾當夫人。"]', '诗', 'shi', '', NULL, '戲題新栽薔薇 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('963a663b-28d3-4728-8a3a-152d54f1dfda', '酬王十八李大見招遊山', '酬王十八李大见招游山', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自憐幽會心期阻，復媿嘉招書信頻。","王事牽身去不得，滿山松雪屬他人。"]', '["自怜幽會心期阻，复媿嘉招书信頻。","王事牽身去不得，满山松雪屬他人。"]', '诗', 'shi', '', NULL, '酬王十八李大見招遊山 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5446ce84-6f79-4de1-a771-fa39a81bdc9b', '縣南花下醉中留劉五', '縣南花下醉中留劉五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["百歲幾迴同酩酊，一年今日最芳菲。","願將花贈天台女，留取劉郎到夜歸。"]', '["百歲幾迴同酩酊，一年今日最芳菲。","願將花贈天台女，留取劉郎到夜归。"]', '诗', 'shi', '', NULL, '縣南花下醉中留劉五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd0cc70d-73ab-4bd3-b5de-3d3800a8ca2b', '宿楊家', '宿楊家', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["楊氏弟兄俱醉臥，披衣獨起下高齋。","夜深不語中庭立，月照藤花影上階。"]', '["楊氏弟兄俱醉臥，披衣独起下高斋。","夜深不語中庭立，月照藤花影上階。"]', '诗', 'shi', '', NULL, '宿楊家 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ee15225-57fd-4564-8e2c-4620bfd4afb4', '醉中留別楊六兄弟', '醉中留別楊六兄弟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["春初攜手春深散，無日花間不醉狂。","別後何人堪共醉，猶殘十日好風光。"]', '["春初携手春深散，無日花间不醉狂。","別後何人堪共醉，猶殘十日好风光。"]', '诗', 'shi', '', NULL, '醉中留別楊六兄弟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d11f51f5-36f1-45b2-a040-f031c692c249', '醉中歸盩厔', '醉中归盩厔', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["金光門外昆明路，半醉騰騰信馬迴。","數日非關王事繫，牡丹花盡始歸來。"]', '["金光门外昆明路，半醉腾腾信马迴。","數日非关王事繫，牡丹花尽始归来。"]', '诗', 'shi', '', NULL, '醉中歸盩厔 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53028b2e-544e-459b-bcce-e338144fa773', '遊雲居寺贈穆三十六地主', '游云居寺贈穆三十六地主', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["亂峰深處雲居路，共蹋花行獨惜春。","勝地本來無定主，大都山屬愛山人。"]', '["亂峰深处云居路，共蹋花行独惜春。","勝地本来無定主，大都山屬愛山人。"]', '诗', 'shi', '', NULL, '遊雲居寺贈穆三十六地主 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3859bf9d-de38-42a2-81cd-d949039796f0', '和王十八薔薇澗花時有懷蕭侍御兼見贈', '和王十八薔薇澗花时有懷蕭侍御兼见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["霄漢風塵俱是繫，薔薇花委故山深。","憐君獨向澗中立，一把紅芳三處心。"]', '["霄漢风塵俱是繫，薔薇花委故山深。","怜君独向澗中立，一把紅芳三处心。"]', '诗', 'shi', '', NULL, '和王十八薔薇澗花時有懷蕭侍御兼見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('840ce0ed-eb6c-46e5-82e9-f4a8cc0f18da', '再因公事到駱口驛', '再因公事到駱口驛', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今年到時夏雲白，去年來時秋樹紅。","兩度見山心有媿，皆因王事到山中。"]', '["今年到时夏云白，去年来时秋樹紅。","兩度见山心有媿，皆因王事到山中。"]', '诗', 'shi', '', NULL, '再因公事到駱口驛 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e67b678e-4534-46bf-b632-5f235ff5bfbb', '期李二十文略王十八質夫不至獨宿仙遊寺', '期李二十文略王十八質夫不至独宿仙游寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["文略也從牽吏役，質夫何故戀囂塵。","始知解愛山中宿，千萬人中無一人。"]', '["文略也從牽吏役，質夫何故戀囂塵。","始知解愛山中宿，千万人中無一人。"]', '诗', 'shi', '', NULL, '期李二十文略王十八質夫不至獨宿仙遊寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d505db47-7a71-49b2-8fc2-8377b6867374', '酬趙秀才贈新登科諸先輩', '酬趙秀才贈新登科諸先輩', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫羨蓬萊鸞鶴侶，道成羽翼自生身。","君看名在丹臺者，盡是人間修道人。"]', '["莫羨蓬萊鸾鹤侶，道成羽翼自生身。","君看名在丹台者，尽是人间修道人。"]', '诗', 'shi', '', NULL, '酬趙秀才贈新登科諸先輩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fbf22c24-6020-4423-b6ce-2980ad7128d6', '過天門街', '過天门街', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雪盡終南又欲春，遙憐翠色對紅塵。","千車萬馬九衢上，回首看山無一人。"]', '["雪尽終南又欲春，遙怜翠色对紅塵。","千车万马九衢上，回首看山無一人。"]', '诗', 'shi', '', NULL, '過天門街 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39e149d5-4920-4e9e-addf-f6856006b0b9', '惜玉蘂花有懷集賢王校書起', '惜玉蘂花有懷集賢王校书起', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["芳意將闌風又吹，白雲離葉雪辭枝。","集賢讎校無閑日，落盡瑤花君不知。"]', '["芳意將闌风又吹，白云離葉雪辞枝。","集賢讎校無闲日，落尽瑤花君不知。"]', '诗', 'shi', '', NULL, '惜玉蘂花有懷集賢王校書起 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90c2cd6d-0584-481e-942f-4ec54f825a04', '春送盧秀才下第遊太原謁嚴尚書', '春送盧秀才下第游太原謁嚴尚书', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["未將時會合，且與俗浮沈。","鴻養青冥翮，蛟潛雲雨心。","煙郊春別遠，風磧暮程深。","墨客投何處，幷州舊翰林。"]', '["未將时會合，且與俗浮沈。","鴻養青冥翮，蛟潛云雨心。","煙郊春別远，风磧暮程深。","墨客投何处，幷州旧翰林。"]', '诗', 'shi', '', NULL, '春送盧秀才下第遊太原謁嚴尚書 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7147b2d-a269-4713-9a36-f33828741d44', '長安送柳大東歸', '长安送柳大东归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白社羈遊伴，青門遠別離。","浮名相引住，歸路不同歸。"]', '["白社羈游伴，青门远別離。","浮名相引住，归路不同归。"]', '诗', 'shi', '', NULL, '長安送柳大東歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55f9fef6-7e33-469e-b541-b7607eed2915', '送文暢上人東遊', '送文暢上人东游', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["得道即無著，隨緣西復東。","貌依年臘老，心到夜禪空。","山宿馴溪虎，江行濾水蟲。","悠悠塵客思，春滿碧雲中。"]', '["得道即無著，隨緣西复东。","貌依年臘老，心到夜禪空。","山宿馴溪虎，江行濾水蟲。","悠悠塵客思，春满碧云中。"]', '诗', 'shi', '', NULL, '送文暢上人東遊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('784ea83c-e62e-46ff-8926-61e23c29faa0', '社日關路作', '社日关路作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晚景函關路，涼風社日天。","青巖新有燕，紅樹欲無蟬。","愁立驛樓上，厭行官堠前。","蕭條秋興苦，漸近二毛年。"]', '["晚景函关路，涼风社日天。","青巖新有燕，紅樹欲無蟬。","愁立驛楼上，厭行官堠前。","蕭條秋兴苦，漸近二毛年。"]', '诗', 'shi', '', NULL, '社日關路作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('210b9f5e-908c-467f-b8e1-4f894a38debd', '重到毓村宅有感', '重到毓村宅有感', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["欲入中門淚滿巾，庭花無主兩迴春。","軒窗簾幕皆依舊，只是堂前欠一人。"]', '["欲入中门泪满巾，庭花無主兩迴春。","軒窗簾幕皆依旧，只是堂前欠一人。"]', '诗', 'shi', '', NULL, '重到毓村宅有感 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbc32292-ff89-4f1b-8696-f3bc9684faf7', '亂後過流溝寺', '亂後過流溝寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["九月徐州新戰後，悲風殺氣滿山河。","唯有流溝山下寺，門前依舊白雲多。"]', '["九月徐州新戰後，悲风殺氣满山河。","唯有流溝山下寺，门前依旧白云多。"]', '诗', 'shi', '', NULL, '亂後過流溝寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4500204-2d83-45a0-b6a8-50aa50ec086c', '歎髮落', '歎髮落', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["多病多愁心自知，行年未老髮先衰。","隨梳落去何須惜，不落終須變作絲。"]', '["多病多愁心自知，行年未老髮先衰。","隨梳落去何須惜，不落終須变作絲。"]', '诗', 'shi', '', NULL, '歎髮落 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9c7cfee-dd62-460c-b2b7-2490696deea2', '留別吳七正字', '留別吳七正字', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["成名共記甲科上，署吏同登芸閣間。","唯是塵心殊道性，秋蓬常轉水長閑。"]', '["成名共記甲科上，署吏同登芸閣间。","唯是塵心殊道性，秋蓬常轉水长闲。"]', '诗', 'shi', '', NULL, '留別吳七正字 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3f62a61-92aa-4722-ae49-30f01c03df7f', '除夜宿洺州', '除夜宿洺州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["家寄關西住，身爲河北遊。","蕭條歲除夜，旅泊在洺州。"]', '["家寄关西住，身爲河北游。","蕭條歲除夜，旅泊在洺州。"]', '诗', 'shi', '', NULL, '除夜宿洺州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71263a4a-e096-441c-a82f-02a0c483577b', '邯鄲冬至夜思家', '邯鄲冬至夜思家', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["邯鄲驛裏逢冬至，抱膝燈前影伴身。","想得家中夜深坐，還應說著遠行人。"]', '["邯鄲驛裏逢冬至，抱膝灯前影伴身。","想得家中夜深坐，還應说著远行人。"]', '诗', 'shi', '', NULL, '邯鄲冬至夜思家 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('578f99ee-4165-4bc0-8c54-d675f4fabf1c', '冬至夜懷湘靈', '冬至夜懷湘靈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["豔質無由見，寒衾不可親。","何堪最長夜，俱作獨眠人。"]', '["豔質無由见，寒衾不可親。","何堪最长夜，俱作独眠人。"]', '诗', 'shi', '', NULL, '冬至夜懷湘靈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9515a84-89a0-4245-93ea-d1e1da419f5c', '感故張僕射諸妓', '感故張僕射諸妓', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["黃金不惜買蛾眉，揀得如花三四枝。","歌舞教成心力盡，一朝身去不相隨。"]', '["黄金不惜買蛾眉，揀得如花三四枝。","歌舞教成心力尽，一朝身去不相隨。"]', '诗', 'shi', '', NULL, '感故張僕射諸妓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f50090f-1c01-4b33-bbf6-965ac5819f57', '遊仙遊山', '游仙游山', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["闇將心地出人間，五六年來人怪閑。","自嫌戀著未全盡，猶愛雲泉多在山。"]', '["闇將心地出人间，五六年来人怪闲。","自嫌戀著未全尽，猶愛云泉多在山。"]', '诗', 'shi', '', NULL, '遊仙遊山 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26c0f439-29bc-4cfb-8aef-8a3e51ee1851', '見尹公亮新詩偶贈絕句', '见尹公亮新诗偶贈絕句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["袖裏新詩十首餘，吟看句句是瓊琚。","如何持此將干謁，不及公卿一字書。"]', '["袖裏新诗十首餘，吟看句句是瓊琚。","如何持此將干謁，不及公卿一字书。"]', '诗', 'shi', '', NULL, '見尹公亮新詩偶贈絕句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50f53af5-9721-49cf-9cd0-4ca7a4cfbbb8', '長安閑居', '长安闲居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風竹松煙晝掩關，意中長似在深山。","無人不怪長安住，何獨朝朝暮暮間。"]', '["风竹松煙晝掩关，意中长似在深山。","無人不怪长安住，何独朝朝暮暮间。"]', '诗', 'shi', '', NULL, '長安閑居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47d39d91-8d2e-4bb8-b68f-98477f427f25', '早春獨遊曲江', '早春独游曲江', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["散職無羈束，羸驂少送迎。","朝從直城出，春傍曲江行。","風起池東暖，雲開山北晴。","冰銷泉脈動，雪盡草芽生。","露杏紅初坼，煙楊綠未成。","影遲新度鴈，聲澀欲啼鶯。","閑地心俱靜，韶光眼共明。","酒狂憐性逸，藥效喜身輕。","慵慢疎人事，幽棲逐野情。","迴看芸閣笑，不似有浮名。"]', '["散職無羈束，羸驂少送迎。","朝從直城出，春傍曲江行。","风起池东暖，云开山北晴。","冰銷泉脈动，雪尽草芽生。","露杏紅初坼，煙楊綠未成。","影遲新度鴈，声澀欲啼鶯。","闲地心俱静，韶光眼共明。","酒狂怜性逸，藥效喜身轻。","慵慢疎人事，幽棲逐野情。","迴看芸閣笑，不似有浮名。"]', '诗', 'shi', '', NULL, '早春獨遊曲江 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7732a927-0843-4d0f-9547-ce2b47334879', '祕書省中憶舊山', '祕书省中憶旧山', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["厭從薄宦校青簡，悔別故山思白雲。","猶喜蘭臺非傲吏，歸時應免動移文。"]', '["厭從薄宦校青簡，悔別故山思白云。","猶喜蘭台非傲吏，归时應免动移文。"]', '诗', 'shi', '', NULL, '祕書省中憶舊山 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6a9b0dc-74fc-4f16-b4f1-7a599982aac2', '涼夜有懷', '涼夜有懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["清風吹枕席，白露濕衣裳。","好是相親夜，漏遲天氣涼。"]', '["清风吹枕席，白露濕衣裳。","好是相親夜，漏遲天氣涼。"]', '诗', 'shi', '', NULL, '涼夜有懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71a9187b-d586-453c-8ee8-c244203a0de3', '送武士曹歸蜀', '送武士曹归蜀', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["花落鳥嚶嚶，南歸稱野情。","月宜秦嶺宿，春好蜀江行。","鄉路通雲棧，郊扉近錦城。","烏臺陟岡送，人羨別時榮。"]', '["花落鸟嚶嚶，南归稱野情。","月宜秦嶺宿，春好蜀江行。","乡路通云棧，郊扉近錦城。","烏台陟岡送，人羨別时榮。"]', '诗', 'shi', '', NULL, '送武士曹歸蜀 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55e096b9-a41b-47e4-8eb6-fd50581a2a68', '江南送北客因憑寄徐州兄弟書', '江南送北客因憑寄徐州兄弟书', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["故園望斷欲何如，楚水吳山萬里餘。","今日因君訪兄弟，數行鄉淚一封書。"]', '["故园望斷欲何如，楚水吳山万里餘。","今日因君訪兄弟，數行乡泪一封书。"]', '诗', 'shi', '', NULL, '江南送北客因憑寄徐州兄弟書 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0174cbbc-31fa-4daf-b1cf-7f91c6a646a9', '賦得古原草送別', '賦得古原草送別', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["離離原上草，一歲一枯榮。","野火燒不盡，春風吹又生。","遠芳侵古道，晴翠接荒城。","又送王孫去，萋萋滿別情。"]', '["離離原上草，一歲一枯榮。","野火燒不尽，春风吹又生。","远芳侵古道，晴翠接荒城。","又送王孫去，萋萋满別情。"]', '诗', 'shi', '', NULL, '賦得古原草送別 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0888ad57-fb1c-41ad-8191-df2d37e0aad1', '夜哭李夷道', '夜哭李夷道', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["逝者絕影響，空庭朝復昏。","家人哀臨畢，夜鏁壽堂門。","無妻無子何人葬，空見銘旌向月飜。"]', '["逝者絕影响，空庭朝复昏。","家人哀臨畢，夜鏁壽堂门。","無妻無子何人葬，空见銘旌向月飜。"]', '诗', 'shi', '', NULL, '夜哭李夷道 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('089fa1dd-9956-44e6-8230-2ad16b259f86', '病中作', '病中作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["久爲勞生事，不學攝生道。","年少已多病，此身豈堪老。"]', '["久爲勞生事，不学攝生道。","年少已多病，此身豈堪老。"]', '诗', 'shi', '', NULL, '病中作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b25a588e-10c2-40e6-92a4-12e0e1904a2f', '秋江晚泊', '秋江晚泊', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["扁舟泊雲島，倚櫂念鄉國。","四望不見人，煙江澹秋色。","客心貧易動，日入愁未息。"]', '["扁舟泊云島，倚櫂念乡国。","四望不见人，煙江澹秋色。","客心貧易动，日入愁未息。"]', '诗', 'shi', '', NULL, '秋江晚泊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('156a6098-8d73-48c3-91e8-ceae6aaee7df', '旅次景空寺宿幽上人院', '旅次景空寺宿幽上人院', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不與人境接，寺門開向山。","暮鐘寒鳥聚，秋雨病僧閑。","月隱雲樹外，螢飛廊宇間。","幸投花界宿，暫得靜心顏。"]', '["不與人境接，寺门开向山。","暮鐘寒鸟聚，秋雨病僧闲。","月隐云樹外，螢飞廊宇间。","幸投花界宿，暫得静心顏。"]', '诗', 'shi', '', NULL, '旅次景空寺宿幽上人院 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('825a3fa6-f22a-406d-88c4-6417a218f417', '長安正月十五日', '长安正月十五日', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["諠諠車騎帝王州，羇病無心逐勝遊。","明月春風三五夜，萬人行樂一人愁。"]', '["諠諠车騎帝王州，羇病無心逐勝游。","明月春风三五夜，万人行乐一人愁。"]', '诗', 'shi', '', NULL, '長安正月十五日 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2437cd98-fd11-4eab-be03-636f1ac08e54', '過高將軍墓', '過高將軍墓', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["原上新墳委一身，城中舊宅有何人。","妓堂賓閣無歸日，野草山花又欲春。","門客空將感恩淚，白楊風裏一霑巾。"]', '["原上新墳委一身，城中旧宅有何人。","妓堂賓閣無归日，野草山花又欲春。","门客空將感恩泪，白楊风裏一霑巾。"]', '诗', 'shi', '', NULL, '過高將軍墓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1ea01a1-a614-455d-afc8-3ccf1150f620', '寒食臥病', '寒食臥病', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["病逢佳節長歎息，春雨濛濛榆柳色。","羸坐全非舊日容，扶行半是他人力。","諠諠里巷蹋青歸，笑閉柴門度寒食。"]', '["病逢佳節长歎息，春雨濛濛榆柳色。","羸坐全非旧日容，扶行半是他人力。","諠諠里巷蹋青归，笑閉柴门度寒食。"]', '诗', 'shi', '', NULL, '寒食臥病 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67c19865-9ca0-4e55-b73a-1d613ef41890', '宿桐廬館同崔存度醉後作', '宿桐廬館同崔存度醉後作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江海漂漂共旅遊，一尊相勸散窮愁。","夜深醒後愁還在，雨滴梧桐山館秋。"]', '["江海漂漂共旅游，一尊相勸散窮愁。","夜深醒後愁還在，雨滴梧桐山館秋。"]', '诗', 'shi', '', NULL, '宿桐廬館同崔存度醉後作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93f9ba05-054c-4c81-b9b0-6f20403c10ae', '江樓望歸', '江楼望归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["滿眼雲水色，月明樓上人。","旅愁春入越，鄉夢夜歸秦。","道路通荒服，田園隔虜塵。","悠悠滄海畔，十載避黃巾。"]', '["满眼云水色，月明楼上人。","旅愁春入越，乡梦夜归秦。","道路通荒服，田园隔虜塵。","悠悠滄海畔，十載避黄巾。"]', '诗', 'shi', '', NULL, '江樓望歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0daf2c4f-321f-44c3-a6c3-eb6576a3aadf', '除夜寄弟妹', '除夜寄弟妹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["感時思弟妹，不寐百憂生。","萬里經年別，孤燈此夜情。","病容非舊日，歸思逼新正。","早晚重歡會，羇離各長成。"]', '["感时思弟妹，不寐百憂生。","万里經年別，孤灯此夜情。","病容非旧日，归思逼新正。","早晚重歡會，羇離各长成。"]', '诗', 'shi', '', NULL, '除夜寄弟妹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3970bdf-c421-41b9-b6da-d5f57437c3cd', '寒食月夜', '寒食月夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風香露重棃花濕，草舍無燈愁未入。","南鄰北里歌吹時，獨倚柴門月中立。"]', '["风香露重棃花濕，草舍無灯愁未入。","南鄰北里歌吹时，独倚柴门月中立。"]', '诗', 'shi', '', NULL, '寒食月夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('537740ce-d87e-4cf2-a93d-6b9999b42327', '感芍藥花寄正一上人', '感芍藥花寄正一上人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今日階前紅芍藥，幾花欲老幾花新。","開時不解比色相，落後始知如幻身。","空門此去幾多地，欲把殘花問上人。"]', '["今日階前紅芍藥，幾花欲老幾花新。","开时不解比色相，落後始知如幻身。","空门此去幾多地，欲把殘花问上人。"]', '诗', 'shi', '', NULL, '感芍藥花寄正一上人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ae0baa0-f15e-4820-b606-0b873a659e72', '晚秋閑居', '晚秋闲居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["地僻門深少送迎，披衣閑坐養幽情。","秋庭不埽攜藤杖，閑蹋梧桐黃葉行。"]', '["地僻门深少送迎，披衣闲坐養幽情。","秋庭不埽携藤杖，闲蹋梧桐黄葉行。"]', '诗', 'shi', '', NULL, '晚秋閑居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8143158-8575-48b1-ac8f-146fdb10c033', '秋暮郊居書懷', '秋暮郊居书懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["郊居人事少，晝臥對林巒。","窮巷厭多雨，貧家愁早寒。","葛衣秋未換，書卷病仍看。","若問生涯計，前溪一釣竿。"]', '["郊居人事少，晝臥对林巒。","窮巷厭多雨，貧家愁早寒。","葛衣秋未換，书卷病仍看。","若问生涯計，前溪一釣竿。"]', '诗', 'shi', '', NULL, '秋暮郊居書懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85a8c5b3-509e-4215-b4cc-e388a21558d3', '爲薛台悼亡', '爲薛台悼亡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["半死梧桐老病身，重泉一念一傷神。","手攜穉子夜歸院，月冷空房不見人。"]', '["半死梧桐老病身，重泉一念一傷神。","手携穉子夜归院，月冷空房不见人。"]', '诗', 'shi', '', NULL, '爲薛台悼亡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f91dac01-51cd-430a-8e08-69634bbcd958', '途中寒食', '途中寒食', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["路傍寒食行人盡，獨占春愁在路旁。","馬上垂鞭愁不語，風吹百草野田香。"]', '["路傍寒食行人尽，独占春愁在路旁。","马上垂鞭愁不語，风吹百草野田香。"]', '诗', 'shi', '', NULL, '途中寒食 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('016f4ae1-2782-47a6-9290-5956da3a2126', '題流溝寺古松', '題流溝寺古松', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["煙葉蔥蘢蒼麈尾，霜皮剝落紫龍鱗。","欲知松老看塵壁，死却題詩幾許人。"]', '["煙葉蔥蘢蒼麈尾，霜皮剝落紫龙鱗。","欲知松老看塵壁，死却題诗幾許人。"]', '诗', 'shi', '', NULL, '題流溝寺古松 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7f6b674-6f0b-47a1-9ad7-5c2084a8f544', '感月悲逝者', '感月悲逝者', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["存亡感月一潸然，月色今宵似往年。","何處曾經同望月？櫻桃樹下後堂前。"]', '["存亡感月一潸然，月色今宵似往年。","何处曾經同望月？櫻桃樹下後堂前。"]', '诗', 'shi', '', NULL, '感月悲逝者 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc28d8c0-ca9d-4418-a3d7-73f23c300a35', '代鄰叟言懷', '代鄰叟言懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人生何事心無定，宿昔如今意不同。","宿昔愁身不得老，如今恨作白頭翁。"]', '["人生何事心無定，宿昔如今意不同。","宿昔愁身不得老，如今恨作白头翁。"]', '诗', 'shi', '', NULL, '代鄰叟言懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2aed629-465d-412c-a68d-780068488725', '自河南經亂關內阻饑兄弟離散各在一處因望月有感聊書所懷寄上浮梁大兄於潛七兄烏江十五兄兼示符離及下邽弟妹', '自河南經亂关內阻饑兄弟離散各在一处因望月有感聊书所懷寄上浮梁大兄於潛七兄烏江十五兄兼示符離及下邽弟妹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["時難年饑世業空，弟兄羇旅各西東。","田園寥落干戈後，骨肉流離道路中。","弔影分爲千里鴈，辭根散作九秋蓬。","共看明月應垂淚，一夜鄉心五處同。"]', '["时难年饑世業空，弟兄羇旅各西东。","田园寥落干戈後，骨肉流離道路中。","弔影分爲千里鴈，辞根散作九秋蓬。","共看明月應垂泪，一夜乡心五处同。"]', '诗', 'shi', '', NULL, '自河南經亂關內阻饑兄弟離散各在一處因望月有感聊書所懷寄上浮梁大兄於潛七兄烏江十五兄兼示符離及下邽弟妹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d80fa8fd-ecec-4c5a-9b04-108dc495562b', '長安早春旅懷', '长安早春旅懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["軒車歌吹諠都邑，中有一人向隅立。","夜深明月卷簾愁，日暮青山望鄉泣。","風吹新綠草芽坼，雨灑輕黃柳條濕。","此生知負少年春，不展愁眉欲三十。"]', '["軒车歌吹諠都邑，中有一人向隅立。","夜深明月卷簾愁，日暮青山望乡泣。","风吹新綠草芽坼，雨灑轻黄柳條濕。","此生知負少年春，不展愁眉欲三十。"]', '诗', 'shi', '', NULL, '長安早春旅懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3020bd5c-547a-4624-be07-7e59be430879', '寒閨夜', '寒閨夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜半衾裯冷，孤眠嬾未能。","籠香銷盡火，巾淚滴成冰。","爲惜影相伴，通宵不滅燈。"]', '["夜半衾裯冷，孤眠嬾未能。","籠香銷尽火，巾泪滴成冰。","爲惜影相伴，通宵不滅灯。"]', '诗', 'shi', '', NULL, '寒閨夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cf12c73-a403-4d2f-bfa4-392e5c843745', '寄湘靈', '寄湘靈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["淚眼凌寒凍不流，每經高處即迴頭。","遙知別後西樓上，應凭闌干獨自愁。"]', '["泪眼凌寒凍不流，每經高处即迴头。","遙知別後西楼上，應凭闌干独自愁。"]', '诗', 'shi', '', NULL, '寄湘靈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('609cfa44-628d-4344-91bd-ca03998bf52e', '冬至宿楊梅館', '冬至宿楊梅館', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["十一月中長至夜，三千里外遠行人。","若爲獨宿楊梅館，冷枕單牀一病身。"]', '["十一月中长至夜，三千里外远行人。","若爲独宿楊梅館，冷枕單牀一病身。"]', '诗', 'shi', '', NULL, '冬至宿楊梅館 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e0d4326-adc3-4b6e-933f-a9458d1bc218', '臨江送夏瞻', '臨江送夏瞻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["悲君老別我霑巾，七十無家萬里身。","愁見舟行風又起，白頭浪裏白頭人。"]', '["悲君老別我霑巾，七十無家万里身。","愁见舟行风又起，白头浪裏白头人。"]', '诗', 'shi', '', NULL, '臨江送夏瞻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d9e1245-88cb-4514-92ed-cdb509610832', '冬夜示敏巢', '冬夜示敏巢', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["爐火欲銷燈欲盡，夜長相對百憂生。","他時諸處重相見，莫忘今宵燈下情。"]', '["爐火欲銷灯欲尽，夜长相对百憂生。","他时諸处重相见，莫忘今宵灯下情。"]', '诗', 'shi', '', NULL, '冬夜示敏巢 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c807344-e349-4e3b-a5d4-baa81b8a80b6', '客中守歲', '客中守歲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["守歲尊無酒，思鄉淚滿巾。","始知爲客苦，不及在家貧。","畏老偏驚節，防愁預惡春。","故園今夜裏，應念未歸人。"]', '["守歲尊無酒，思乡泪满巾。","始知爲客苦，不及在家貧。","畏老偏驚節，防愁預惡春。","故园今夜裏，應念未归人。"]', '诗', 'shi', '', NULL, '客中守歲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('601def97-8e7b-4652-8d3a-4bd61095a324', '問淮水', '问淮水', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自嗟名利客，擾擾在人間。","何事長淮水，東流亦不閑。"]', '["自嗟名利客，擾擾在人间。","何事长淮水，东流亦不闲。"]', '诗', 'shi', '', NULL, '問淮水 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('580ebee8-68e3-4109-8918-4f1d7dd2f629', '宿樟亭驛', '宿樟亭驛', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜半樟亭驛，愁人起望鄉。","月明何所見，潮水白茫茫。"]', '["夜半樟亭驛，愁人起望乡。","月明何所见，潮水白茫茫。"]', '诗', 'shi', '', NULL, '宿樟亭驛 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05e38f80-0b14-483a-9e1a-6965c4984106', '及第後憶舊山', '及第後憶旧山', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["偶獻子虛登上第，却吟招隱憶中林。","春蘿秋桂莫惆悵，縱有浮名不繫心。"]', '["偶獻子虛登上第，却吟招隐憶中林。","春蘿秋桂莫惆悵，縱有浮名不繫心。"]', '诗', 'shi', '', NULL, '及第後憶舊山 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('595930ed-7fbc-4f25-b790-93648a05bc63', '題李次雲窗竹', '題李次云窗竹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不用裁爲鳴鳳管，不須截作釣魚竿。","千花百草凋零後，留向紛紛雪裏看。"]', '["不用裁爲鳴鳳管，不須截作釣鱼竿。","千花百草凋零後，留向紛紛雪裏看。"]', '诗', 'shi', '', NULL, '題李次雲窗竹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1105b43-ccd1-443b-89e3-53c421ac386c', '花下自勸酒', '花下自勸酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["酒醆酌來須滿滿，花枝看即落紛紛。","莫言三十是年少，百歲三分已一分。"]', '["酒醆酌来須满满，花枝看即落紛紛。","莫言三十是年少，百歲三分已一分。"]', '诗', 'shi', '', NULL, '花下自勸酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38747045-e685-40fe-a4a4-2746764298cb', '題李十一東亭', '題李十一东亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["相思夕上松臺立，蛩思蟬聲滿耳秋。","惆悵東亭風月好，主人今夜在鄜州。"]', '["相思夕上松台立，蛩思蟬声满耳秋。","惆悵东亭风月好，主人今夜在鄜州。"]', '诗', 'shi', '', NULL, '題李十一東亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6056cb61-9be4-4598-8aed-e474cdb71104', '春村', '春村', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["二月村園暖，桑間戴勝飛。","農夫舂舊穀，蠶妾擣新衣。","牛馬因風遠，雞豚過社稀。","黃昏林下路，鼓笛賽神歸。"]', '["二月村园暖，桑间戴勝飞。","農夫舂旧穀，蠶妾擣新衣。","牛马因风远，雞豚過社稀。","黄昏林下路，鼓笛賽神归。"]', '诗', 'shi', '', NULL, '春村 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84a7d924-e13f-4a58-8ace-df9a24a5ea26', '題施山人野居', '題施山人野居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["得道應無著，謀生亦不妨。","春泥秧稻暖，夜火焙茶香。","水巷風塵少，松齋日月長。"]', '["得道應無著，謀生亦不妨。","春泥秧稻暖，夜火焙茶香。","水巷风塵少，松斋日月长。"]', '诗', 'shi', '', NULL, '題施山人野居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55824cb3-1454-4a9f-b201-6fa551f8dddc', '翰林中送獨孤二十七起居罷職出院', '翰林中送独孤二十七起居罷職出院', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["碧落留雲住，青冥放鶴還。","銀臺向南路，從此到人間。"]', '["碧落留云住，青冥放鹤還。","銀台向南路，從此到人间。"]', '诗', 'shi', '', NULL, '翰林中送獨孤二十七起居罷職出院 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7783948d-a789-4a9c-956d-1bc29dcd4eb8', '重尋杏園', '重尋杏园', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["忽憶芳時頻酩酊，却尋醉處重裴回。","杏花結子春深後，誰解多情又獨來。"]', '["忽憶芳时頻酩酊，却尋醉处重裴回。","杏花結子春深後，誰解多情又独来。"]', '诗', 'shi', '', NULL, '重尋杏園 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f967f283-a5d7-4c4c-be64-5a2d4c49d162', '曲江獨行', '曲江独行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["獨來獨去何人識，廐馬朝衣野客心。","閑愛無風水邊坐，楊花不動樹陰陰。"]', '["独来独去何人識，廐马朝衣野客心。","闲愛無风水邊坐，楊花不动樹陰陰。"]', '诗', 'shi', '', NULL, '曲江獨行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43a45a77-20d2-406c-9684-e79cc3b86352', '同李十一醉憶元九', '同李十一醉憶元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["花時同醉破春愁，醉折花枝當酒籌。","忽憶故人天際去，計程今日到涼州。"]', '["花时同醉破春愁，醉折花枝當酒籌。","忽憶故人天際去，計程今日到涼州。"]', '诗', 'shi', '', NULL, '同李十一醉憶元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('304f8683-291a-4cf7-b016-597fe2693367', '同錢員外題絕糧僧巨川', '同錢員外題絕糧僧巨川', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三十年來坐對山，唯將無事化人間。","齋時往往聞鐘笑，一食何如不食閑。"]', '["三十年来坐对山，唯將無事化人间。","斋时往往闻鐘笑，一食何如不食闲。"]', '诗', 'shi', '', NULL, '同錢員外題絕糧僧巨川 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccd01643-9cd7-4802-9cd4-c980d30b22bb', '絕句代書贈錢員外', '絕句代书贈錢員外', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["欲尋秋景閑行去，君病多慵我興孤。","可惜今朝山最好，強能騎馬出來無。"]', '["欲尋秋景闲行去，君病多慵我兴孤。","可惜今朝山最好，強能騎马出来無。"]', '诗', 'shi', '', NULL, '絕句代書贈錢員外 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93ebcf21-bc20-41cb-98f5-d2852b7d84cf', '晚秋有懷鄭中舊隱', '晚秋有懷鄭中旧隐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天高風嫋嫋，鄉思繞關河。","寥落歸山夢，殷勤采蕨歌。","病添心寂寞，愁人鬢蹉跎。","晚樹蟬鳴少，秋階日上多。","長閑羨雲鶴，久別媿煙蘿。","其奈丹墀上，君恩未報何。"]', '["天高风嫋嫋，乡思繞关河。","寥落归山梦，殷勤采蕨歌。","病添心寂寞，愁人鬢蹉跎。","晚樹蟬鳴少，秋階日上多。","长闲羨云鹤，久別媿煙蘿。","其奈丹墀上，君恩未報何。"]', '诗', 'shi', '', NULL, '晚秋有懷鄭中舊隱 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e60181d-a16b-4261-89b7-a3814a52a107', '禁中九日對菊花酒憶元九', '禁中九日对菊花酒憶元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["賜酒盈杯誰共持，宮花滿把獨相思。","相思只傍花邊立，盡日吟君詠菊詩。"]', '["賜酒盈杯誰共持，宮花满把独相思。","相思只傍花邊立，尽日吟君詠菊诗。"]', '诗', 'shi', '', NULL, '禁中九日對菊花酒憶元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9211f33e-c2d8-4c9a-850e-f148d5b6ec63', '送王十八歸山寄題仙遊寺', '送王十八归山寄題仙游寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曾於太白峰前住，數到仙遊寺裏來。","黑水澄時潭底出，白雲破處洞門開。","林間暖酒燒紅葉，石上題詩埽綠苔。","惆悵舊遊那復到，菊花時節羨君迴。"]', '["曾於太白峰前住，數到仙游寺裏来。","黑水澄时潭底出，白云破处洞门开。","林间暖酒燒紅葉，石上題诗埽綠苔。","惆悵旧游那复到，菊花时節羨君迴。"]', '诗', 'shi', '', NULL, '送王十八歸山寄題仙遊寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad6d44e4-08d7-4507-bc67-513d33273aed', '荅張籍因以代書', '荅張籍因以代书', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憐君馬瘦衣裘薄，許到江東訪鄙夫。","今日正閑天又暖，可能扶病暫來無。"]', '["怜君马瘦衣裘薄，許到江东訪鄙夫。","今日正闲天又暖，可能扶病暫来無。"]', '诗', 'shi', '', NULL, '荅張籍因以代書 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('810e7992-aaa0-4676-9848-1b7ff4a07333', '曲江早春', '曲江早春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曲江柳條漸無力，杏園伯勞初有聲。","可憐春淺遊人少，好傍池邊下馬行。"]', '["曲江柳條漸無力，杏园伯勞初有声。","可怜春淺游人少，好傍池邊下马行。"]', '诗', 'shi', '', NULL, '曲江早春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66c455d9-b0a8-44fb-9d34-df66edb1171e', '見元九悼亡詩因以此寄', '见元九悼亡诗因以此寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜淚闇銷明月幌，春腸遙斷牡丹庭。","人間此病治無藥，唯有楞伽四卷經。"]', '["夜泪闇銷明月幌，春腸遙斷牡丹庭。","人间此病治無藥，唯有楞伽四卷經。"]', '诗', 'shi', '', NULL, '見元九悼亡詩因以此寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1e20b02-4a0a-4864-acbf-7eb7e2fab11b', '寒食夜', '寒食夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["無月無燈寒食夜，夜深猶立闇花前。","忽因時節驚年幾，四十如今欠一年。"]', '["無月無灯寒食夜，夜深猶立闇花前。","忽因时節驚年幾，四十如今欠一年。"]', '诗', 'shi', '', NULL, '寒食夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc148eac-89de-40b6-bdd3-3fae742bb536', '杏園花落時招錢員外同醉', '杏园花落时招錢員外同醉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["花園欲去去應遲，正是風吹狼藉時。","近西數樹猶堪醉，半落春風半在枝。"]', '["花园欲去去應遲，正是风吹狼藉时。","近西數樹猶堪醉，半落春风半在枝。"]', '诗', 'shi', '', NULL, '杏園花落時招錢員外同醉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d69e95a-6ee3-49b9-9d30-a00d03946158', '重題西明寺牡丹', '重題西明寺牡丹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["往年君向東都去，曾歎花時君未迴。","今年況作江陵別，惆悵花前又獨來。","只愁離別長如此，不道明年花不開。"]', '["往年君向东都去，曾歎花时君未迴。","今年況作江陵別，惆悵花前又独来。","只愁離別长如此，不道明年花不开。"]', '诗', 'shi', '', NULL, '重題西明寺牡丹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('237abf24-3eae-42ff-8635-fe4328a75036', '同錢員外禁中夜直', '同錢員外禁中夜直', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["宮漏三聲知半夜，好風涼月滿松筠。","此時閑坐寂無語，藥樹影中唯兩人。"]', '["宮漏三声知半夜，好风涼月满松筠。","此时闲坐寂無語，藥樹影中唯兩人。"]', '诗', 'shi', '', NULL, '同錢員外禁中夜直 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1269f80-9c23-43de-a977-5d35cc637c95', '禁中夜作書與元九', '禁中夜作书與元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["心緒萬端書兩紙，欲封重讀意遲遲。","五聲宮漏初鳴夜，一點窗燈欲滅時。"]', '["心緒万端书兩紙，欲封重读意遲遲。","五声宮漏初鳴夜，一点窗灯欲滅时。"]', '诗', 'shi', '', NULL, '禁中夜作書與元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7a3e012-1956-42e6-ab05-24207d568992', '八月十五日夜禁中獨直對月憶元九', '八月十五日夜禁中独直对月憶元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["銀臺金闕夕沈沈，獨宿相思在翰林。","三五夜中新月色，二千里外故人心。","渚宮東面煙波冷，浴殿西頭鐘漏深。","猶恐清光不同見，江陵卑濕足秋陰。"]', '["銀台金闕夕沈沈，独宿相思在翰林。","三五夜中新月色，二千里外故人心。","渚宮东面煙波冷，浴殿西头鐘漏深。","猶恐清光不同见，江陵卑濕足秋陰。"]', '诗', 'shi', '', NULL, '八月十五日夜禁中獨直對月憶元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb03ba1f-cc1e-445d-b75e-e8858f7cc432', '寄陳式五兄', '寄陳式五兄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["年來白髮兩三莖，憶別君時髭未生。","惆悵料君應滿鬢，當初是我十年兄。"]', '["年来白髮兩三莖，憶別君时髭未生。","惆悵料君應满鬢，當初是我十年兄。"]', '诗', 'shi', '', NULL, '寄陳式五兄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60813964-f20e-4f14-82cd-61da369ce91b', '庾順之以紫霞綺遠贈以詩荅之', '庾順之以紫霞綺远贈以诗荅之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["千里故人心鄭重，一端香綺紫氛氳。","開緘日映晚霞色，滿幅風生秋水紋。","爲褥欲裁憐葉破，製裘將翦惜花分。","不如縫作合歡被，寤寐相思如對君。"]', '["千里故人心鄭重，一端香綺紫氛氳。","开緘日映晚霞色，满幅风生秋水紋。","爲褥欲裁怜葉破，製裘將翦惜花分。","不如縫作合歡被，寤寐相思如对君。"]', '诗', 'shi', '', NULL, '庾順之以紫霞綺遠贈以詩荅之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f618883-3dab-44ee-8ed4-aba84facac67', '送元八歸鳳翔', '送元八归鳳翔', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫道岐州三日程，其如風雪一身行。","與君況是經年別，暫到城來又出城。"]', '["莫道岐州三日程，其如风雪一身行。","與君況是經年別，暫到城来又出城。"]', '诗', 'shi', '', NULL, '送元八歸鳳翔 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dd3f276-ac7e-4025-aba2-0df7fab25f24', '雨雪放朝因懷微之', '雨雪放朝因懷微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["歸騎紛紛滿九衢，放朝三日爲泥塗。","不知雨雪江陵府，今日排衙得免無。"]', '["归騎紛紛满九衢，放朝三日爲泥塗。","不知雨雪江陵府，今日排衙得免無。"]', '诗', 'shi', '', NULL, '雨雪放朝因懷微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e295054-0f2f-4982-aaec-366ca9202f5a', '詠懷', '詠懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["歲去年來塵土中，眼看變作白頭翁。","如何辦得歸山計，兩頃村田一畝宮。"]', '["歲去年来塵土中，眼看变作白头翁。","如何辦得归山計，兩頃村田一畝宮。"]', '诗', 'shi', '', NULL, '詠懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58f17350-f21c-4d9e-948e-43b46bd16ff8', '聞微之江陵臥病以大通中散碧腴垂雲膏寄之因題四韻', '闻微之江陵臥病以大通中散碧腴垂云膏寄之因題四韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["已題一帖紅消散，又封一合碧雲英。","憑人寄向江陵去，道路迢迢一月程。","未必能治江上瘴，且圖遙慰病中情。","到時想得君拈得，枕上開看眼暫明。"]', '["已題一帖紅消散，又封一合碧云英。","憑人寄向江陵去，道路迢迢一月程。","未必能治江上瘴，且圖遙慰病中情。","到时想得君拈得，枕上开看眼暫明。"]', '诗', 'shi', '', NULL, '聞微之江陵臥病以大通中散碧腴垂雲膏寄之因題四韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('168419ec-0b03-4000-90f7-1c43149728b8', '酬錢員外雪中見寄', '酬錢員外雪中见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["松雪無塵小院寒，閉門不似住長安。","煩君想我看心坐，報道心空無可看。"]', '["松雪無塵小院寒，閉门不似住长安。","煩君想我看心坐，報道心空無可看。"]', '诗', 'shi', '', NULL, '酬錢員外雪中見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cc4af70-5655-44db-8511-53517c42fc7f', '重酬錢員外', '重酬錢員外', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雪中重寄雪山偈，問荅殷勤四句中。","本立空名緣破妄，若能無妄亦無空。"]', '["雪中重寄雪山偈，问荅殷勤四句中。","本立空名緣破妄，若能無妄亦無空。"]', '诗', 'shi', '', NULL, '重酬錢員外 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2afa5cca-9319-411f-ad72-11e5a11e97c9', '獨酌憶微之', '独酌憶微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["獨酌花前醉憶君，與君春別又逢春。","惆悵銀杯來處重，不曾盛酒勸閑人。"]', '["独酌花前醉憶君，與君春別又逢春。","惆悵銀杯来处重，不曾盛酒勸闲人。"]', '诗', 'shi', '', NULL, '獨酌憶微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80edff94-1b97-4690-b151-cb189f6dc5d2', '微之宅殘牡丹', '微之宅殘牡丹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["殘紅零落無人賞，雨打風摧花不全。","諸處見時猶悵望，況當元九小亭前。"]', '["殘紅零落無人賞，雨打风摧花不全。","諸处见时猶悵望，況當元九小亭前。"]', '诗', 'shi', '', NULL, '微之宅殘牡丹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aa297dc-1cd5-42cf-816f-c6aab12dc017', '新磨鏡', '新磨镜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["衰容常晚櫛，秋鏡偶新磨。","一與清光對，方知白髮多。","鬢毛從幻化，心地付頭陀。","任意渾成雪，其如似夢何。"]', '["衰容常晚櫛，秋镜偶新磨。","一與清光对，方知白髮多。","鬢毛從幻化，心地付头陀。","任意渾成雪，其如似梦何。"]', '诗', 'shi', '', NULL, '新磨鏡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c073e464-17fb-4dd6-8ccc-f35b4e08a873', '感髮落', '感髮落', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昔日愁頭白，誰知未白衰。","眼看應落盡，無可變成絲。"]', '["昔日愁头白，誰知未白衰。","眼看應落尽，無可变成絲。"]', '诗', 'shi', '', NULL, '感髮落 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('061aed4b-2f05-4e1d-9ab1-ac0b57b8eece', '八月十五日夜聞崔大員外翰林獨直對酒玩月因懷禁中清景偶題是詩', '八月十五日夜闻崔大員外翰林独直对酒玩月因懷禁中清景偶題是诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秋月高懸空碧外，仙郎靜玩禁闈間。","歲中唯有今宵好，海內無如此地閑。","皓色分明雙闕牓，清光深到九門關。","遙聞獨醉還惆悵，不見金波照玉山。"]', '["秋月高懸空碧外，仙郎静玩禁闈间。","歲中唯有今宵好，海內無如此地闲。","皓色分明雙闕牓，清光深到九门关。","遙闻独醉還惆悵，不见金波照玉山。"]', '诗', 'shi', '', NULL, '八月十五日夜聞崔大員外翰林獨直對酒玩月因懷禁中清景偶題是詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f020464b-af2d-427b-b387-c5bd01b9cd25', '酬王十八見寄', '酬王十八见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秋思太白峰頭雪，晴憶仙遊洞口雲。","未報皇恩歸未得，慙君爲寄北山文。"]', '["秋思太白峰头雪，晴憶仙游洞口云。","未報皇恩归未得，慙君爲寄北山文。"]', '诗', 'shi', '', NULL, '酬王十八見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9ca7e25-5fb0-40ed-a1ff-8d35cc5bf2e4', '立春日酬錢員外曲江同行見贈', '立春日酬錢員外曲江同行见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["下直遇春日，垂鞭出禁闈。","兩人攜手語，十里看山歸。","柳色早黃淺，水文新綠微。","風光向晚好，車馬近南稀。","機盡笑相顧，不驚鷗鷺飛。"]', '["下直遇春日，垂鞭出禁闈。","兩人携手語，十里看山归。","柳色早黄淺，水文新綠微。","风光向晚好，车马近南稀。","機尽笑相顧，不驚鷗鷺飞。"]', '诗', 'shi', '', NULL, '立春日酬錢員外曲江同行見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e155564-60d5-46eb-9b84-f03368126ec5', '和錢員外青龍寺上方望舊山', '和錢員外青龙寺上方望旧山', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["舊峰松雪舊溪雲，悵望今朝遙屬君。","共道使臣非俗吏，南山莫動北山文。"]', '["旧峰松雪旧溪云，悵望今朝遙屬君。","共道使臣非俗吏，南山莫动北山文。"]', '诗', 'shi', '', NULL, '和錢員外青龍寺上方望舊山 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c64ae43-ddd2-48e6-8869-a1ba18943260', '宴周皓大夫光福宅', '宴周皓大夫光福宅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處風光最可憐？妓堂階下砌臺前。","軒車擁路光照地，絲管入門聲沸天。","綠蕙不香饒桂酒，紅櫻無色讓花鈿。","野人不敢求他事，唯借泉聲伴醉眠。"]', '["何处风光最可怜？妓堂階下砌台前。","軒车擁路光照地，絲管入门声沸天。","綠蕙不香饒桂酒，紅櫻無色讓花鈿。","野人不敢求他事，唯借泉声伴醉眠。"]', '诗', 'shi', '', NULL, '宴周皓大夫光福宅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05fb5739-287d-4a55-9fc3-3c857d72392d', '晚秋夜', '晚秋夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["碧空溶溶月華靜，月裏愁人弔孤影。","花開殘菊傍疎籬，葉下衰桐落寒井。","塞鴻飛急覺秋盡，鄰雞鳴遲知夜永。","凝情不語空所思，風吹白露衣裳冷。"]', '["碧空溶溶月华静，月裏愁人弔孤影。","花开殘菊傍疎籬，葉下衰桐落寒井。","塞鴻飞急覺秋尽，鄰雞鳴遲知夜永。","凝情不語空所思，风吹白露衣裳冷。"]', '诗', 'shi', '', NULL, '晚秋夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e83e9a4d-282b-4ef9-bda7-c727c4060380', '惜牡丹花二首 一', '惜牡丹花二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["惆悵階前紅牡丹，晚來唯有兩枝殘。","明朝風起應吹盡，夜惜衰紅把火看。"]', '["惆悵階前紅牡丹，晚来唯有兩枝殘。","明朝风起應吹尽，夜惜衰紅把火看。"]', '诗', 'shi', '', NULL, '惜牡丹花二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71d54a43-afd1-4ac2-8e8b-573056da74b4', '惜牡丹花二首 二', '惜牡丹花二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["寂寞萎紅低向雨，離披破豔散隨風。","晴明落地猶惆悵，何況飄零泥土中。"]', '["寂寞萎紅低向雨，離披破豔散隨风。","晴明落地猶惆悵，何況飄零泥土中。"]', '诗', 'shi', '', NULL, '惜牡丹花二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('678d05bd-b9e7-4ecc-be6e-91dc7b26f5d7', '荅元奉禮同宿見贈', '荅元奉禮同宿见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["相逢俱歎不閑身，直日常多齋日頻。","曉鼓一聲分散去，明朝風景屬何人。"]', '["相逢俱歎不闲身，直日常多斋日頻。","晓鼓一声分散去，明朝风景屬何人。"]', '诗', 'shi', '', NULL, '荅元奉禮同宿見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2749a3bb-d308-4291-838d-3e98da7d4d18', '荅馬侍御見贈', '荅马侍御见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["謬入金門侍玉除，煩君問我意何如。","蟠木詎堪明主用，籠禽徒與故人疎。","苑花似雪同隨輦，宮月如眉伴直廬。","淺薄求賢思自代，嵇康莫寄絕交書。"]', '["謬入金门侍玉除，煩君问我意何如。","蟠木詎堪明主用，籠禽徒與故人疎。","苑花似雪同隨輦，宮月如眉伴直廬。","淺薄求賢思自代，嵇康莫寄絕交书。"]', '诗', 'shi', '', NULL, '荅馬侍御見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2a7ff16-70cf-41c1-9c92-98d72b43c6db', '上巳日恩賜曲江宴會即事', '上巳日恩賜曲江宴會即事', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["賜歡仍許醉，此會興如何。","翰苑主恩重，曲江春意多。","花低羞豔妓，鶯散讓清歌。","共道升平樂，元和勝永和。"]', '["賜歡仍許醉，此會兴如何。","翰苑主恩重，曲江春意多。","花低羞豔妓，鶯散讓清歌。","共道升平乐，元和勝永和。"]', '诗', 'shi', '', NULL, '上巳日恩賜曲江宴會即事 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ed8894d-ed56-44de-a0f9-3808db91c8b9', '夜惜禁中桃花因懷錢員外', '夜惜禁中桃花因懷錢員外', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["前日歸時花正紅，今夜宿時枝半空。","坐惜殘芳君不見，風吹狼藉月明中。"]', '["前日归时花正紅，今夜宿时枝半空。","坐惜殘芳君不见，风吹狼藉月明中。"]', '诗', 'shi', '', NULL, '夜惜禁中桃花因懷錢員外 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0b9984d-eb82-4994-9aeb-dd578cf8b3c1', '和錢員外早冬玩禁中新菊', '和錢員外早冬玩禁中新菊', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["禁署寒氣遲，孟冬菊初坼。","新黃間繁綠，爛若金照碧。","仙郎小隱日，心似陶彭澤。","秋憐潭上看，日慣籬邊摘。","今來此地賞，野意潛自適。","金馬門內花，玉山峰下客。","寒芳引清句，吟玩煙景夕。","賜酒色偏宜，握蘭香不敵。","淒淒百卉死，歲晚冰霜積。","唯有此花開，殷勤助君惜。"]', '["禁署寒氣遲，孟冬菊初坼。","新黄间繁綠，爛若金照碧。","仙郎小隐日，心似陶彭澤。","秋怜潭上看，日慣籬邊摘。","今来此地賞，野意潛自適。","金马门內花，玉山峰下客。","寒芳引清句，吟玩煙景夕。","賜酒色偏宜，握蘭香不敵。","淒淒百卉死，歲晚冰霜積。","唯有此花开，殷勤助君惜。"]', '诗', 'shi', '', NULL, '和錢員外早冬玩禁中新菊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c21e797c-469b-4909-80cf-f6fe2458feda', '荅劉戒之早秋別墅見寄', '荅劉戒之早秋別墅见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["涼風木槿籬，暮雨槐花枝。","幷起新秋思，爲得故人詩。","避地鳥擇木，升朝魚在池。","城中與山下，喧靜闇相思。"]', '["涼风木槿籬，暮雨槐花枝。","幷起新秋思，爲得故人诗。","避地鸟擇木，升朝鱼在池。","城中與山下，喧静闇相思。"]', '诗', 'shi', '', NULL, '荅劉戒之早秋別墅見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31dd1e86-b1d5-4d84-ad33-ebde3ef0797b', '涼夜有懷', '涼夜有懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["念別感時節，早蛩聞一聲。","風簾夜涼入，露簟秋意生。","燈盡夢初罷，月斜天未明。","闇凝無限思，起傍藥闌行。"]', '["念別感时節，早蛩闻一声。","风簾夜涼入，露簟秋意生。","灯尽梦初罷，月斜天未明。","闇凝無限思，起傍藥闌行。"]', '诗', 'shi', '', NULL, '涼夜有懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e68e524-df00-42f5-b814-57d93ec727fc', '秋思', '秋思', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["病眠夜少夢，閑立秋多思。","寂寞餘雨晴，蕭條早寒至。","鳥棲紅葉樹，月照青苔地。","何況鏡中年，又過三十二。"]', '["病眠夜少梦，闲立秋多思。","寂寞餘雨晴，蕭條早寒至。","鸟棲紅葉樹，月照青苔地。","何況镜中年，又過三十二。"]', '诗', 'shi', '', NULL, '秋思 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b900a74d-2082-4cf9-aee9-c41bb05d5bff', '禁中聞蛩', '禁中闻蛩', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["悄悄禁門閉，夜深無月明。","西窗獨闇坐，滿耳新蛩聲。"]', '["悄悄禁门閉，夜深無月明。","西窗独闇坐，满耳新蛩声。"]', '诗', 'shi', '', NULL, '禁中聞蛩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('541e3c1f-effb-4dbb-ab37-04ce524a2c63', '秋蟲', '秋蟲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["切切闇窗下，喓喓深草裏。","秋天思婦心，雨夜愁人耳。"]', '["切切闇窗下，喓喓深草裏。","秋天思婦心，雨夜愁人耳。"]', '诗', 'shi', '', NULL, '秋蟲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46926d08-c875-4ec0-9046-b6d92348be06', '贈別宣上人', '贈別宣上人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["上人處世界，清淨何所似。","似彼白蓮花，在水不著水。","性真悟泡幻，行潔離塵滓。","修道來幾時，身心俱到此。","嗟余牽世網，不得長依止。","離念與碧雲，秋來朝夕起。"]', '["上人处世界，清淨何所似。","似彼白蓮花，在水不著水。","性真悟泡幻，行潔離塵滓。","修道来幾时，身心俱到此。","嗟余牽世網，不得长依止。","離念與碧云，秋来朝夕起。"]', '诗', 'shi', '', NULL, '贈別宣上人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a090e29-02a0-4fcb-bf13-81f883cc0333', '春夜喜雪有懷王二十二', '春夜喜雪有懷王二十二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜雪有佳趣，幽人出書帷。","微寒生枕席，輕素對階墀。","坐罷楚弦曲，起吟班扇詩。","明宜滅燭後，淨愛褰簾時。","窗引曙色早，庭銷春氣遲。","山陰應有興，不臥待徽之。"]', '["夜雪有佳趣，幽人出书帷。","微寒生枕席，轻素对階墀。","坐罷楚弦曲，起吟班扇诗。","明宜滅燭後，淨愛褰簾时。","窗引曙色早，庭銷春氣遲。","山陰應有兴，不臥待徽之。"]', '诗', 'shi', '', NULL, '春夜喜雪有懷王二十二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c3d1b9e-3000-479f-b207-767d3b454a49', '酬和元九東川路詩十二首 駱口驛舊題詩', '酬和元九东川路诗十二首 駱口驛旧題诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["拙詩在壁無人愛，鳥汙苔侵文字殘。","唯有多情元侍御，繡衣不惜拂塵看。"]', '["拙诗在壁無人愛，鸟汙苔侵文字殘。","唯有多情元侍御，繡衣不惜拂塵看。"]', '诗', 'shi', '', NULL, '酬和元九東川路詩十二首 駱口驛舊題詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61191841-79c3-4581-b277-e245d174330a', '酬和元九東川路詩十二首 南秦雪', '酬和元九东川路诗十二首 南秦雪', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["往歲曾爲西邑吏，慣從駱口到南秦。","三時雲冷多飛雪，二月山寒少有春。","我思舊事猶惆悵，君作初行定苦辛。","任賴愁猨寒不叫，若聞猨叫更愁人。"]', '["往歲曾爲西邑吏，慣從駱口到南秦。","三时云冷多飞雪，二月山寒少有春。","我思旧事猶惆悵，君作初行定苦辛。","任賴愁猨寒不叫，若闻猨叫更愁人。"]', '诗', 'shi', '', NULL, '酬和元九東川路詩十二首 南秦雪 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34e6c28b-edf5-40c5-83ff-2fd911f2b82d', '酬和元九東川路詩十二首 山枇杷花二首 一', '酬和元九东川路诗十二首 山枇杷花二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["萬重青嶂蜀門口，一樹紅花山頂頭。","春盡憶家歸未得，低紅如解替君愁。"]', '["万重青嶂蜀门口，一樹紅花山頂头。","春尽憶家归未得，低紅如解替君愁。"]', '诗', 'shi', '', NULL, '酬和元九東川路詩十二首 山枇杷花二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3175c3bc-7ec2-40fc-bd98-793d82d2a756', '酬和元九東川路詩十二首 山枇杷花二首 二', '酬和元九东川路诗十二首 山枇杷花二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["葉如帬色碧綃淺，花似芙蓉紅粉輕。","若使此花兼解語，推囚御史定違程。"]', '["葉如帬色碧綃淺，花似芙蓉紅粉轻。","若使此花兼解語，推囚御史定違程。"]', '诗', 'shi', '', NULL, '酬和元九東川路詩十二首 山枇杷花二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('477251d1-3976-40b6-9608-17f02f63f982', '酬和元九東川路詩十二首 江樓月', '酬和元九东川路诗十二首 江楼月', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["嘉陵江曲曲江池，明月雖同人別離。","一宵光景潛相憶，兩地陰晴遠不知。","誰料江邊懷我夜，正當池畔望君時。","今朝共語方同悔，不解多情先寄詩。"]', '["嘉陵江曲曲江池，明月雖同人別離。","一宵光景潛相憶，兩地陰晴远不知。","誰料江邊懷我夜，正當池畔望君时。","今朝共語方同悔，不解多情先寄诗。"]', '诗', 'shi', '', NULL, '酬和元九東川路詩十二首 江樓月 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('672dab59-f65f-41c4-9164-4625eaf02569', '酬和元九東川路詩十二首 亞枝花', '酬和元九东川路诗十二首 亞枝花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["山郵花木似平陽，愁殺多情驄馬郎。","還似升平池畔坐，低頭向水自看妝。"]', '["山郵花木似平陽，愁殺多情驄马郎。","還似升平池畔坐，低头向水自看妝。"]', '诗', 'shi', '', NULL, '酬和元九東川路詩十二首 亞枝花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29ad18a2-cbb9-4fbe-97ea-690c9ca3edd0', '酬和元九東川路詩十二首 江上笛', '酬和元九东川路诗十二首 江上笛', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江上何人夜吹笛，聲聲似憶故園春。","此時聞者堪頭白，況是多愁少睡人。"]', '["江上何人夜吹笛，声声似憶故园春。","此时闻者堪头白，況是多愁少睡人。"]', '诗', 'shi', '', NULL, '酬和元九東川路詩十二首 江上笛 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67256052-e19b-4ad7-a021-14d4cffec23d', '酬和元九東川路詩十二首 嘉陵夜有懷二首 一', '酬和元九东川路诗十二首 嘉陵夜有懷二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["露濕牆花春意深，西廊月上半牀陰。","憐君獨臥無言語，唯我知君此夜心。"]', '["露濕牆花春意深，西廊月上半牀陰。","怜君独臥無言語，唯我知君此夜心。"]', '诗', 'shi', '', NULL, '酬和元九東川路詩十二首 嘉陵夜有懷二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ef7a0df-7c1d-4967-9141-b5d8f7e9a888', '酬和元九東川路詩十二首 嘉陵夜有懷二首 二', '酬和元九东川路诗十二首 嘉陵夜有懷二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不明不暗朧朧月，不暖不寒慢慢風。","獨臥空牀好天氣，平明閑事到心中。"]', '["不明不暗朧朧月，不暖不寒慢慢风。","独臥空牀好天氣，平明闲事到心中。"]', '诗', 'shi', '', NULL, '酬和元九東川路詩十二首 嘉陵夜有懷二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('646d1c95-6805-4ab4-8bed-2ddb7166b852', '酬和元九東川路詩十二首 夜深行', '酬和元九东川路诗十二首 夜深行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["百牢關外夜行客，三殿角頭宵直人。","莫道近臣勝遠使，其如同是不閑身。"]', '["百牢关外夜行客，三殿角头宵直人。","莫道近臣勝远使，其如同是不闲身。"]', '诗', 'shi', '', NULL, '酬和元九東川路詩十二首 夜深行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a37babb-d94a-4b9c-8aeb-1d5245acfcf7', '酬和元九東川路詩十二首 望驛臺', '酬和元九东川路诗十二首 望驛台', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["靖安宅裏當窗柳，望驛臺前撲地花。","兩處春光同日盡，居人思客客思家。"]', '["靖安宅裏當窗柳，望驛台前撲地花。","兩处春光同日尽，居人思客客思家。"]', '诗', 'shi', '', NULL, '酬和元九東川路詩十二首 望驛臺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d18a2679-38bc-4848-9947-d7e1d00d1177', '酬和元九東川路詩十二首 江岸棃花', '酬和元九东川路诗十二首 江岸棃花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["棃花有思緣和葉，一樹江頭惱殺君。","最似孀閨少年婦，白妝素袖碧紗帬。"]', '["棃花有思緣和葉，一樹江头惱殺君。","最似孀閨少年婦，白妝素袖碧紗帬。"]', '诗', 'shi', '', NULL, '酬和元九東川路詩十二首 江岸棃花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b6dd3c8-5a26-42e9-b7b9-6e76417d272e', '荅謝家最小偏憐女', '荅謝家最小偏怜女', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["嫁得梁鴻六七年，耽書愛酒日高眠。","雨荒春圃唯生草，雪壓朝廚未有煙。","身病憂來緣女少，家貧忘却爲夫賢。","誰知厚俸今無分，枉向秋風吹紙錢。"]', '["嫁得梁鴻六七年，耽书愛酒日高眠。","雨荒春圃唯生草，雪壓朝廚未有煙。","身病憂来緣女少，家貧忘却爲夫賢。","誰知厚俸今無分，枉向秋风吹紙錢。"]', '诗', 'shi', '', NULL, '荅謝家最小偏憐女 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb1e8fc9-d00c-4345-9b84-026690c754a8', '荅騎馬入空臺', '荅騎马入空台', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["君入空臺去，朝往暮還來。","我入泉臺去，泉門無復開。","鰥夫任繫職，穉女未勝哀。","寂寞咸陽道，家人覆墓迴。"]', '["君入空台去，朝往暮還来。","我入泉台去，泉门無复开。","鰥夫任繫職，穉女未勝哀。","寂寞咸陽道，家人覆墓迴。"]', '诗', 'shi', '', NULL, '荅騎馬入空臺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('962a4569-cf4c-46d6-9c9b-eab27dd17a82', '荅山驛夢', '荅山驛梦', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["入君旅夢來千里，閉我幽魂欲二年。","莫忘平生行坐處，後堂階下竹叢前。"]', '["入君旅梦来千里，閉我幽魂欲二年。","莫忘平生行坐处，後堂階下竹叢前。"]', '诗', 'shi', '', NULL, '荅山驛夢 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbe56a89-b1ec-4a18-b330-e2dfd68fec8d', '和元九與呂二同宿話舊感贈', '和元九與呂二同宿話旧感贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["見君新贈呂君詩，憶得同年行樂時。","爭入杏園齊馬首，潛過柳曲鬬蛾眉。","八人雲散俱遊宦，七度花開盡別離。","聞道秋娘猶且在，至今時復問微之。"]', '["见君新贈呂君诗，憶得同年行乐时。","爭入杏园齊马首，潛過柳曲鬬蛾眉。","八人云散俱游宦，七度花开尽別離。","闻道秋娘猶且在，至今时复问微之。"]', '诗', 'shi', '', NULL, '和元九與呂二同宿話舊感贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aec0c03f-0f29-48f2-b0c2-8f50a3e5e02a', '憶元九', '憶元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["渺渺江陵道，相思遠不知。","近來文卷裏，半是憶君詩。"]', '["渺渺江陵道，相思远不知。","近来文卷裏，半是憶君诗。"]', '诗', 'shi', '', NULL, '憶元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('545f574e-4691-4405-bc8d-5c9adda64210', '蕭員外寄新蜀茶', '蕭員外寄新蜀茶', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蜀茶寄到但驚新，渭水煎來始覺珍。","滿甌似乳堪持玩，況是春深酒渴人。"]', '["蜀茶寄到但驚新，渭水煎来始覺珍。","满甌似乳堪持玩，況是春深酒渴人。"]', '诗', 'shi', '', NULL, '蕭員外寄新蜀茶 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dacdc367-9262-445f-a5a5-634a588f4b0a', '寄上大兄', '寄上大兄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秋鴻過盡無書信，病戴紗巾強出門。","獨上荒臺東北望，日西愁立到黃昏。"]', '["秋鴻過尽無书信，病戴紗巾強出门。","独上荒台东北望，日西愁立到黄昏。"]', '诗', 'shi', '', NULL, '寄上大兄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea2ed339-839d-42c8-8308-40cdb8b81340', '病中哭金鑾子', '病中哭金鑾子', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["豈料吾方病，飜悲汝不全。","臥驚從枕上，扶哭就燈前。","有女誠爲累，無兒豈免憐。","病來纔十日，養得已三年。","慈淚隨聲迸，悲腸遇物牽。","故衣猶架上，殘藥尚頭邊。","送出深村巷，看封小墓田。","莫言三里地，此別是終天。"]', '["豈料吾方病，飜悲汝不全。","臥驚從枕上，扶哭就灯前。","有女誠爲累，無兒豈免怜。","病来纔十日，養得已三年。","慈泪隨声迸，悲腸遇物牽。","故衣猶架上，殘藥尚头邊。","送出深村巷，看封小墓田。","莫言三里地，此別是終天。"]', '诗', 'shi', '', NULL, '病中哭金鑾子 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fe5fc01-e66d-47f3-a2d8-56a2852b71f3', '寄內', '寄內', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["條桑初綠即爲別，柿葉半紅猶未歸。","不如村婦知時節，解爲田夫秋擣衣。"]', '["條桑初綠即爲別，柿葉半紅猶未归。","不如村婦知时節，解爲田夫秋擣衣。"]', '诗', 'shi', '', NULL, '寄內 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('757aa868-d91a-4848-8cee-0e4ec35309f2', '病氣', '病氣', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自知氣發每因情，情在何由氣得平。","若問病根深與淺，此身應與病齊生。"]', '["自知氣發每因情，情在何由氣得平。","若问病根深與淺，此身應與病齊生。"]', '诗', 'shi', '', NULL, '病氣 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bb58119-41a8-4c01-a673-ceeb9c5ed42e', '歎元九', '歎元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不入城門來五載，同時班列盡官高。","何人牢落猶依舊，唯有江陵元士曹。"]', '["不入城门来五載，同时班列尽官高。","何人牢落猶依旧，唯有江陵元士曹。"]', '诗', 'shi', '', NULL, '歎元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('855553e3-68e3-444a-b89a-b687b71b0bd5', '眼暗', '眼暗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["早年勤倦看書苦，晚歲悲傷出淚多。","眼損不知都自取，病成方悟欲如何。","夜昏乍似燈將滅，朝闇長疑鏡未磨。","千藥萬方治不得，唯應閉目學頭陀。"]', '["早年勤倦看书苦，晚歲悲傷出泪多。","眼損不知都自取，病成方悟欲如何。","夜昏乍似灯將滅，朝闇长疑镜未磨。","千藥万方治不得，唯應閉目学头陀。"]', '诗', 'shi', '', NULL, '眼暗 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81b32163-af3c-4af8-a7dc-45f931a0b7f4', '得袁相書', '得袁相书', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["穀苗深處一農夫，面黑頭斑手把鋤。","何意使人猶識我，就田來送相公書。"]', '["穀苗深处一農夫，面黑头斑手把鋤。","何意使人猶識我，就田来送相公书。"]', '诗', 'shi', '', NULL, '得袁相書 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab8d7d5d-64a8-4cf5-82b3-f1aa59a12555', '病中作', '病中作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["病來城裏諸親故，厚薄親疎心總知。","唯有蔚章於我分，深於同在翰林時。"]', '["病来城裏諸親故，厚薄親疎心總知。","唯有蔚章於我分，深於同在翰林时。"]', '诗', 'shi', '', NULL, '病中作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a9d07b6-8d5c-47b6-a3ce-4f4a27c8e054', '感化寺見元九劉三十二題名處', '感化寺见元九劉三十二題名处', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["微之謫去千餘里，太白無來十一年。","今日見名如見面，塵埃壁上破窗前。"]', '["微之謫去千餘里，太白無来十一年。","今日见名如见面，塵埃壁上破窗前。"]', '诗', 'shi', '', NULL, '感化寺見元九劉三十二題名處 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdedbda3-e775-4341-a995-c2f712ef2fa0', '遊悟貞寺迴山下別張殷衡', '游悟貞寺迴山下別張殷衡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["世緣未了治不得，孤負青山心共知。","愁君又入都門去，即是紅塵滿眼時。"]', '["世緣未了治不得，孤負青山心共知。","愁君又入都门去，即是紅塵满眼时。"]', '诗', 'shi', '', NULL, '遊悟貞寺迴山下別張殷衡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2dacec8-ad5a-4397-93f6-9be8b148ed88', '村居寄張殷衡', '村居寄張殷衡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["金氏村中一病夫，生涯濩落性靈迂。","唯看老子五千字，不蹋長安十二衢。","藥銚夜傾殘酒煖，竹牀寒取舊氈鋪。","聞君欲發江東去，能到茅菴訪別無。"]', '["金氏村中一病夫，生涯濩落性靈迂。","唯看老子五千字，不蹋长安十二衢。","藥銚夜傾殘酒煖，竹牀寒取旧氈鋪。","闻君欲發江东去，能到茅菴訪別無。"]', '诗', 'shi', '', NULL, '村居寄張殷衡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1ffddc0-f4f6-4aa0-921d-e644cd8586a9', '病中得樊大書', '病中得樊大书', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["荒村破屋經年臥，寂絕無人問病身。","唯有東都樊著作，至今書信尚殷勤。"]', '["荒村破屋經年臥，寂絕無人问病身。","唯有东都樊著作，至今书信尚殷勤。"]', '诗', 'shi', '', NULL, '病中得樊大書 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d9b8943-8400-4fa7-8554-bdad9369db40', '開元九詩書卷', '开元九诗书卷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紅牋白紙兩三束，半是君詩半是書。","經年不展緣身病，今日開看生蠹魚。"]', '["紅牋白紙兩三束，半是君诗半是书。","經年不展緣身病，今日开看生蠹鱼。"]', '诗', 'shi', '', NULL, '開元九詩書卷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04a7b4e6-59dd-4023-8018-466431aaebb0', '晝臥', '晝臥', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["抱枕無言語，空房獨悄然。","誰知盡日臥，非病亦非眠。"]', '["抱枕無言語，空房独悄然。","誰知尽日臥，非病亦非眠。"]', '诗', 'shi', '', NULL, '晝臥 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18690e89-2a93-496e-aa8e-954c8c17641b', '夜坐', '夜坐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["庭前盡日立到夜，燈下有時坐徹明。","此情不語何人會，時復長吁一兩聲。"]', '["庭前尽日立到夜，灯下有时坐徹明。","此情不語何人會，时复长吁一兩声。"]', '诗', 'shi', '', NULL, '夜坐 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2630277-c246-4a08-8bc4-7e1db4695059', '暮立', '暮立', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["黃昏獨立佛堂前，滿地槐花滿樹蟬。","大抵四時心總苦，就中腸斷是秋天。"]', '["黄昏独立佛堂前，满地槐花满樹蟬。","大抵四时心總苦，就中腸斷是秋天。"]', '诗', 'shi', '', NULL, '暮立 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8f0943a-9e1e-4606-93c0-9763779182f7', '有感', '有感', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["絕弦與斷絲，猶有却續時。","唯有衷腸斷，應無續得期。"]', '["絕弦與斷絲，猶有却續时。","唯有衷腸斷，應無續得期。"]', '诗', 'shi', '', NULL, '有感 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18715080-bdbd-43eb-9fea-f560bbbeef89', '荅友問', '荅友问', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["似玉童顏盡，如霜病鬢新。","莫驚身頓老，心更老於身。"]', '["似玉童顏尽，如霜病鬢新。","莫驚身頓老，心更老於身。"]', '诗', 'shi', '', NULL, '荅友問 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a96bc1fc-868d-474d-abca-1b025afdb009', '村夜', '村夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["霜草蒼蒼蟲切切，村南村北行人絕。","獨出前門望野田，月明蕎麥花如雪。"]', '["霜草蒼蒼蟲切切，村南村北行人絕。","独出前门望野田，月明蕎麦花如雪。"]', '诗', 'shi', '', NULL, '村夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('316b68e4-1b43-4f0c-8ec2-ed129d5c9c50', '聞蟲', '闻蟲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["暗蟲唧唧夜緜緜，況是秋陰欲雨天。","猶恐愁人暫得睡，聲聲移近臥牀前。"]', '["暗蟲唧唧夜緜緜，況是秋陰欲雨天。","猶恐愁人暫得睡，声声移近臥牀前。"]', '诗', 'shi', '', NULL, '聞蟲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fe6a34b-55c3-4fde-bcdc-7288d9ad79dc', '寒食夜有懷', '寒食夜有懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["寒食非長非短夜，春風不熱不寒天。","可憐時節堪相憶，何況無燈各早眠。"]', '["寒食非长非短夜，春风不熱不寒天。","可怜时節堪相憶，何況無灯各早眠。"]', '诗', 'shi', '', NULL, '寒食夜有懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeb942b6-d854-4a2b-bcee-a40f98f6edef', '贈內', '贈內', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["漠漠闇苔新雨地，微微涼露欲秋天。","莫對月明思往事，損君顏色減君年。"]', '["漠漠闇苔新雨地，微微涼露欲秋天。","莫对月明思往事，損君顏色減君年。"]', '诗', 'shi', '', NULL, '贈內 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf51e6fa-a589-4cfc-a7da-8f061e486a7a', '得錢舍人書問眼疾', '得錢舍人书问眼疾', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["春來眼闇少心情，點盡黃連尚未平。","唯得君書勝得藥，開緘未讀眼先明。"]', '["春来眼闇少心情，点尽黄連尚未平。","唯得君书勝得藥，开緘未读眼先明。"]', '诗', 'shi', '', NULL, '得錢舍人書問眼疾 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5108300b-1703-4db4-82c5-35ef128de98e', '還李十一馬', '還李十一马', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["傳語李君勞寄馬，病來唯著杖扶身。","縱擬強騎無出處，却將牽與趁朝人。"]', '["傳語李君勞寄马，病来唯著杖扶身。","縱擬強騎無出处，却將牽與趁朝人。"]', '诗', 'shi', '', NULL, '還李十一馬 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e373015-8104-41e0-b4ee-d72649428998', '九日寄行簡', '九日寄行簡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["摘得菊花攜得酒，繞村騎馬思悠悠。","下邽田地平如掌，何處登髙望梓州。"]', '["摘得菊花携得酒，繞村騎马思悠悠。","下邽田地平如掌，何处登髙望梓州。"]', '诗', 'shi', '', NULL, '九日寄行簡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c64e239f-b458-4bee-b583-cf0dab072906', '夜坐', '夜坐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["斜月入前楹，迢迢夜坐情。","梧桐上階影，蟋蟀近牀聲。","曙傍窗間至，秋從簟上生。","感時因憶事，不寢到雞鳴。"]', '["斜月入前楹，迢迢夜坐情。","梧桐上階影，蟋蟀近牀声。","曙傍窗间至，秋從簟上生。","感时因憶事，不寢到雞鳴。"]', '诗', 'shi', '', NULL, '夜坐 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6846795-96aa-42c2-b51d-d0a3ce349f37', '村居二首 一', '村居二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["田園莽蒼經春早，籬落蕭條盡日風。","若問經過談笑者，不過田舍白頭翁。"]', '["田园莽蒼經春早，籬落蕭條尽日风。","若问經過談笑者，不過田舍白头翁。"]', '诗', 'shi', '', NULL, '村居二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62a6abfc-070a-40ac-8e3a-e4678b9661e1', '村居二首 二', '村居二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["門閉仍逢雪，廚寒未起煙。","貧家重寥落，半爲日高眠。"]', '["门閉仍逢雪，廚寒未起煙。","貧家重寥落，半爲日高眠。"]', '诗', 'shi', '', NULL, '村居二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56434984-cb41-42c9-977e-9d030b9dd7c3', '早春', '早春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雪散因和氣，冰開得暖光。","春銷不得處，唯有鬢邊霜。"]', '["雪散因和氣，冰开得暖光。","春銷不得处，唯有鬢邊霜。"]', '诗', 'shi', '', NULL, '早春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c084d0f-76cc-4294-bd80-4e8672338d39', '和夢遊春詩一百韻', '和梦游春诗一百韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昔君夢遊春，夢遊仙山曲。","怳若有所遇，似愜平生欲。","因尋菖蒲水，漸入桃花谷。","到一紅樓家，愛之看不足。","池流渡清泚，草嫩蹋綠蓐。","門柳闇全低，檐櫻紅半熟。","轉行深深院，過盡重重屋。","烏龍臥不驚，青鳥飛相逐。","漸聞玉珮響，始辨珠履躅。","遙見窗下人，娉婷十五六。","霞光抱明月，蓮豔開初旭。","縹緲雲雨仙，氛氳蘭麝馥。","風流薄梳洗，時世寬妝束。","袖輭異文綾，裾輕單絲縠。","裙腰銀線壓，梳掌金筐蹙。","帶襭紫蒲萄，袴花紅石竹。","凝情都未語，付意微相矚。","眉斂遠山青，鬟低片雲綠。","帳牽翡翠帶，被解鴛鴦襆。","秀色似堪餐，穠華如可掬。","半卷錦頭席，斜鋪繡腰褥。","朱脣素指勻，粉汗紅緜撲。","心驚睡易覺，夢斷魂難續。","籠委獨棲禽，劒分連理木。","存誠期有感，誓志貞無黷。","京洛八九春，未曾花裏宿。","壯年徒自棄，佳會應無復。","鸞歌不重聞，鳳兆從茲卜。","韋門女清貴，裴氏甥賢淑。","羅扇夾花燈，金鞍攢繡轂。","既傾南國貌，遂坦東牀腹。","劉阮心漸忘，潘楊意方睦。","新修履信第，初食尚書祿。","九醞備聖賢，八珍窮水陸。","秦家重蕭史，彥輔憐衛叔。","朝饌饋獨盤，夜醪傾百斛。","親賓盛輝赫，妓樂紛曄煜。","宿醉纔解酲，朝歡俄枕麴。","飲過君子爭，令甚將軍酷。","酩酊歌鷓鴣，顛狂舞鴝鵒。","月流春夜短，日下秋天速。","謝傅隙過駒，蕭娘風過燭。","全凋蕣花折，半死梧桐禿。","闇鏡對孤鸞，哀弦留寡鵠。","淒淒隔幽顯，冉冉移寒燠。","萬事此時休，百身何處贖。","提攜小兒女，將領舊姻族。","再入朱門行，一傍青樓哭。","櫪空無廐馬，水涸失池[鶩]。","搖落廢井梧，荒涼故籬菊。","莓苔上几閣，塵土生琴筑。","舞榭綴蠨蛸，歌梁聚蝙蝠。","嫁分紅粉妾，賣散蒼頭僕。","門客思徬徨，家人泣吚噢。","心期正蕭索，宦序仍拘跼。","懷策入崤函，驅車辭郟鄏。","逢時念既濟，聚學思大畜。","端詳筮仕蓍，磨拭穿楊鏃。","始從讐校職，首中賢良目。","一拔侍瑤墀，再升紆繡服。","誓酬君王寵，願使朝廷肅。","密勿奏封章，清明操憲牘。","鷹韝中病下，豸角當邪觸。","糾謬靜東周，申冤動南蜀。","危言詆閽寺，直氣忤鈞軸。","不忍曲作鉤，乍能折爲玉。","捫心無媿畏，騰口有謗讟。","只要明是非，何曾虞禍福。","車摧太行路，劒落酆城獄。","襄漢問修途，荆蠻指殊俗。","謫爲江府掾，遣事荆州牧。","趨走謁麾幢，喧煩視鞭朴。","簿書常自領，縲囚每親鞫。","竟日坐官曹，經旬曠休沐。","宅荒渚宮草，馬瘦畬田粟。","薄俸等涓毫，微官同桎梏。","月中照形影，天際辭骨肉。","鶴病翅羽垂，獸窮爪牙縮。","行看鬚間白，誰勸杯中綠。","時傷大野麟，命問長沙鵩。","夏梅山雨漬，秋瘴江雲毒。","巴水白茫茫，楚山青簇簇。","吟君七十韻，是我心所蓄。","既去誠莫追，將來幸前勗。","欲除憂惱病，當取禪經讀。","須悟事皆空，無令念將屬。","請思遊春夢，此夢何閃倏。","豔色即空花，浮生乃焦穀。","良姻在嘉偶，頃剋爲單獨。","入仕欲榮身，須臾成黜辱。","合者離之始，樂兮憂所伏。","愁恨僧祇長，歡榮剎那促。","覺悟因傍喻，迷執由當局。","膏明誘闇蛾，陽焱奔癡鹿。","貪爲苦聚落，愛是悲林麓。","水蕩無明波，輪迴死生輻。","塵應甘露灑，垢待醍醐浴。","障要智燈燒，魔須慧刀戮。","外熏性易染，內戰心難衂。","法句與心王，期君日三復。"]', '["昔君梦游春，梦游仙山曲。","怳若有所遇，似愜平生欲。","因尋菖蒲水，漸入桃花谷。","到一紅楼家，愛之看不足。","池流渡清泚，草嫩蹋綠蓐。","门柳闇全低，檐櫻紅半熟。","轉行深深院，過尽重重屋。","烏龙臥不驚，青鸟飞相逐。","漸闻玉珮响，始辨珠履躅。","遙见窗下人，娉婷十五六。","霞光抱明月，蓮豔开初旭。","縹緲云雨仙，氛氳蘭麝馥。","风流薄梳洗，时世寬妝束。","袖輭異文綾，裾轻單絲縠。","裙腰銀線壓，梳掌金筐蹙。","带襭紫蒲萄，袴花紅石竹。","凝情都未語，付意微相矚。","眉斂远山青，鬟低片云綠。","帳牽翡翠带，被解鴛鴦襆。","秀色似堪餐，穠华如可掬。","半卷錦头席，斜鋪繡腰褥。","朱脣素指勻，粉汗紅緜撲。","心驚睡易覺，梦斷魂难續。","籠委独棲禽，劒分連理木。","存誠期有感，誓志貞無黷。","京洛八九春，未曾花裏宿。","壯年徒自棄，佳會應無复。","鸾歌不重闻，鳳兆從茲卜。","韋门女清貴，裴氏甥賢淑。","羅扇夾花灯，金鞍攢繡轂。","既傾南国貌，遂坦东牀腹。","劉阮心漸忘，潘楊意方睦。","新修履信第，初食尚书祿。","九醞備聖賢，八珍窮水陸。","秦家重蕭史，彥輔怜衛叔。","朝饌饋独盤，夜醪傾百斛。","親賓盛輝赫，妓乐紛曄煜。","宿醉纔解酲，朝歡俄枕麴。","饮過君子爭，令甚將軍酷。","酩酊歌鷓鴣，顛狂舞鴝鵒。","月流春夜短，日下秋天速。","謝傅隙過駒，蕭娘风過燭。","全凋蕣花折，半死梧桐禿。","闇镜对孤鸾，哀弦留寡鵠。","淒淒隔幽显，冉冉移寒燠。","万事此时休，百身何处贖。","提携小兒女，將領旧姻族。","再入朱门行，一傍青楼哭。","櫪空無廐马，水涸失池[鶩]。","搖落廢井梧，荒涼故籬菊。","莓苔上几閣，塵土生琴筑。","舞榭綴蠨蛸，歌梁聚蝙蝠。","嫁分紅粉妾，賣散蒼头僕。","门客思徬徨，家人泣吚噢。","心期正蕭索，宦序仍拘跼。","懷策入崤函，驱车辞郟鄏。","逢时念既濟，聚学思大畜。","端詳筮仕蓍，磨拭穿楊鏃。","始從讐校職，首中賢良目。","一拔侍瑤墀，再升紆繡服。","誓酬君王寵，願使朝廷肅。","密勿奏封章，清明操憲牘。","鷹韝中病下，豸角當邪觸。","糾謬静东周，申冤动南蜀。","危言詆閽寺，直氣忤鈞軸。","不忍曲作鉤，乍能折爲玉。","捫心無媿畏，腾口有謗讟。","只要明是非，何曾虞禍福。","车摧太行路，劒落酆城獄。","襄漢问修途，荆蠻指殊俗。","謫爲江府掾，遣事荆州牧。","趨走謁麾幢，喧煩視鞭朴。","簿书常自領，縲囚每親鞫。","竟日坐官曹，經旬曠休沐。","宅荒渚宮草，马瘦畬田粟。","薄俸等涓毫，微官同桎梏。","月中照形影，天際辞骨肉。","鹤病翅羽垂，獸窮爪牙縮。","行看鬚间白，誰勸杯中綠。","时傷大野麟，命问长沙鵩。","夏梅山雨漬，秋瘴江云毒。","巴水白茫茫，楚山青簇簇。","吟君七十韻，是我心所蓄。","既去誠莫追，將来幸前勗。","欲除憂惱病，當取禪經读。","須悟事皆空，無令念將屬。","請思游春梦，此梦何閃倏。","豔色即空花，浮生乃焦穀。","良姻在嘉偶，頃剋爲單独。","入仕欲榮身，須臾成黜辱。","合者離之始，乐兮憂所伏。","愁恨僧祇长，歡榮剎那促。","覺悟因傍喻，迷執由當局。","膏明誘闇蛾，陽焱奔癡鹿。","貪爲苦聚落，愛是悲林麓。","水蕩無明波，輪迴死生輻。","塵應甘露灑，垢待醍醐浴。","障要智灯燒，魔須慧刀戮。","外熏性易染，內戰心难衂。","法句與心王，期君日三复。"]', '诗', 'shi', '', NULL, '和夢遊春詩一百韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1705bb19-c6ff-40e2-be8f-4a9475b2ffc0', '王昭君二首 一', '王昭君二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["滿面胡沙滿鬢風，眉銷殘黛臉銷紅。","愁苦辛勤顦顇盡，如今却似畫圖中。"]', '["满面胡沙满鬢风，眉銷殘黛臉銷紅。","愁苦辛勤顦顇尽，如今却似畫圖中。"]', '诗', 'shi', '', NULL, '王昭君二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a3a31d1-2ebc-47b3-ba5b-38a6553a68d1', '王昭君二首 二', '王昭君二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["漢使却回憑寄語，黃金何日贖蛾眉。","君王若問妾顏色，莫道不知宮裏時。"]', '["漢使却回憑寄語，黄金何日贖蛾眉。","君王若问妾顏色，莫道不知宮裏时。"]', '诗', 'shi', '', NULL, '王昭君二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2fcac42-d89b-45b0-ad1b-a785a9b9a9cf', '渭村退居寄禮部崔侍郎翰林錢舍人詩一百韻', '渭村退居寄禮部崔侍郎翰林錢舍人诗一百韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["聖代元和歲，閑居渭水陽。","不才甘命舛，多幸遇時康。","朝野分倫序，賢愚定否臧。","重文疎卜式，尚少棄馮唐。","由是推天運，從茲樂性場。","籠禽放高翥，霧豹得深藏。","世慮休相擾，身謀且自強。","猶須務衣食，未免事農桑。","薙草通三徑，開田占一坊。","晝扉扃白版，夜碓埽黃粱。","隙地治場圃，閑時糞土疆。","枳籬編刺夾，薤壟擘科秧。","穡力嫌身病，農心願歲穰。","朝衣典杯酒，佩劒博牛羊。","困倚栽松鍤，飢提采蕨筐。","引泉來後澗，移竹下前岡。","生計雖勤苦，家資甚渺茫。","塵埃常滿甑，錢帛少盈囊。","弟病仍扶杖，妻愁不出房。","傳衣念繿縷，舉案笑糟糠。","犬吠村胥鬧，蟬鳴織婦忙。","納租看縣貼，輸粟問軍倉。","夕歇攀村樹，秋行繞野塘。","雲容陰慘澹，月色冷悠揚。","蕎麥鋪花白，棠棃間葉黃。","早寒風摵摵，新霽月蒼蒼。","園菜迎霜死，庭蕪過雨荒。","檐空愁宿燕，壁闇思啼螿。","眼爲看書損，肱因運甓傷。","病骸渾似木，老鬢欲成霜。","少睡知年長，端憂覺夜長。","舊遊多廢忘，往事偶思量。","忽憶煙霄路，常陪劒履行。","登朝思檢束，入閣學趨蹌。","命偶風雲會，恩覃雨露霶。","霑枯發枝葉，磨鈍起鋒鋩。","崔閤連鑣騖，錢兄接翼翔。","齊竽混韶夏，燕石廁琳琅。","同日升金馬，分宵直未央。","共詞加寵命，合表謝恩光。","廐馬驕初跨，天廚味始嘗。","朝晡頒餅餌，寒暑賜衣裳。","對秉鵝毛筆，俱含雞舌香。","青縑衾薄絮，朱裏幕高張。","晝食恆連案，宵眠每竝牀。","差肩承詔旨，連署進封章。","起草偏同視，疑文最共詳。","滅私容點竄，窮理析毫芒。","便共輸肝膽，何曾異肺腸。","慎微參石奮，決密與張湯。","禁闥青交瑣，宮垣紫界牆。","井闌排菡萏，檐瓦鬬鴛鴦。","樓額題鳷鵲，池心浴鳳凰。","風枝萬年動，溫樹四時芳。","宿露凝金掌，晨暉上璧璫。","砌筠塗綠粉，庭果滴紅漿。","曉從朝興慶，春陪宴柏梁。","傳呼鞭索索，拜舞珮鏘鏘。","仙仗環雙闕，神兵闢兩廂。","火飜紅尾斾，冰卓白竿槍。","滉瀁經魚藻，深沈近浴堂。","分庭皆命婦，對院即儲皇。","貴主冠浮動，親王轡鬧裝。","金鈿相照耀，朱紫間熒煌。","毬簇桃花綺，歌巡竹葉觴。","窪銀中貴帶，昂黛內人妝。","賜禊東城下，頒酺曲水傍。","尊罍分聖酒，妓樂借仙倡。","淺酌看紅藥，徐吟把綠楊。","宴迴過御陌，行歇入僧房。","白鹿原東脚，青龍寺北廊。","望春花景暖，避暑竹風涼。","下直閑如社，尋芳醉似狂。","有時還後到，無處不相將。","雞鶴初雖雜，蕭蘭久乃彰。","來燕隗貴重，去魯孔恓惶。","聚散期難定，飛沈勢不常。","五年同晝夜，一別似參商。","屈折孤生竹，銷摧百鍊鋼。","途窮任顦顇，道在肯徬徨。","尚念遺簪折，仍憐病雀瘡。","卹寒分賜帛，救餒減餘糧。","藥物來盈裹，書題寄滿箱。","殷勤翰林主，珍重禮闈郎。","喣沫誠多謝，摶扶豈所望。","提攜勞氣力，吹簸不飛揚。","拙劣才何用，龍鍾分自當。","妝嫫徒費黛，磨甋詎成璋。","習隱將時背，干名與道妨。","外身宗老氏，齊物學蒙莊。","疎放遺千慮，愚蒙守一方。","樂天無怨歎，倚命不劻勷。","憤懣胷須豁，交加臂莫攘。","珠沈猶是寶，金躍未爲祥。","泥尾休搖掉，灰心罷激昂。","漸閑親道友，因病事醫王。","息亂歸禪定，存神入坐亡。","斷癡求慧劒，濟苦得慈航。","不動爲吾志，無何是我鄉。","可憐身與世，從此兩相忘。"]', '["聖代元和歲，闲居渭水陽。","不才甘命舛，多幸遇时康。","朝野分倫序，賢愚定否臧。","重文疎卜式，尚少棄馮唐。","由是推天運，從茲乐性場。","籠禽放高翥，霧豹得深藏。","世慮休相擾，身謀且自強。","猶須務衣食，未免事農桑。","薙草通三徑，开田占一坊。","晝扉扃白版，夜碓埽黄粱。","隙地治場圃，闲时糞土疆。","枳籬編刺夾，薤壟擘科秧。","穡力嫌身病，農心願歲穰。","朝衣典杯酒，佩劒博牛羊。","困倚栽松鍤，飢提采蕨筐。","引泉来後澗，移竹下前岡。","生計雖勤苦，家資甚渺茫。","塵埃常满甑，錢帛少盈囊。","弟病仍扶杖，妻愁不出房。","傳衣念繿縷，舉案笑糟糠。","犬吠村胥鬧，蟬鳴织婦忙。","納租看縣貼，輸粟问軍倉。","夕歇攀村樹，秋行繞野塘。","云容陰慘澹，月色冷悠揚。","蕎麦鋪花白，棠棃间葉黄。","早寒风摵摵，新霽月蒼蒼。","园菜迎霜死，庭蕪過雨荒。","檐空愁宿燕，壁闇思啼螿。","眼爲看书損，肱因運甓傷。","病骸渾似木，老鬢欲成霜。","少睡知年长，端憂覺夜长。","旧游多廢忘，往事偶思量。","忽憶煙霄路，常陪劒履行。","登朝思檢束，入閣学趨蹌。","命偶风云會，恩覃雨露霶。","霑枯發枝葉，磨鈍起鋒鋩。","崔閤連鑣騖，錢兄接翼翔。","齊竽混韶夏，燕石廁琳琅。","同日升金马，分宵直未央。","共词加寵命，合表謝恩光。","廐马驕初跨，天廚味始嘗。","朝晡頒餅餌，寒暑賜衣裳。","对秉鵝毛笔，俱含雞舌香。","青縑衾薄絮，朱裏幕高張。","晝食恆連案，宵眠每竝牀。","差肩承詔旨，連署進封章。","起草偏同視，疑文最共詳。","滅私容点竄，窮理析毫芒。","便共輸肝膽，何曾異肺腸。","慎微參石奮，決密與張湯。","禁闥青交瑣，宮垣紫界牆。","井闌排菡萏，檐瓦鬬鴛鴦。","楼額題鳷鵲，池心浴鳳凰。","风枝万年动，溫樹四时芳。","宿露凝金掌，晨暉上璧璫。","砌筠塗綠粉，庭果滴紅漿。","晓從朝兴慶，春陪宴柏梁。","傳呼鞭索索，拜舞珮鏘鏘。","仙仗环雙闕，神兵闢兩廂。","火飜紅尾斾，冰卓白竿槍。","滉瀁經鱼藻，深沈近浴堂。","分庭皆命婦，对院即儲皇。","貴主冠浮动，親王轡鬧裝。","金鈿相照耀，朱紫间熒煌。","毬簇桃花綺，歌巡竹葉觴。","窪銀中貴带，昂黛內人妝。","賜禊东城下，頒酺曲水傍。","尊罍分聖酒，妓乐借仙倡。","淺酌看紅藥，徐吟把綠楊。","宴迴過御陌，行歇入僧房。","白鹿原东脚，青龙寺北廊。","望春花景暖，避暑竹风涼。","下直闲如社，尋芳醉似狂。","有时還後到，無处不相將。","雞鹤初雖杂，蕭蘭久乃彰。","来燕隗貴重，去魯孔恓惶。","聚散期难定，飞沈勢不常。","五年同晝夜，一別似參商。","屈折孤生竹，銷摧百鍊鋼。","途窮任顦顇，道在肯徬徨。","尚念遺簪折，仍怜病雀瘡。","卹寒分賜帛，救餒減餘糧。","藥物来盈裹，书題寄满箱。","殷勤翰林主，珍重禮闈郎。","喣沫誠多謝，摶扶豈所望。","提携勞氣力，吹簸不飞揚。","拙劣才何用，龙鍾分自當。","妝嫫徒費黛，磨甋詎成璋。","習隐將时背，干名與道妨。","外身宗老氏，齊物学蒙莊。","疎放遺千慮，愚蒙守一方。","乐天無怨歎，倚命不劻勷。","憤懣胷須豁，交加臂莫攘。","珠沈猶是寶，金躍未爲祥。","泥尾休搖掉，灰心罷激昂。","漸闲親道友，因病事醫王。","息亂归禪定，存神入坐亡。","斷癡求慧劒，濟苦得慈航。","不动爲吾志，無何是我乡。","可怜身與世，從此兩相忘。"]', '诗', 'shi', '', NULL, '渭村退居寄禮部崔侍郎翰林錢舍人詩一百韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3aabefe5-fd34-4382-a15f-2af4412f7749', '酬盧祕書二十韻', '酬盧祕书二十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["謬歷文場選，慙非翰苑才。","雲霄高暫致，毛羽弱先摧。","識分忘軒冕，知歸返草萊。","杜陵書積蠹，豐獄劒生苔。","晦厭鳴雞雨，春驚震蟄雷。","舊恩收墜履，新律動寒灰。","鳳詔容徐起，鵷行許重陪。","衰顏雖拂拭，蹇步尚低徊。","睡少鐘偏警，行遲漏苦摧。","風霜趁朝去，泥雪拜陵迴。","上感君猶念，傍慙友或推。","石頑鐫費匠，女醜嫁勞媒。","倏忽青春度，奔波白日頹。","性將時共背，病與老俱來。","聞有蓬壺客，知懷杞梓材。","世家標甲第，官職滯麟臺。","筆盡鉛黃點，詩成錦繡堆。","嘗思豁雲霧，忽喜訪塵埃。","心爲論文合，眉因勸善開。","不勝珍重意，滿袖寫瓊瓌。"]', '["謬歷文場選，慙非翰苑才。","云霄高暫致，毛羽弱先摧。","識分忘軒冕，知归返草萊。","杜陵书積蠹，豐獄劒生苔。","晦厭鳴雞雨，春驚震蟄雷。","旧恩收墜履，新律动寒灰。","鳳詔容徐起，鵷行許重陪。","衰顏雖拂拭，蹇步尚低徊。","睡少鐘偏警，行遲漏苦摧。","风霜趁朝去，泥雪拜陵迴。","上感君猶念，傍慙友或推。","石頑鐫費匠，女醜嫁勞媒。","倏忽青春度，奔波白日頹。","性將时共背，病與老俱来。","闻有蓬壺客，知懷杞梓材。","世家標甲第，官職滯麟台。","笔尽鉛黄点，诗成錦繡堆。","嘗思豁云霧，忽喜訪塵埃。","心爲論文合，眉因勸善开。","不勝珍重意，满袖寫瓊瓌。"]', '诗', 'shi', '', NULL, '酬盧祕書二十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9df347d9-fda4-43fc-bd6d-285d8e325cba', '題盧祕書夏日新栽竹二十韻', '題盧祕书夏日新栽竹二十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["湘竹初封植，盧生此考槃。","久持霜節苦，新託露根難。","等度須當砌，疎稠要滿闌。","買憐分薄俸，栽稱作閑官。","葉翦藍羅碎，莖抽玉琯端。","幾聲清淅瀝，一簇綠檀欒。","未夜青嵐入，先秋白露團。","拂肩搖翡翠，熨手弄琅玕。","韻透窗風起，陰鋪砌月殘。","炎天聞覺冷，窄地見疑寬。","梢動勝搖扇，枝低好挂冠。","碧籠煙幕幕，珠灑雨珊珊。","晚籜晴雲展，陰芽蟄虺蟠。","愛從抽馬策，惜未截魚竿。","松韻徒煩聽，桃夭不足觀。","梁慙當家杏，臺陋本司蘭。","撐撥詩人興，勾牽酒客歡。","靜連蘆簟滑，涼拂葛衣單。","豈止消時暑，應能保歲寒。","莫同凡草木，一種夏中看。"]', '["湘竹初封植，盧生此考槃。","久持霜節苦，新託露根难。","等度須當砌，疎稠要满闌。","買怜分薄俸，栽稱作闲官。","葉翦藍羅碎，莖抽玉琯端。","幾声清淅瀝，一簇綠檀欒。","未夜青嵐入，先秋白露團。","拂肩搖翡翠，熨手弄琅玕。","韻透窗风起，陰鋪砌月殘。","炎天闻覺冷，窄地见疑寬。","梢动勝搖扇，枝低好挂冠。","碧籠煙幕幕，珠灑雨珊珊。","晚籜晴云展，陰芽蟄虺蟠。","愛從抽马策，惜未截鱼竿。","松韻徒煩听，桃夭不足观。","梁慙當家杏，台陋本司蘭。","撐撥诗人兴，勾牽酒客歡。","静連蘆簟滑，涼拂葛衣單。","豈止消时暑，應能保歲寒。","莫同凡草木，一種夏中看。"]', '诗', 'shi', '', NULL, '題盧祕書夏日新栽竹二十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f44a8e5-f5ba-4ad8-804f-5114b0e5f317', '渭村酬李二十見寄', '渭村酬李二十见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["百里音書何太遲，暮秋把得暮春詩。","柳條綠日君相憶，棃葉紅時我始知。","莫歎學官貧冷落，猶勝村客病支離。","形容意緒遙看取，不似華陽觀裏時。"]', '["百里音书何太遲，暮秋把得暮春诗。","柳條綠日君相憶，棃葉紅时我始知。","莫歎学官貧冷落，猶勝村客病支離。","形容意緒遙看取，不似华陽观裏时。"]', '诗', 'shi', '', NULL, '渭村酬李二十見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d144f4c-3df5-42d7-962c-bdae024e261d', '初授贊善大夫早朝寄李二十助教', '初授贊善大夫早朝寄李二十助教', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["病身初謁青宮日，衰貌新垂白髮年。","寂莫曹司非熱地，蕭條風雪是寒天。","遠坊早起常侵鼓，瘦馬行遲苦費鞭。","一種共君官職冷，不如猶得日高眠。"]', '["病身初謁青宮日，衰貌新垂白髮年。","寂莫曹司非熱地，蕭條风雪是寒天。","远坊早起常侵鼓，瘦马行遲苦費鞭。","一種共君官職冷，不如猶得日高眠。"]', '诗', 'shi', '', NULL, '初授贊善大夫早朝寄李二十助教 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39aaa65d-42e4-46cd-af9e-2e9b2d956802', '欲與元八卜鄰先有是贈', '欲與元八卜鄰先有是贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["平生心迹最相親，欲隱牆東不爲身。","明月好同三徑夜，綠楊宜作兩家春。","每因暫出猶思伴，豈得安居不擇鄰。","何獨終身數相見，子孫長作隔牆人。"]', '["平生心迹最相親，欲隐牆东不爲身。","明月好同三徑夜，綠楊宜作兩家春。","每因暫出猶思伴，豈得安居不擇鄰。","何独終身數相见，子孫长作隔牆人。"]', '诗', 'shi', '', NULL, '欲與元八卜鄰先有是贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('607e1f98-5d6e-4c0f-81de-f309b22c882f', '遊城南留元九李二十晚歸', '游城南留元九李二十晚归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老遊春飲莫相違，不獨花稀人亦稀。","更勸殘杯看日影，猶應趁得鼓聲歸。"]', '["老游春饮莫相違，不独花稀人亦稀。","更勸殘杯看日影，猶應趁得鼓声归。"]', '诗', 'shi', '', NULL, '遊城南留元九李二十晚歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5ea6abb-206b-4ae2-8b7a-88e8f30e5343', '廣宣上人以應制詩見示因以贈之詔許上人居安國寺紅樓院以詩供奉', '廣宣上人以應制诗见示因以贈之詔許上人居安国寺紅楼院以诗供奉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["道林談論惠休詩，一到人天便作師。","香積筵承紫泥詔，昭陽歌唱碧雲詞。","紅樓許住請銀鑰，翠輦陪行蹋玉墀。","惆悵甘泉曾侍從，與君前後不同時。"]', '["道林談論惠休诗，一到人天便作師。","香積筵承紫泥詔，昭陽歌唱碧云词。","紅楼許住請銀鑰，翠輦陪行蹋玉墀。","惆悵甘泉曾侍從，與君前後不同时。"]', '诗', 'shi', '', NULL, '廣宣上人以應制詩見示因以贈之詔許上人居安國寺紅樓院以詩供奉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e5a55aa-7cdd-4002-8a69-6869754f5e7f', '重過祕書舊房因題長句', '重過祕书旧房因題长句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閣前下馬思裴回，第二房門手自開。","昔爲白面書郎去，今作蒼鬚贊善來。","吏人不識多新補，松竹相親是舊栽。","應有題牆名姓在，試將衫袖拂塵埃。"]', '["閣前下马思裴回，第二房门手自开。","昔爲白面书郎去，今作蒼鬚贊善来。","吏人不識多新補，松竹相親是旧栽。","應有題牆名姓在，試將衫袖拂塵埃。"]', '诗', 'shi', '', NULL, '重過祕書舊房因題長句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26796388-eb6e-4c32-8fa4-6519c9064033', '重到城七絕句 見元九', '重到城七絕句 见元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["容貌一日減一日，心情十分無九分。","每逢陌路猶嗟歎，何況今朝是見君。"]', '["容貌一日減一日，心情十分無九分。","每逢陌路猶嗟歎，何況今朝是见君。"]', '诗', 'shi', '', NULL, '重到城七絕句 見元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b97e361-0652-4cef-85d3-043181f3b9f0', '重到城七絕句 高相宅', '重到城七絕句 高相宅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["青苔故里懷恩地，白髮新生抱病身。","涕淚雖多無哭處，永寧門館屬他人。"]', '["青苔故里懷恩地，白髮新生抱病身。","涕泪雖多無哭处，永寧门館屬他人。"]', '诗', 'shi', '', NULL, '重到城七絕句 高相宅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5224e822-abba-4f9d-888e-de26a4b8b3cc', '重到城七絕句 張十八', '重到城七絕句 張十八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["諫垣幾見遷遺補，憲府頻聞轉殿監。","獨有詠詩張太祝，十年不改舊官銜。"]', '["諫垣幾见遷遺補，憲府頻闻轉殿監。","独有詠诗張太祝，十年不改旧官銜。"]', '诗', 'shi', '', NULL, '重到城七絕句 張十八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bb4d0cf-8849-4ca7-9089-15bac9ba3267', '重到城七絕句 劉家花', '重到城七絕句 劉家花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["劉家牆上花還發，李十門前草又春。","處處傷心心始悟，多情不及少情人。"]', '["劉家牆上花還發，李十门前草又春。","处处傷心心始悟，多情不及少情人。"]', '诗', 'shi', '', NULL, '重到城七絕句 劉家花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebc3d85d-39f0-4519-b71c-260cb78b733c', '重到城七絕句 裴五', '重到城七絕句 裴五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫怪相逢無笑語，感今思舊戟門前。","張家伯仲偏相似，每見清揚一惘然。"]', '["莫怪相逢無笑語，感今思旧戟门前。","張家伯仲偏相似，每见清揚一惘然。"]', '诗', 'shi', '', NULL, '重到城七絕句 裴五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ec3d679-67c2-440a-aa7f-aab38ac6c3e3', '重到城七絕句 仇家酒', '重到城七絕句 仇家酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["年年老去歡情少，處處春來感事深。","時到仇家非愛酒，醉時心勝醒時心。"]', '["年年老去歡情少，处处春来感事深。","时到仇家非愛酒，醉时心勝醒时心。"]', '诗', 'shi', '', NULL, '重到城七絕句 仇家酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ffc5c7d-1092-4b09-b831-14792b437fc4', '重到城七絕句 恆寂師', '重到城七絕句 恆寂師', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["舊遊分散人零落，如此傷心事幾條。","會逐禪師坐禪去，一時滅盡定中消。"]', '["旧游分散人零落，如此傷心事幾條。","會逐禪師坐禪去，一时滅尽定中消。"]', '诗', 'shi', '', NULL, '重到城七絕句 恆寂師 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5644e203-bc2c-4dba-a58a-d29d0e5be78a', '靖安北街贈李二十', '靖安北街贈李二十', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["榆莢拋錢柳展眉，兩人竝馬語行遲。","還似往年安福寺，共君私試却迴時。"]', '["榆莢拋錢柳展眉，兩人竝马語行遲。","還似往年安福寺，共君私試却迴时。"]', '诗', 'shi', '', NULL, '靖安北街贈李二十 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a5451f4-2641-4c07-97cd-c7a8b2afb972', '重傷小女子', '重傷小女子', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["學人言語凭牀行，嫩似花房脆似瓊。","纔知恩愛迎三歲，未辨東西過一生。","汝異下殤應殺禮，吾非上聖詎忘情。","傷心自歎鳩巢拙，長墮春雛養不成。"]', '["学人言語凭牀行，嫩似花房脆似瓊。","纔知恩愛迎三歲，未辨东西過一生。","汝異下殤應殺禮，吾非上聖詎忘情。","傷心自歎鳩巢拙，长墮春雛養不成。"]', '诗', 'shi', '', NULL, '重傷小女子 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba717d99-48a7-4d9c-890f-384c0dafd39d', '過顏處士墓', '過顏处士墓', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["向墳道徑沒荒榛，滿室詩書積闇塵。","長夜肯教黃壤曉，悲風不許白楊春。","簞瓢顏子生仍促，布被黔婁死更貧。","未會悠悠上天意，惜將富壽與何人。"]', '["向墳道徑沒荒榛，满室诗书積闇塵。","长夜肯教黄壤晓，悲风不許白楊春。","簞瓢顏子生仍促，布被黔婁死更貧。","未會悠悠上天意，惜將富壽與何人。"]', '诗', 'shi', '', NULL, '過顏處士墓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('812d6cfd-a411-41d1-8ddd-8ba9a3251f5b', '題周皓大夫新亭子二十二韻', '題周皓大夫新亭子二十二韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["東道常爲主，南亭別待賓。","規模何日創，景致一時新。","廣砌羅紅藥，疎窗蔭綠筠。","鎖開賓閣曉，梯上妓樓春。","置醴寧三爵，加籩過八珍。","茶香飄紫筍，膾縷落紅鱗。","輝赫車輿鬧，珍奇鳥獸馴。","獼猴看櫪馬，鸚鵡喚家人。","錦額簾高卷，銀花醆慢巡。","勸嘗光祿酒，許看洛川神。","斂翠凝歌黛，流香動舞巾。","帬飜繡鸂鶒，梳陷鈿麒麟。","笛怨音含楚，箏嬌語帶秦。","侍兒催畫燭，醉客吐文茵。","投轄多連夜，鳴珂便達晨。","入朝紆紫綬，待漏擁朱輪。","貴介交三事，光榮照四鄰。","甘濃將奉客，穩暖不緣身。","十載歌鐘地，三朝節鉞臣。","愛才心倜儻，敦舊禮殷勤。","門以招賢盛，家因好事貧。","始知豪傑意，富貴爲交親。"]', '["东道常爲主，南亭別待賓。","規模何日創，景致一时新。","廣砌羅紅藥，疎窗蔭綠筠。","鎖开賓閣晓，梯上妓楼春。","置醴寧三爵，加籩過八珍。","茶香飄紫筍，膾縷落紅鱗。","輝赫车輿鬧，珍奇鸟獸馴。","獼猴看櫪马，鸚鵡喚家人。","錦額簾高卷，銀花醆慢巡。","勸嘗光祿酒，許看洛川神。","斂翠凝歌黛，流香动舞巾。","帬飜繡鸂鶒，梳陷鈿麒麟。","笛怨音含楚，箏嬌語带秦。","侍兒催畫燭，醉客吐文茵。","投轄多連夜，鳴珂便達晨。","入朝紆紫綬，待漏擁朱輪。","貴介交三事，光榮照四鄰。","甘濃將奉客，穩暖不緣身。","十載歌鐘地，三朝節鉞臣。","愛才心倜儻，敦旧禮殷勤。","门以招賢盛，家因好事貧。","始知豪傑意，富貴爲交親。"]', '诗', 'shi', '', NULL, '題周皓大夫新亭子二十二韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bae6fbfb-b1e6-4b06-b31d-1f378bba403c', '賦得聽邊鴻', '賦得听邊鴻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["驚風吹起塞鴻羣，半拂平沙半入雲。","爲問昭君月下聽，何如蘇武雪中聞。"]', '["驚风吹起塞鴻羣，半拂平沙半入云。","爲问昭君月下听，何如蘇武雪中闻。"]', '诗', 'shi', '', NULL, '賦得聽邊鴻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76457d1c-1c6c-4004-b360-99264de9b6d4', '見楊弘貞詩賦因題絕句以自諭', '见楊弘貞诗賦因題絕句以自諭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["賦句詩章妙入神，未年三十即無身。","常嗟薄命形顦顇，若比弘貞是幸人。"]', '["賦句诗章妙入神，未年三十即無身。","常嗟薄命形顦顇，若比弘貞是幸人。"]', '诗', 'shi', '', NULL, '見楊弘貞詩賦因題絕句以自諭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12df34cd-e7ce-4f04-9a1c-bccbdf2beea7', '病中早春', '病中早春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今朝枕上覺頭輕，強起階前試脚行。","羶膩斷來無氣力，風痰惱得少心情。","暖消霜瓦津初合，寒減冰渠凍不成。","唯有愁人鬢間雪，不隨春盡逐春生。"]', '["今朝枕上覺头轻，強起階前試脚行。","羶膩斷来無氣力，风痰惱得少心情。","暖消霜瓦津初合，寒減冰渠凍不成。","唯有愁人鬢间雪，不隨春尽逐春生。"]', '诗', 'shi', '', NULL, '病中早春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b896001-80aa-4294-b01e-9cb59262e700', '送人貶信州判官', '送人貶信州判官', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["地僻山深古上饒，土風貧薄道程遙。","不唯遷客須恓屑，見說居人也寂寥。","溪畔毒沙藏水弩，城頭枯樹下山魈。","若於此郡爲卑吏，刺史廳前又折腰。"]', '["地僻山深古上饒，土风貧薄道程遙。","不唯遷客須恓屑，见说居人也寂寥。","溪畔毒沙藏水弩，城头枯樹下山魈。","若於此郡爲卑吏，刺史廳前又折腰。"]', '诗', 'shi', '', NULL, '送人貶信州判官 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16e30743-0747-4459-8d32-6e2ec5973494', '曲江醉後贈諸親故', '曲江醉後贈諸親故', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["郭東丘墓何年客，江畔風光幾日春。","只合殷勤逐杯酒，不須疎索向交親。","中天或有長生藥，下界應無不死人。","除却醉來開口笑，世間何事更關身。"]', '["郭东丘墓何年客，江畔风光幾日春。","只合殷勤逐杯酒，不須疎索向交親。","中天或有长生藥，下界應無不死人。","除却醉来开口笑，世间何事更关身。"]', '诗', 'shi', '', NULL, '曲江醉後贈諸親故 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('876c276a-c0db-410a-a509-6df178ef8a97', '和元八侍御升平新居四絕句 看花屋', '和元八侍御升平新居四絕句 看花屋', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["忽驚映樹新開屋，却似當檐故種花。","可惜年年紅似火，今春始得屬元家。"]', '["忽驚映樹新开屋，却似當檐故種花。","可惜年年紅似火，今春始得屬元家。"]', '诗', 'shi', '', NULL, '和元八侍御升平新居四絕句 看花屋 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b85263b-b9a1-4cbd-b6ce-90d33cda12da', '和元八侍御升平新居四絕句 累土山', '和元八侍御升平新居四絕句 累土山', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["堆土漸高山意出，終南移入戶庭間。","玉峰藍水應惆悵，恐見新山望舊山。"]', '["堆土漸高山意出，終南移入戶庭间。","玉峰藍水應惆悵，恐见新山望旧山。"]', '诗', 'shi', '', NULL, '和元八侍御升平新居四絕句 累土山 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3814f20d-965f-415d-8448-3eab7b3f51a6', '和元八侍御升平新居四絕句 高亭', '和元八侍御升平新居四絕句 高亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["亭脊太高君莫拆，東家留取當西山。","好看落日斜銜處，一片春嵐映半環。"]', '["亭脊太高君莫拆，东家留取當西山。","好看落日斜銜处，一片春嵐映半环。"]', '诗', 'shi', '', NULL, '和元八侍御升平新居四絕句 高亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc73dcdb-5250-4285-8365-0308f3060100', '和元八侍御升平新居四絕句 松樹', '和元八侍御升平新居四絕句 松樹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白金換得青松樹，君既先栽我不栽。","幸有西風易憑仗，夜深偷送好聲來。"]', '["白金換得青松樹，君既先栽我不栽。","幸有西风易憑仗，夜深偷送好声来。"]', '诗', 'shi', '', NULL, '和元八侍御升平新居四絕句 松樹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c5c6b89-7127-47d5-9500-8e1188ffeff9', '醉後却寄元九', '醉後却寄元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蒲池村裏悤悤別，灃水橋邊兀兀迴。","行到城門殘酒醒，萬重離恨一時來。"]', '["蒲池村裏悤悤別，灃水橋邊兀兀迴。","行到城门殘酒醒，万重離恨一时来。"]', '诗', 'shi', '', NULL, '醉後却寄元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74e567ab-47ef-4b3e-9aba-77cbee35aa1b', '重寄', '重寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蕭散弓驚雁，分飛劒化龍。","悠悠天地內，不死會相逢。"]', '["蕭散弓驚雁，分飞劒化龙。","悠悠天地內，不死會相逢。"]', '诗', 'shi', '', NULL, '重寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36a04dff-fd44-4c7d-bab2-77bd86f46c1c', '李十一舍人松園飲小酎酒得元八侍御詩敘云在臺中推院有鞫獄之苦即事書懷因酬四韻', '李十一舍人松园饮小酎酒得元八侍御诗敘云在台中推院有鞫獄之苦即事书懷因酬四韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["愛酒舍人開小酌，能文御史寄新詩。","亂松園裏醉相憶，古柏廳前忙不知。","早夏我當逃暑日，晚衙君是慮囚時。","唯應清夜無公事，新草亭中好一期。"]', '["愛酒舍人开小酌，能文御史寄新诗。","亂松园裏醉相憶，古柏廳前忙不知。","早夏我當逃暑日，晚衙君是慮囚时。","唯應清夜無公事，新草亭中好一期。"]', '诗', 'shi', '', NULL, '李十一舍人松園飲小酎酒得元八侍御詩敘云在臺中推院有鞫獄之苦即事書懷因酬四韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd09198f-11df-4dab-8977-8c545b4db39e', '重到華陽觀舊居', '重到华陽观旧居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憶昔初年三十二，當時秋思已難堪。","若爲重入華陽院，病鬢愁心四十三。"]', '["憶昔初年三十二，當时秋思已难堪。","若爲重入华陽院，病鬢愁心四十三。"]', '诗', 'shi', '', NULL, '重到華陽觀舊居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('555b326c-f465-4210-b4f0-526c5491a05e', '荅勸酒', '荅勸酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫怪近來都不飲，幾迴因醉却霑巾。","誰料平生狂酒客，如今變作酒悲人。"]', '["莫怪近来都不饮，幾迴因醉却霑巾。","誰料平生狂酒客，如今变作酒悲人。"]', '诗', 'shi', '', NULL, '荅勸酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14ce8e49-2d68-4543-b72d-e4bd7ecb3987', '題王侍御池亭', '題王侍御池亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朱門深鎖春池滿，岸落薔薇水浸莎。","畢竟林塘誰是主，主人來少客來多。"]', '["朱门深鎖春池满，岸落薔薇水浸莎。","畢竟林塘誰是主，主人来少客来多。"]', '诗', 'shi', '', NULL, '題王侍御池亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d8d628f-c08e-4f0d-982c-95efe6a40a3c', '聽水部吳員外新詩因贈絕句', '听水部吳員外新诗因贈絕句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朱紱仙郎白雪歌，和人雖少愛人多。","明朝說與詩人道，水部如今不姓何。"]', '["朱紱仙郎白雪歌，和人雖少愛人多。","明朝说與诗人道，水部如今不姓何。"]', '诗', 'shi', '', NULL, '聽水部吳員外新詩因贈絕句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baaa3909-b38d-4757-bfea-d031fa0e37d1', '雨夜憶元九', '雨夜憶元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天陰一日便堪愁，何況連宵雨不休。","一種雨中君最苦，偏梁閣道向通州。"]', '["天陰一日便堪愁，何況連宵雨不休。","一種雨中君最苦，偏梁閣道向通州。"]', '诗', 'shi', '', NULL, '雨夜憶元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd8372bf-08e2-42bf-9aff-7e3b5d0399af', '雨中攜元九詩訪元八侍御', '雨中携元九诗訪元八侍御', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["微之詩卷憶同開，假日多應不入臺。","好句無人堪共詠，衝泥蹋水就君來。"]', '["微之诗卷憶同开，假日多應不入台。","好句無人堪共詠，衝泥蹋水就君来。"]', '诗', 'shi', '', NULL, '雨中攜元九詩訪元八侍御 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0808cd5-9fd9-49d1-af58-6df17fa5802b', '贈楊祕書巨源', '贈楊祕书巨源', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["早聞一箭取遼城，相識雖新有故情。","清句三朝誰是敵，白鬚四海半爲兄。","貧家薙草時時入，瘦馬尋花處處行。","不用更教詩過好，折君官職是聲名。"]', '["早闻一箭取遼城，相識雖新有故情。","清句三朝誰是敵，白鬚四海半爲兄。","貧家薙草时时入，瘦马尋花处处行。","不用更教诗過好，折君官職是声名。"]', '诗', 'shi', '', NULL, '贈楊祕書巨源 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ecfca2c-c5d5-4829-8fb4-63903ba66297', '和武相公感韋令公舊池孔雀', '和武相公感韋令公旧池孔雀', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["索莫少顏色，池邊無主禽。","難收帶泥翅，易結著人心。","頂毳落殘碧，尾花銷闇金。","放歸飛不得，雲海故巢深。"]', '["索莫少顏色，池邊無主禽。","难收带泥翅，易結著人心。","頂毳落殘碧，尾花銷闇金。","放归飞不得，云海故巢深。"]', '诗', 'shi', '', NULL, '和武相公感韋令公舊池孔雀 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('233af831-6f24-48c0-bc3c-0f44459ef85f', '寄生衣與微之因題封上', '寄生衣與微之因題封上', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["淺色縠衫輕似霧，紡花紗袴薄於雲。","莫嫌輕薄但知著，猶恐通州熱殺君。"]', '["淺色縠衫轻似霧，紡花紗袴薄於云。","莫嫌轻薄但知著，猶恐通州熱殺君。"]', '诗', 'shi', '', NULL, '寄生衣與微之因題封上 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('554c469d-b686-4278-81ef-850108c3a453', '白牡丹', '白牡丹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白花冷澹無人愛，亦占芳名道牡丹。","應似東宮白贊善，被人還喚作朝官。"]', '["白花冷澹無人愛，亦占芳名道牡丹。","應似东宮白贊善，被人還喚作朝官。"]', '诗', 'shi', '', NULL, '白牡丹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf33f5b7-bdc3-4aaf-b3a1-090b9ebc0089', '夢舊', '梦旧', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["別來老大苦修道，鍊得離心成死灰。","平生憶念消磨盡，昨夜因何入夢來。"]', '["別来老大苦修道，鍊得離心成死灰。","平生憶念消磨尽，昨夜因何入梦来。"]', '诗', 'shi', '', NULL, '夢舊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('743667f0-25db-4081-9794-1cb81a5b649c', '戲題盧祕書新移薔薇', '戲題盧祕书新移薔薇', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風動翠條腰嫋娜，露垂紅萼淚闌干。","移他到此須爲主，不別花人莫使看。"]', '["风动翠條腰嫋娜，露垂紅萼泪闌干。","移他到此須爲主，不別花人莫使看。"]', '诗', 'shi', '', NULL, '戲題盧祕書新移薔薇 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0fec5b0d-3a4d-4609-bc87-cdb36657c54f', '曲江夜歸聞元八見訪', '曲江夜归闻元八见訪', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自入臺來見面稀，班中遙得揖容輝。","早知相憶來相訪，悔待江頭明月歸。"]', '["自入台来见面稀，班中遙得揖容輝。","早知相憶来相訪，悔待江头明月归。"]', '诗', 'shi', '', NULL, '曲江夜歸聞元八見訪 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8dae3d5-aa36-4911-b3ae-6609da96e5b4', '苦熱題恆寂師禪室', '苦熱題恆寂師禪室', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人人避暑走如狂，獨有禪師不出房。","可是禪房無熱到，但能心靜即身涼。"]', '["人人避暑走如狂，独有禪師不出房。","可是禪房無熱到，但能心静即身涼。"]', '诗', 'shi', '', NULL, '苦熱題恆寂師禪室 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4af04ec2-4fde-4a22-8847-3ee2dcb3f527', '微之到通州日授館未安見塵壁間有數行字讀之即僕舊詩其落句云淥水紅蓮一朵開千花百草無顏色然不知題者何人也微之吟歎不足因綴一章兼錄僕詩本同寄省其詩乃十五年前初及第時贈長安妓人阿輭絕句緬思往事杳若夢中懷舊感今因酬長句', '微之到通州日授館未安见塵壁间有數行字读之即僕旧诗其落句云淥水紅蓮一朵开千花百草無顏色然不知題者何人也微之吟歎不足因綴一章兼錄僕诗本同寄省其诗乃十五年前初及第时贈长安妓人阿輭絕句緬思往事杳若梦中懷旧感今因酬长句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["十五年前似夢遊，曾將詩句結風流。","偶助笑歌嘲阿輭，可知傳誦到通州。","昔教紅袖佳人唱，今遣青衫司馬愁。","惆悵又聞題處所，雨淋江館破牆頭。"]', '["十五年前似梦游，曾將诗句結风流。","偶助笑歌嘲阿輭，可知傳誦到通州。","昔教紅袖佳人唱，今遣青衫司马愁。","惆悵又闻題处所，雨淋江館破牆头。"]', '诗', 'shi', '', NULL, '微之到通州日授館未安見塵壁間有數行字讀之即僕舊詩其落句云淥水紅蓮一朵開千花百草無顏色然不知題者何人也微之吟歎不足因綴一章兼錄僕詩本同寄省其詩乃十五年前初及第時贈長安妓人阿輭絕句緬思往事杳若夢中懷舊感今因酬長句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('484da055-ac5b-43ad-97a2-d5158c9c8ab5', '得微之到官後書備知通州之事悵然有感因成四章 一', '得微之到官後书備知通州之事悵然有感因成四章 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["來書子細說通州，州在山根峽岸頭。","四面千重火雲合，中心一道瘴江流。","蟲蛇白晝攔官道，蚊蚋黃昏撲郡樓。","何罪遣君居此地，天高無處問來由。"]', '["来书子細说通州，州在山根峽岸头。","四面千重火云合，中心一道瘴江流。","蟲蛇白晝攔官道，蚊蚋黄昏撲郡楼。","何罪遣君居此地，天高無处问来由。"]', '诗', 'shi', '', NULL, '得微之到官後書備知通州之事悵然有感因成四章 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd3baf45-b68c-4f2e-89d4-d2b7ba85afc1', '得微之到官後書備知通州之事悵然有感因成四章 二', '得微之到官後书備知通州之事悵然有感因成四章 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["匼匝巔山萬仞餘，人家應似甑中居。","寅年籬下多逢虎，亥日沙頭始賣魚。","衣斑梅雨長須熨，米澀畬田不解鉏。","努力安心過三考，已曾愁殺李尚書。"]', '["匼匝巔山万仞餘，人家應似甑中居。","寅年籬下多逢虎，亥日沙头始賣鱼。","衣斑梅雨长須熨，米澀畬田不解鉏。","努力安心過三考，已曾愁殺李尚书。"]', '诗', 'shi', '', NULL, '得微之到官後書備知通州之事悵然有感因成四章 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('469541fc-798f-4e96-841d-7805ad3d392b', '得微之到官後書備知通州之事悵然有感因成四章 三', '得微之到官後书備知通州之事悵然有感因成四章 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人稀地僻醫巫少，夏旱秋霖瘴瘧多。","老去一身須愛惜，別來四體得如何。","侏儒飽笑東方朔，薏苡讒憂馬伏波。","莫遣沈愁結成病，時時一唱濯纓歌。"]', '["人稀地僻醫巫少，夏旱秋霖瘴瘧多。","老去一身須愛惜，別来四體得如何。","侏儒飽笑东方朔，薏苡讒憂马伏波。","莫遣沈愁結成病，时时一唱濯纓歌。"]', '诗', 'shi', '', NULL, '得微之到官後書備知通州之事悵然有感因成四章 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e1d8586-038c-4508-929a-ba1e4d98a13b', '得微之到官後書備知通州之事悵然有感因成四章 四', '得微之到官後书備知通州之事悵然有感因成四章 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["通州海內恓惶地，司馬人間冗長官。","傷鳥有弦驚不定，臥龍無水動應難。","劒埋獄底誰深掘，松偃霜中盡冷看。","舉目爭能不惆悵，高車大馬滿長安。"]', '["通州海內恓惶地，司马人间冗长官。","傷鸟有弦驚不定，臥龙無水动應难。","劒埋獄底誰深掘，松偃霜中尽冷看。","舉目爭能不惆悵，高车大马满长安。"]', '诗', 'shi', '', NULL, '得微之到官後書備知通州之事悵然有感因成四章 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7b84bd0-de0c-4392-b5b6-8290dc25767e', '病中荅招飲者', '病中荅招饮者', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["顧我鏡中悲白髮，盡君花下醉青春。","不緣眼痛兼身病，可是尊前第二人。"]', '["顧我镜中悲白髮，尽君花下醉青春。","不緣眼痛兼身病，可是尊前第二人。"]', '诗', 'shi', '', NULL, '病中荅招飲者 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d25f80d3-39e0-4a22-9f6a-ea6cec174c6b', '燕子樓三首 一', '燕子楼三首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["滿窗明月滿簾霜，被冷燈殘拂臥牀。","燕子樓中霜月夜，秋來只爲一人長。"]', '["满窗明月满簾霜，被冷灯殘拂臥牀。","燕子楼中霜月夜，秋来只爲一人长。"]', '诗', 'shi', '', NULL, '燕子樓三首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('970f15b9-e204-4847-b3a3-b041bea2b444', '燕子樓三首 二', '燕子楼三首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鈿暈羅衫色似煙，幾回欲著即潸然。","自從不舞霓裳曲，疊在空箱十一年。"]', '["鈿暈羅衫色似煙，幾回欲著即潸然。","自從不舞霓裳曲，叠在空箱十一年。"]', '诗', 'shi', '', NULL, '燕子樓三首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38813485-6cdd-48ca-8620-11f4dcc822d6', '燕子樓三首 三', '燕子楼三首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今春有客洛陽回，曾到尚書墓上來。","見說白楊堪作柱，爭教紅粉不成灰。"]', '["今春有客洛陽回，曾到尚书墓上来。","见说白楊堪作柱，爭教紅粉不成灰。"]', '诗', 'shi', '', NULL, '燕子樓三首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc768485-8f28-4ee8-84ef-a30d3505fd7e', '初貶官過望秦嶺', '初貶官過望秦嶺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["草草辭家憂後事，遲遲去國問前途。","望秦嶺上回頭立，無限秋風吹白鬚。"]', '["草草辞家憂後事，遲遲去国问前途。","望秦嶺上回头立，無限秋风吹白鬚。"]', '诗', 'shi', '', NULL, '初貶官過望秦嶺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82bdecb5-27a0-48a0-88d9-6b128e770299', '藍橋驛見元九詩', '藍橋驛见元九诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["藍橋春雪君歸日，秦嶺秋風我去時。","每到驛亭先下馬，循牆繞柱覓君詩。"]', '["藍橋春雪君归日，秦嶺秋风我去时。","每到驛亭先下马，循牆繞柱覓君诗。"]', '诗', 'shi', '', NULL, '藍橋驛見元九詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc5fad98-8394-480c-8b1d-676f55559fc7', '韓公堆寄元九', '韓公堆寄元九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["韓公堆北澗西頭，冷雨涼風拂面秋。","努力南行少惆悵，江州猶似勝通州。"]', '["韓公堆北澗西头，冷雨涼风拂面秋。","努力南行少惆悵，江州猶似勝通州。"]', '诗', 'shi', '', NULL, '韓公堆寄元九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5843202c-c124-495f-a81b-85c0226f4b40', '發商州', '發商州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["商州館裏停三日，待得妻孥相逐行。","若比李三猶自勝，兒啼婦哭不聞聲。"]', '["商州館裏停三日，待得妻孥相逐行。","若比李三猶自勝，兒啼婦哭不闻声。"]', '诗', 'shi', '', NULL, '發商州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2a9164c-f186-4e8a-8636-4701c19e897f', '武關南見元九題山石榴見寄', '武关南见元九題山石榴见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["往來同路不同時，前後相思兩不知。","行過關門三四里，榴花不見見君詩。"]', '["往来同路不同时，前後相思兩不知。","行過关门三四里，榴花不见见君诗。"]', '诗', 'shi', '', NULL, '武關南見元九題山石榴見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('517ff7ae-a930-4c4d-a3fc-5798c75ad570', '紅鸚鵡', '紅鸚鵡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["安南遠進紅鸚鵡，色似桃花語似人。","文章辯慧皆如此，籠檻何年出得身。"]', '["安南远進紅鸚鵡，色似桃花語似人。","文章辯慧皆如此，籠檻何年出得身。"]', '诗', 'shi', '', NULL, '紅鸚鵡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03ccdb12-fd90-45ac-a7d1-ef8fbbb24465', '題四皓廟', '題四皓廟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["臥逃秦亂起安劉，舒卷如雲得自由。","若有精靈應笑我，不成一事謫江州。"]', '["臥逃秦亂起安劉，舒卷如云得自由。","若有精靈應笑我，不成一事謫江州。"]', '诗', 'shi', '', NULL, '題四皓廟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1256f876-e915-400b-b306-4c323bfc390c', '罷藥', '罷藥', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自學坐禪休服藥，從他時復病沈沈。","此身不要全彊健，彊健多生人我心。"]', '["自学坐禪休服藥，從他时复病沈沈。","此身不要全彊健，彊健多生人我心。"]', '诗', 'shi', '', NULL, '罷藥 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ad923b7-896f-4ea6-8440-bb231d4c2bf7', '白鷺', '白鷺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人生四十未全衰，我爲愁多白髮垂。","何故水邊雙白鷺，無愁頭上亦垂絲。"]', '["人生四十未全衰，我爲愁多白髮垂。","何故水邊雙白鷺，無愁头上亦垂絲。"]', '诗', 'shi', '', NULL, '白鷺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae9f57d5-a953-4d5a-b947-11f178c56f61', '襄陽舟夜', '襄陽舟夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["下馬襄陽郭，移舟漢陰驛。","秋風截江起，寒浪連天白。","本是多愁人，復此風波夕。"]', '["下马襄陽郭，移舟漢陰驛。","秋风截江起，寒浪連天白。","本是多愁人，复此风波夕。"]', '诗', 'shi', '', NULL, '襄陽舟夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('777a91d8-7915-4cdb-8065-40d1fa6321cd', '江夜舟行', '江夜舟行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["煙澹月濛濛，舟行夜色中。","江鋪滿槽水，帆展半檣風。","叫曙嗸嗸鴈，啼秋唧唧蟲。","只應催北客，早作白鬚翁。"]', '["煙澹月濛濛，舟行夜色中。","江鋪满槽水，帆展半檣风。","叫曙嗸嗸鴈，啼秋唧唧蟲。","只應催北客，早作白鬚翁。"]', '诗', 'shi', '', NULL, '江夜舟行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c60ee1e8-110c-421f-aa00-72ca7a28a06a', '紅藤杖', '紅藤杖', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["交親過滻別，車馬到江迴。","唯有紅藤杖，相隨萬里來。"]', '["交親過滻別，车马到江迴。","唯有紅藤杖，相隨万里来。"]', '诗', 'shi', '', NULL, '紅藤杖 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fff15ec-8eef-48d6-99a4-84994e6772b1', '江上吟元八絕句', '江上吟元八絕句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["大江深處月明時，一夜吟君小律詩。","應有水仙潛出聽，飜將唱作步虛詞。"]', '["大江深处月明时，一夜吟君小律诗。","應有水仙潛出听，飜將唱作步虛词。"]', '诗', 'shi', '', NULL, '江上吟元八絕句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ae94144-f199-4464-b862-817581348b97', '途中感秋', '途中感秋', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["節物行搖落，年顏坐變衰。","樹初黃葉日，人欲白頭時。","鄉國程程遠，親朋處處辭。","唯殘病與老，一步不相離。"]', '["節物行搖落，年顏坐变衰。","樹初黄葉日，人欲白头时。","乡国程程远，親朋处处辞。","唯殘病與老，一步不相離。"]', '诗', 'shi', '', NULL, '途中感秋 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b972cf6a-7e01-4f8e-aa5c-d1316da5539e', '登郢州白雪樓', '登郢州白雪楼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白雪樓中一望鄉，青山蔟蔟水茫茫。","朝來渡口逢京使，說道煙塵近洛陽。"]', '["白雪楼中一望乡，青山蔟蔟水茫茫。","朝来渡口逢京使，说道煙塵近洛陽。"]', '诗', 'shi', '', NULL, '登郢州白雪樓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db5b6d45-ab39-4b33-b2ed-2125c122d067', '舟夜贈內', '舟夜贈內', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三聲猨後垂鄉淚，一葉舟中載病身。","莫凭水窗南北望，月明月闇總愁人。"]', '["三声猨後垂乡泪，一葉舟中載病身。","莫凭水窗南北望，月明月闇總愁人。"]', '诗', 'shi', '', NULL, '舟夜贈內 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1cd654f7-70ac-4753-8418-81a90134313f', '逢舊', '逢旧', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我梳白髮添新恨，君埽青蛾減舊容。","應被傍人怪惆悵，少年離別老相逢。"]', '["我梳白髮添新恨，君埽青蛾減旧容。","應被傍人怪惆悵，少年離別老相逢。"]', '诗', 'shi', '', NULL, '逢舊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67b018ec-37ca-4b68-a8d5-2f2fbc6c26ff', '臼口阻風十日', '臼口阻风十日', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["洪濤白浪塞江津，處處邅迴事事迍。","世上方爲失途客，江頭又作阻風人。","魚鰕遇雨腥盈鼻，蚊蚋和煙癢滿身。","老大光陰能幾日，等閑臼口坐經旬。"]', '["洪濤白浪塞江津，处处邅迴事事迍。","世上方爲失途客，江头又作阻风人。","鱼鰕遇雨腥盈鼻，蚊蚋和煙癢满身。","老大光陰能幾日，等闲臼口坐經旬。"]', '诗', 'shi', '', NULL, '臼口阻風十日 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f79e1d06-86ce-4cba-b906-b0623d9dfc3e', '浦中夜泊', '浦中夜泊', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["暗上江隄還獨立，水風霜氣夜稜稜。","回看深浦停舟處，蘆荻花中一點燈。"]', '["暗上江隄還独立，水风霜氣夜稜稜。","回看深浦停舟处，蘆荻花中一点灯。"]', '诗', 'shi', '', NULL, '浦中夜泊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad55996e-9419-4dc2-bb37-05ea1b3287b7', '盧侍御與崔評事爲予於黃鶴樓置宴宴罷同望', '盧侍御與崔評事爲予於黄鹤楼置宴宴罷同望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江邊黃鶴古時樓，勞置華筵待我遊。","楚思淼茫雲水冷，商聲清脆管弦秋。","白花浪濺頭陀寺，紅葉林籠鸚鵡洲。","總是平生未行處，醉來堪賞醒堪愁。"]', '["江邊黄鹤古时楼，勞置华筵待我游。","楚思淼茫云水冷，商声清脆管弦秋。","白花浪濺头陀寺，紅葉林籠鸚鵡洲。","總是平生未行处，醉来堪賞醒堪愁。"]', '诗', 'shi', '', NULL, '盧侍御與崔評事爲予於黃鶴樓置宴宴罷同望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b7dec59-a467-4fc6-878a-ff0a992d7d96', '舟中讀元九詩', '舟中读元九诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["把君詩卷燈前讀，詩盡燈殘天未明。","眼痛滅燈猶闇坐，逆風吹浪打船聲。"]', '["把君诗卷灯前读，诗尽灯殘天未明。","眼痛滅灯猶闇坐，逆风吹浪打船声。"]', '诗', 'shi', '', NULL, '舟中讀元九詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('867c046c-575c-428c-a034-a9419a366e7b', '舟行阻風寄李十一舍人', '舟行阻风寄李十一舍人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["扁舟厭泊煙波上，輕策閑尋浦嶼間。","虎蹋青泥稠似印，風吹白浪大於山。","且愁江郡何時到，敢望京都幾歲還。","今日料君朝退後，迎寒新酎煖開顏。"]', '["扁舟厭泊煙波上，轻策闲尋浦嶼间。","虎蹋青泥稠似印，风吹白浪大於山。","且愁江郡何时到，敢望京都幾歲還。","今日料君朝退後，迎寒新酎煖开顏。"]', '诗', 'shi', '', NULL, '舟行阻風寄李十一舍人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f89f42e3-e2f0-4867-aa33-29d72d2d8500', '雨中題衰柳', '雨中題衰柳', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["濕屈青條折，寒飄黃葉多。","不知秋雨意，更遣欲如何。"]', '["濕屈青條折，寒飄黄葉多。","不知秋雨意，更遣欲如何。"]', '诗', 'shi', '', NULL, '雨中題衰柳 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd254f96-ea36-492d-b8e6-07546d6a4d28', '題王處士郊居', '題王处士郊居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["半依雲渚半依山，愛此令人不欲還。","負郭田園八九頃，向陽茅屋兩三間。","寒松縱老風標在，野鶴雖飢飲啄閑。","一臥江村來早晚，著書盈帙鬢毛斑。"]', '["半依云渚半依山，愛此令人不欲還。","負郭田园八九頃，向陽茅屋兩三间。","寒松縱老风標在，野鹤雖飢饮啄闲。","一臥江村来早晚，著书盈帙鬢毛斑。"]', '诗', 'shi', '', NULL, '題王處士郊居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b482a2e4-0daa-4a28-80a4-f7e6e16e5745', '歲晚旅望', '歲晚旅望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝來暮去星霜換，陰慘陽舒氣序牽。","萬物秋霜能壞色，四時冬日最凋年。","煙波半露新沙地，鳥雀羣飛欲雪天。","向晚蒼蒼南北望，窮陰旅思兩無邊。"]', '["朝来暮去星霜換，陰慘陽舒氣序牽。","万物秋霜能壞色，四时冬日最凋年。","煙波半露新沙地，鸟雀羣飞欲雪天。","向晚蒼蒼南北望，窮陰旅思兩無邊。"]', '诗', 'shi', '', NULL, '歲晚旅望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14d6613e-6558-477f-9415-4d691d219dd9', '晏坐閑吟', '晏坐闲吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昔爲京洛聲華客，今作江湖潦倒翁。","意氣銷磨羣動裏，形骸變化百年中。","霜侵殘鬢無多黑，酒伴衰顏只暫紅。","願學禪門非想定，千愁萬念一時空。"]', '["昔爲京洛声华客，今作江湖潦倒翁。","意氣銷磨羣动裏，形骸变化百年中。","霜侵殘鬢無多黑，酒伴衰顏只暫紅。","願学禪门非想定，千愁万念一时空。"]', '诗', 'shi', '', NULL, '晏坐閑吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2d5b055-2f5a-4631-baa6-74eb744700c4', '題李山人', '題李山人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["廚無煙火室無妻，籬落蕭條屋舍低。","每日將何療飢渴，井華雲粉一刀圭。"]', '["廚無煙火室無妻，籬落蕭條屋舍低。","每日將何療飢渴，井华云粉一刀圭。"]', '诗', 'shi', '', NULL, '題李山人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b83af6f-0b1f-43d0-b664-67cbef1642ef', '讀莊子', '读莊子', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["去國辭家謫異方，中心自怪少憂傷。","爲尋莊子知歸處，認得無何是本鄉。"]', '["去国辞家謫異方，中心自怪少憂傷。","爲尋莊子知归处，認得無何是本乡。"]', '诗', 'shi', '', NULL, '讀莊子 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b0dce36-e643-47de-acc6-df63e99861b9', '江樓偶宴贈同座', '江楼偶宴贈同座', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南浦閑行罷，西樓小宴時。","望湖凭檻久，待月放杯遲。","江果嘗盧橘，山歌聽竹枝。","相逢且同樂，何必舊相知。"]', '["南浦闲行罷，西楼小宴时。","望湖凭檻久，待月放杯遲。","江果嘗盧橘，山歌听竹枝。","相逢且同乐，何必旧相知。"]', '诗', 'shi', '', NULL, '江樓偶宴贈同座 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a78362c6-61cc-441c-9320-bcdfffe1d0ed', '放言五首 一', '放言五首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝真暮僞何人辨，古往今來底事無。","但愛臧生能詐聖，可知甯子解佯愚。","草螢有耀終非火，荷露雖團豈是珠。","不取燔柴兼照乘，可憐光彩亦何殊。"]', '["朝真暮僞何人辨，古往今来底事無。","但愛臧生能詐聖，可知甯子解佯愚。","草螢有耀終非火，荷露雖團豈是珠。","不取燔柴兼照乘，可怜光彩亦何殊。"]', '诗', 'shi', '', NULL, '放言五首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('75b50ace-279b-494d-b782-d12543f86edb', '放言五首 二', '放言五首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["世途倚伏都無定，塵網牽纏卒未休。","禍福回還車轉轂，榮枯反覆手藏鉤。","龜靈未免刳腸患，馬失應無折足憂。","不信君看弈棊者，輸贏須待局終頭。"]', '["世途倚伏都無定，塵網牽纏卒未休。","禍福回還车轉轂，榮枯反覆手藏鉤。","龟靈未免刳腸患，马失應無折足憂。","不信君看弈棊者，輸贏須待局終头。"]', '诗', 'shi', '', NULL, '放言五首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed302103-1459-4cc9-9890-4b4bccf19aa9', '放言五首 三', '放言五首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["贈君一法決狐疑，不用鑽龜與祝蓍。","試玉要燒三日滿，辨材須待七年期。","周公恐懼流言後，王莽謙恭未篡時。","向使當初身便死，一生真僞復誰知。"]', '["贈君一法決狐疑，不用鑽龟與祝蓍。","試玉要燒三日满，辨材須待七年期。","周公恐懼流言後，王莽謙恭未篡时。","向使當初身便死，一生真僞复誰知。"]', '诗', 'shi', '', NULL, '放言五首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9edc43ff-921b-4811-8014-f37f828889aa', '放言五首 四', '放言五首 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["誰家第宅成還破，何處親賓哭復歌。","昨日屋頭堪炙手，今朝門外好張羅。","北邙未省留閑地，東海何曾有定波。","莫笑賤貧誇富貴，共成枯骨兩如何。"]', '["誰家第宅成還破，何处親賓哭复歌。","昨日屋头堪炙手，今朝门外好張羅。","北邙未省留闲地，东海何曾有定波。","莫笑賤貧誇富貴，共成枯骨兩如何。"]', '诗', 'shi', '', NULL, '放言五首 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34f06c40-fce8-496a-b80d-2a5f2fa28ec3', '放言五首 五', '放言五首 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["泰山不要欺毫末，顏子無心羨老彭。","松樹千年終是朽，槿花一日自爲榮。","何須戀世常憂死，亦莫嫌身漫厭生。","生去死來都是幻，幻人哀樂繫何情。"]', '["泰山不要欺毫末，顏子無心羨老彭。","松樹千年終是朽，槿花一日自爲榮。","何須戀世常憂死，亦莫嫌身漫厭生。","生去死来都是幻，幻人哀乐繫何情。"]', '诗', 'shi', '', NULL, '放言五首 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28016a81-cd5b-4bc8-b5dc-79f8f09d8d6d', '歲暮道情二首 一', '歲暮道情二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["壯日苦曾驚歲月，長年都不惜光陰。","爲學空門平等法，先齊老少死生心。"]', '["壯日苦曾驚歲月，长年都不惜光陰。","爲学空门平等法，先齊老少死生心。"]', '诗', 'shi', '', NULL, '歲暮道情二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec3cc36d-6ae1-4f04-9201-1eac85d15a08', '歲暮道情二首 二', '歲暮道情二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["半故青衫半白頭，雪風吹面上江樓。","禪功自見無人覺，合是愁時亦不愁。"]', '["半故青衫半白头，雪风吹面上江楼。","禪功自见無人覺，合是愁时亦不愁。"]', '诗', 'shi', '', NULL, '歲暮道情二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30bd3981-e0aa-412a-800f-47b2580b0a3f', '讀李杜詩集因題卷後', '读李杜诗集因題卷後', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["翰林江左日，員外劒南時。","不得高官職，仍逢苦亂離。","暮年逋客恨，浮世謫仙悲。","吟詠留千古，聲名動四夷。","文場供秀句，樂府待新詞。","天意君須會，人間要好詩。"]', '["翰林江左日，員外劒南时。","不得高官職，仍逢苦亂離。","暮年逋客恨，浮世謫仙悲。","吟詠留千古，声名动四夷。","文場供秀句，乐府待新词。","天意君須會，人间要好诗。"]', '诗', 'shi', '', NULL, '讀李杜詩集因題卷後 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebb2987e-120d-40f6-a187-e7f164effb7e', '強酒', '強酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["若不坐禪銷妄想，即須行醉放狂歌。","不然秋月春風夜，爭那閑思往事何。"]', '["若不坐禪銷妄想，即須行醉放狂歌。","不然秋月春风夜，爭那闲思往事何。"]', '诗', 'shi', '', NULL, '強酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbbb2a7e-6754-4d24-940c-373fcd77942d', '獨樹浦雨夜寄李六郎中', '独樹浦雨夜寄李六郎中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["忽憶兩家同里巷，何曾一處不追隨。","閑遊預算分朝日，靜語多同待漏時。","花下放狂衝黑飲，燈前起坐徹明棊。","可知風雨孤舟夜，蘆葦叢中作此詩。"]', '["忽憶兩家同里巷，何曾一处不追隨。","闲游預算分朝日，静語多同待漏时。","花下放狂衝黑饮，灯前起坐徹明棊。","可知风雨孤舟夜，蘆葦叢中作此诗。"]', '诗', 'shi', '', NULL, '獨樹浦雨夜寄李六郎中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd535dce-eec5-463a-b2df-9118a4285f39', '聽崔七妓人箏', '听崔七妓人箏', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["花臉雲鬟坐玉樓，十三弦裏一時愁。","憑君向道休彈去，白盡江州司馬頭。"]', '["花臉云鬟坐玉楼，十三弦裏一时愁。","憑君向道休彈去，白尽江州司马头。"]', '诗', 'shi', '', NULL, '聽崔七妓人箏 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42c2b2b5-f59d-46ac-8599-1c22e0b0782b', '望江州', '望江州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江迴望見雙華表，知是潯陽西郭門。","猶去孤舟三四里，水煙沙雨欲黃昏。"]', '["江迴望见雙华表，知是潯陽西郭门。","猶去孤舟三四里，水煙沙雨欲黄昏。"]', '诗', 'shi', '', NULL, '望江州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e38fdcaa-f9f2-47ca-a0dc-3c2e81c289d7', '初到江州', '初到江州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["潯陽欲到思無窮，庾亮樓南湓口東。","樹木凋疎山雨後，人家低濕水煙中。","菰蔣餧馬行無力，蘆荻編房臥有風。","遙見朱輪來出郭，相迎勞動使君公。"]', '["潯陽欲到思無窮，庾亮楼南湓口东。","樹木凋疎山雨後，人家低濕水煙中。","菰蔣餧马行無力，蘆荻編房臥有风。","遙见朱輪来出郭，相迎勞动使君公。"]', '诗', 'shi', '', NULL, '初到江州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e67b292-b84e-438f-868e-cc4f80f569ed', '醉後題李馬二妓', '醉後題李马二妓', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["行搖雲髻花鈿節，應似霓裳趁管弦。","豔動舞帬渾是火，愁凝歌黛欲生煙。","有風縱道能迴雪，無水何由忽吐蓮。","疑是兩般心未決，雨中神女月中仙。"]', '["行搖云髻花鈿節，應似霓裳趁管弦。","豔动舞帬渾是火，愁凝歌黛欲生煙。","有风縱道能迴雪，無水何由忽吐蓮。","疑是兩般心未決，雨中神女月中仙。"]', '诗', 'shi', '', NULL, '醉後題李馬二妓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0948a7ef-e377-40db-96ad-87b06375fa92', '盧侍御小妓乞詩座上留贈', '盧侍御小妓乞诗座上留贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鬱金香汗裛歌巾，山石榴花染舞帬。","好似文君還對酒，勝於神女不歸雲。","夢中那及覺時見，宋玉荆王應羨君。"]', '["鬱金香汗裛歌巾，山石榴花染舞帬。","好似文君還对酒，勝於神女不归云。","梦中那及覺时见，宋玉荆王應羨君。"]', '诗', 'shi', '', NULL, '盧侍御小妓乞詩座上留贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34d3b009-d2b6-456e-969f-8b4a0283356b', '東南行一百韻寄通州元九侍御澧州李十一舍人果州崔二十二使君開州韋大員外庾三十二補闕杜十四拾遺李二十助教員外竇七校書', '东南行一百韻寄通州元九侍御澧州李十一舍人果州崔二十二使君开州韋大員外庾三十二補闕杜十四拾遺李二十助教員外竇七校书', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南去經三楚，東來過五湖。","山頭看候館，水面問征途。","地遠窮江界，天低極海隅。","飄零同落葉，浩蕩似乘桴。","漸覺鄉原異，深知土產殊。","夷音語嘲异常，蠻態笑睢盱。","水市通闤闠，煙村混舳艫。","吏徵漁戶稅，人納火田租。","亥日饒鰕蟹，寅年足虎貙。","成人男作丱，事鬼女爲巫。","樓闇攢倡婦，隄長簇販夫。","夜船論鋪賃，春酒斷缾酤。","見果皆盧橘，聞禽悉鷓鴣。","山歌猨獨叫，野哭鳥相呼。","嶺徼雲成棧，江郊水當郛。","月移翹柱鶴，風汎颭檣烏。","鼇礙潮無信，蛟驚浪不虞。","鼉鳴江擂鼓，蜃氣海浮圖。","樹裂山魈穴，沙含水弩樞。","喘牛犂紫芋，羸馬放青菰。","繡面誰家婢，鵶頭幾歲奴。","泥中采菱芡，燒後拾樵蘇。","鼎膩愁烹鼈，盤腥厭膾鱸。","鍾儀徒戀楚，張翰浪思吳。","氣序涼還熱，光陰旦復晡。","身方逐萍梗，年欲近桑榆。","渭北田園廢，江西歲月徂。","憶歸恆慘澹，懷舊忽踟躕。","自念咸秦客，嘗爲鄒魯儒。","蘊藏經國術，輕棄度關繻。","賦力凌鸚鵡，詞鋒敵轆轤。","戰文重掉鞅，射策一彎弧。","崔杜鞭齊下，元韋轡並驅。","名聲逼揚馬，交分過蕭朱。","世務輕摩揣，周行竊覬覦。","風雲皆會合，雨露各霑濡。","共遇升平代，偏慙固陋軀。","承明連夜直，建禮拂晨趨。","美服頒王府，珍羞降御廚。","議高通白虎，諫切伏青蒲。","柏殿行陪宴，花樓走看酺。","神旗張鳥獸，天籟動笙芋。","戈劒星芒耀，魚龍電策驅。","定場排越伎，促坐進吳歈。","縹緲疑仙樂，嬋娟勝畫圖。","歌鬟低翠羽，舞汗墮紅珠。","別選閑遊伴，潛招小飲徒。","一杯愁已破，三醆氣彌麤。","輭美仇家酒，幽閑葛氏姝。","十千方得斗，二八正當壚。","論笑杓胡律，談憐鞏囁嚅。","李酣猶短竇，庾醉更蔫迂。","鞍馬呼教住，骰盤喝遣輸。","長驅波卷白，連擲采成盧。","籌幷頻逃席，觥嚴列置盂。","滿巵那可灌，頹玉不勝扶。","入視中樞草，歸乘內廐駒。","醉曾衝宰相，驕不揖金吾。","日近恩雖重，雲高勢却孤。","飜身落霄漢，失脚倒泥塗。","博望移門籍，潯陽佐郡符。","時情變寒暑，世利算錙銖。","即日辭雙闕，明朝別九衢。","播遷分郡國，次第出京都。","秦嶺馳三驛，商山上二邘。","峴陽亭寂莫，夏口路崎嶇。","大道全生棘，中丁盡執殳。","江關未撤警，淮寇尚稽誅。","林對東西寺，山分大小姑。","廬峰蓮刻削，湓浦帶縈紆。","九派吞青草，孤城覆綠蕪。","黃昏鐘寂寂，清曉角嗚嗚。","春色辭門柳，秋聲到井梧。","殘芳悲鶗鴂，暮節感茱萸。","蘂坼金英菊，花飄雪片蘆。","波紅日斜沒，沙白月平鋪。","幾見林抽筍，頻驚燕引雛。","歲華何倏忽，年少不須臾。","眇默思千古，蒼茫想八區。","孔窮緣底事，顏夭有何辜。","龍智猶經醢，龜靈未免刳。","窮通應已定，聖哲不能逾。","況我身謀拙，逢他厄運拘。","漂流隨大海，錘鍛任洪鑪。","險阻嘗之矣，栖遲命也夫。","沈冥消意氣，窮餓耗肌膚。","防瘴和殘藥，迎寒補舊襦。","書牀鳴蟋蟀，琴匣網蜘蛛。","貧室如懸磐，端憂劇守株。","時遭人指點，數被鬼揶揄。","兀兀都疑夢，昏昏半是愚。","女驚朝不起，妻怪夜長吁。","萬里拋朋侶，三年隔友于。","自然悲聚散，不是恨榮枯。","去夏微之瘧，今春席八殂。","天涯書達否，泉下哭知無。","謾寫詩盈卷，空盛酒滿壺。","只添新悵望，豈復舊歡娛。","壯志因愁減，衰容與病俱。","相逢應不識，滿頷白髭鬚。"]', '["南去經三楚，东来過五湖。","山头看候館，水面问征途。","地远窮江界，天低極海隅。","飄零同落葉，浩蕩似乘桴。","漸覺乡原異，深知土產殊。","夷音語嘲异常，蠻態笑睢盱。","水市通闤闠，煙村混舳艫。","吏徵漁戶稅，人納火田租。","亥日饒鰕蟹，寅年足虎貙。","成人男作丱，事鬼女爲巫。","楼闇攢倡婦，隄长簇販夫。","夜船論鋪賃，春酒斷缾酤。","见果皆盧橘，闻禽悉鷓鴣。","山歌猨独叫，野哭鸟相呼。","嶺徼云成棧，江郊水當郛。","月移翹柱鹤，风汎颭檣烏。","鼇礙潮無信，蛟驚浪不虞。","鼉鳴江擂鼓，蜃氣海浮圖。","樹裂山魈穴，沙含水弩樞。","喘牛犂紫芋，羸马放青菰。","繡面誰家婢，鵶头幾歲奴。","泥中采菱芡，燒後拾樵蘇。","鼎膩愁烹鼈，盤腥厭膾鱸。","鍾儀徒戀楚，張翰浪思吳。","氣序涼還熱，光陰旦复晡。","身方逐萍梗，年欲近桑榆。","渭北田园廢，江西歲月徂。","憶归恆慘澹，懷旧忽踟躕。","自念咸秦客，嘗爲鄒魯儒。","蘊藏經国術，轻棄度关繻。","賦力凌鸚鵡，词鋒敵轆轤。","戰文重掉鞅，射策一彎弧。","崔杜鞭齊下，元韋轡並驱。","名声逼揚马，交分過蕭朱。","世務轻摩揣，周行竊覬覦。","风云皆會合，雨露各霑濡。","共遇升平代，偏慙固陋軀。","承明連夜直，建禮拂晨趨。","美服頒王府，珍羞降御廚。","議高通白虎，諫切伏青蒲。","柏殿行陪宴，花楼走看酺。","神旗張鸟獸，天籟动笙芋。","戈劒星芒耀，鱼龙電策驱。","定場排越伎，促坐進吳歈。","縹緲疑仙乐，嬋娟勝畫圖。","歌鬟低翠羽，舞汗墮紅珠。","別選闲游伴，潛招小饮徒。","一杯愁已破，三醆氣彌麤。","輭美仇家酒，幽闲葛氏姝。","十千方得斗，二八正當壚。","論笑杓胡律，談怜鞏囁嚅。","李酣猶短竇，庾醉更蔫迂。","鞍马呼教住，骰盤喝遣輸。","长驱波卷白，連擲采成盧。","籌幷頻逃席，觥嚴列置盂。","满巵那可灌，頹玉不勝扶。","入視中樞草，归乘內廐駒。","醉曾衝宰相，驕不揖金吾。","日近恩雖重，云高勢却孤。","飜身落霄漢，失脚倒泥塗。","博望移门籍，潯陽佐郡符。","时情变寒暑，世利算錙銖。","即日辞雙闕，明朝別九衢。","播遷分郡国，次第出京都。","秦嶺驰三驛，商山上二邘。","峴陽亭寂莫，夏口路崎嶇。","大道全生棘，中丁尽執殳。","江关未撤警，淮寇尚稽誅。","林对东西寺，山分大小姑。","廬峰蓮刻削，湓浦带縈紆。","九派吞青草，孤城覆綠蕪。","黄昏鐘寂寂，清晓角嗚嗚。","春色辞门柳，秋声到井梧。","殘芳悲鶗鴂，暮節感茱萸。","蘂坼金英菊，花飄雪片蘆。","波紅日斜沒，沙白月平鋪。","幾见林抽筍，頻驚燕引雛。","歲华何倏忽，年少不須臾。","眇默思千古，蒼茫想八區。","孔窮緣底事，顏夭有何辜。","龙智猶經醢，龟靈未免刳。","窮通應已定，聖哲不能逾。","況我身謀拙，逢他厄運拘。","漂流隨大海，錘鍛任洪鑪。","險阻嘗之矣，栖遲命也夫。","沈冥消意氣，窮餓耗肌膚。","防瘴和殘藥，迎寒補旧襦。","书牀鳴蟋蟀，琴匣網蜘蛛。","貧室如懸磐，端憂劇守株。","时遭人指点，數被鬼揶揄。","兀兀都疑梦，昏昏半是愚。","女驚朝不起，妻怪夜长吁。","万里拋朋侶，三年隔友于。","自然悲聚散，不是恨榮枯。","去夏微之瘧，今春席八殂。","天涯书達否，泉下哭知無。","謾寫诗盈卷，空盛酒满壺。","只添新悵望，豈复旧歡娛。","壯志因愁減，衰容與病俱。","相逢應不識，满頷白髭鬚。"]', '诗', 'shi', '', NULL, '東南行一百韻寄通州元九侍御澧州李十一舍人果州崔二十二使君開州韋大員外庾三十二補闕杜十四拾遺李二十助教員外竇七校書 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('649dafe4-d336-4479-b2ce-27ab240fecda', '謫居', '謫居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["面瘦頭斑四十四，遠謫江州爲郡史。","逢時棄置從不才，未老衰羸爲何事。","火燒寒澗松爲燼，霜降春林花委地。","遭時榮悴一時間，豈是昭昭上天意。"]', '["面瘦头斑四十四，远謫江州爲郡史。","逢时棄置從不才，未老衰羸爲何事。","火燒寒澗松爲燼，霜降春林花委地。","遭时榮悴一时间，豈是昭昭上天意。"]', '诗', 'shi', '', NULL, '謫居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e24c83fd-e7b9-4f64-a389-cd65d2c62fe1', '初到江州寄翰林張李杜三學士', '初到江州寄翰林張李杜三学士', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["早攀霄漢上天衢，晚落風波委世途。","雨露施恩無厚薄，蓬蒿隨分有榮枯。","傷禽側翅驚弓箭，老婦低顏事舅姑。","碧落三仙曾識面，年深記得姓名無。"]', '["早攀霄漢上天衢，晚落风波委世途。","雨露施恩無厚薄，蓬蒿隨分有榮枯。","傷禽側翅驚弓箭，老婦低顏事舅姑。","碧落三仙曾識面，年深記得姓名無。"]', '诗', 'shi', '', NULL, '初到江州寄翰林張李杜三學士 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d284c4a-e2d7-4e1f-af06-624fbc49c46d', '庾樓曉望', '庾楼晓望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["獨憑朱檻立凌晨，山色初明水色新。","竹霧曉籠銜嶺月，蘋風暖送過江春。","子城陰處猶殘雪，衙鼓聲前未有塵。","三百年來庾樓上，曾經多少望鄉人。"]', '["独憑朱檻立凌晨，山色初明水色新。","竹霧晓籠銜嶺月，蘋风暖送過江春。","子城陰处猶殘雪，衙鼓声前未有塵。","三百年来庾楼上，曾經多少望乡人。"]', '诗', 'shi', '', NULL, '庾樓曉望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f0933ba-9551-4ad7-b16f-29fb99bd8ac7', '宿西林寺', '宿西林寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["木落天晴山翠開，愛山騎馬入山來。","心知不及柴桑令，一宿西林便却回。"]', '["木落天晴山翠开，愛山騎马入山来。","心知不及柴桑令，一宿西林便却回。"]', '诗', 'shi', '', NULL, '宿西林寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a473fe7-7454-428d-aeca-40b7687f2369', '江樓宴別', '江楼宴別', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["樓中別曲催離酌，燈下紅裙間綠袍。","縹緲楚風羅綺薄，錚鏦越調管弦高。","寒流帶月澄如鏡，夕吹和霜利似刀。","尊酒未空歡未盡，舞腰歌袖莫辭勞。"]', '["楼中別曲催離酌，灯下紅裙间綠袍。","縹緲楚风羅綺薄，錚鏦越調管弦高。","寒流带月澄如镜，夕吹和霜利似刀。","尊酒未空歡未尽，舞腰歌袖莫辞勞。"]', '诗', 'shi', '', NULL, '江樓宴別 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb590847-46a4-470e-8737-d33e5060b4f4', '題山石榴花', '題山石榴花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一叢千朵壓闌干，翦碎紅綃却作團。","風嫋舞腰香不盡，露銷妝臉淚新乾。","薔薇帶刺攀應嬾，菡萏生泥玩亦難。","爭及此花檐戶下，任人采弄盡人看。"]', '["一叢千朵壓闌干，翦碎紅綃却作團。","风嫋舞腰香不尽，露銷妝臉泪新乾。","薔薇带刺攀應嬾，菡萏生泥玩亦难。","爭及此花檐戶下，任人采弄尽人看。"]', '诗', 'shi', '', NULL, '題山石榴花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e90f1c87-f2a3-4976-a582-5a87d2f8395b', '代春贈', '代春贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["山吐晴嵐水放光，辛夷花白柳梢黃。","但知莫作江西意，風景何曾異帝鄉。"]', '["山吐晴嵐水放光，辛夷花白柳梢黄。","但知莫作江西意，风景何曾異帝乡。"]', '诗', 'shi', '', NULL, '代春贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d753d2ef-7e1e-40da-bc18-403648638967', '荅春', '荅春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["草煙低重水花明，從道風光似帝京。","其奈山猨江上叫，故鄉無此斷腸聲。"]', '["草煙低重水花明，從道风光似帝京。","其奈山猨江上叫，故乡無此斷腸声。"]', '诗', 'shi', '', NULL, '荅春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97365e6d-4417-496a-aa71-7f8eaa2d5d4b', '櫻桃花下歎白髮', '櫻桃花下歎白髮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["逐處花皆好，隨年貌自衰。","紅櫻滿眼日，白髮半頭時。","倚樹無言久，攀條欲放遲。","臨風兩堪歎，如雪復如絲。"]', '["逐处花皆好，隨年貌自衰。","紅櫻满眼日，白髮半头时。","倚樹無言久，攀條欲放遲。","臨风兩堪歎，如雪复如絲。"]', '诗', 'shi', '', NULL, '櫻桃花下歎白髮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9da82c6a-2569-45f5-a4be-8349b15f0f16', '惜落花贈崔二十四', '惜落花贈崔二十四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["漠漠紛紛不奈何，狂風急雨兩相和。","晚來悵望君知否，枝上稀疎地上多。"]', '["漠漠紛紛不奈何，狂风急雨兩相和。","晚来悵望君知否，枝上稀疎地上多。"]', '诗', 'shi', '', NULL, '惜落花贈崔二十四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b84882b-af34-43dd-9fbc-ef1b90a30d81', '移山櫻桃', '移山櫻桃', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["亦知官舍非吾宅，且斸山櫻滿院栽。","上佐近來多五考，少應四度見花開。"]', '["亦知官舍非吾宅，且斸山櫻满院栽。","上佐近来多五考，少應四度见花开。"]', '诗', 'shi', '', NULL, '移山櫻桃 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de92b5a4-8307-4276-ac61-ea696a0cc371', '官舍閑題', '官舍闲題', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["職散優閑地，身慵老大時。","送春唯有酒，銷日不過棊。","祿米麞牙稻，園蔬鴨脚葵。","飽餐仍晏起，餘暇弄龜兒。"]', '["職散優闲地，身慵老大时。","送春唯有酒，銷日不過棊。","祿米麞牙稻，园蔬鴨脚葵。","飽餐仍晏起，餘暇弄龟兒。"]', '诗', 'shi', '', NULL, '官舍閑題 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d7ba7de-93e0-4c2f-99d9-976f3a9dea12', '晚春登大雲寺南樓贈常禪師', '晚春登大云寺南楼贈常禪師', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["花盡頭新白，登樓意若何。","歲時春日少，世界苦人多。","愁醉非因酒，悲吟不是歌。","求師治此病，唯勸讀楞伽。"]', '["花尽头新白，登楼意若何。","歲时春日少，世界苦人多。","愁醉非因酒，悲吟不是歌。","求師治此病，唯勸读楞伽。"]', '诗', 'shi', '', NULL, '晚春登大雲寺南樓贈常禪師 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef511321-15f2-4807-89b4-07ce8e225543', '北樓送客歸上都', '北楼送客归上都', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憑高眺遠一悽悽，却下朱闌即解攜。","京路人歸天直北，江樓客散日平西。","長津欲度迴渡尾，殘酒重傾簇馬蹄。","不獨別君須強飲，窮愁自要醉如泥。"]', '["憑高眺远一悽悽，却下朱闌即解携。","京路人归天直北，江楼客散日平西。","长津欲度迴渡尾，殘酒重傾簇马蹄。","不独別君須強饮，窮愁自要醉如泥。"]', '诗', 'shi', '', NULL, '北樓送客歸上都 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dfb6d47-40e9-49e6-a368-5dc717e425e9', '北亭招客', '北亭招客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["疎散郡丞同野客，幽閑官舍抵山家。","春風北戶千莖竹，晚日東園一樹花。","小醆吹醅嘗冷酒，深爐敲火炙新茶。","能來近日觀棊否，太守知慵放晚衙。"]', '["疎散郡丞同野客，幽闲官舍抵山家。","春风北戶千莖竹，晚日东园一樹花。","小醆吹醅嘗冷酒，深爐敲火炙新茶。","能来近日观棊否，太守知慵放晚衙。"]', '诗', 'shi', '', NULL, '北亭招客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7315b56-63ed-443a-a7f3-ef4cfe11b84d', '宿西林寺早赴東林滿上人之會因寄崔二十二員外', '宿西林寺早赴东林满上人之會因寄崔二十二員外', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["謫辭魏闕鵷鸞隔，老入廬山麋鹿隨。","薄暮蕭條投寺宿，凌晨清淨與僧期。","雙林我起聞鐘後，隻日君趨入閣時。","鵬鷃高低分皆定，莫勞心力遠相思。"]', '["謫辞魏闕鵷鸾隔，老入廬山麋鹿隨。","薄暮蕭條投寺宿，凌晨清淨與僧期。","雙林我起闻鐘後，隻日君趨入閣时。","鵬鷃高低分皆定，莫勞心力远相思。"]', '诗', 'shi', '', NULL, '宿西林寺早赴東林滿上人之會因寄崔二十二員外 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e29eca4b-cb3d-41f1-81e5-5d3afe9ab97d', '遊寶稱寺', '游寶稱寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["竹寺初晴日，花塘欲曉春。","野猨疑弄客，山鳥似呼人。","酒嫩傾金液，茶新碾玉塵。","可憐幽靜地，堪寄老慵身。"]', '["竹寺初晴日，花塘欲晓春。","野猨疑弄客，山鸟似呼人。","酒嫩傾金液，茶新碾玉塵。","可怜幽静地，堪寄老慵身。"]', '诗', 'shi', '', NULL, '遊寶稱寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64b01261-1b4c-40d2-b981-8a8b560ff933', '早春聞提壺鳥因題鄰家', '早春闻提壺鸟因題鄰家', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["厭聽秋猨催下淚，喜聞春鳥勸提壺。","誰家紅樹先花發，何處青樓有酒酤。","進士麄豪尋靜盡，拾遺風采近都無。","欲期明日東鄰醉，變作騰騰一俗夫。"]', '["厭听秋猨催下泪，喜闻春鸟勸提壺。","誰家紅樹先花發，何处青楼有酒酤。","進士麄豪尋静尽，拾遺风采近都無。","欲期明日东鄰醉，变作腾腾一俗夫。"]', '诗', 'shi', '', NULL, '早春聞提壺鳥因題鄰家 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6521c6e2-28fc-49ff-8845-93d307ae1be3', '見紫薇花憶微之', '见紫薇花憶微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一叢暗澹將何比，淺碧籠帬襯紫巾。","除却微之見應愛，人間少有別花人。"]', '["一叢暗澹將何比，淺碧籠帬襯紫巾。","除却微之见應愛，人间少有別花人。"]', '诗', 'shi', '', NULL, '見紫薇花憶微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3814a671-10ee-40d9-95e0-d1e2d48fe54e', '薔薇花一叢獨死不知其故因有是篇', '薔薇花一叢独死不知其故因有是篇', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["柯條未嘗損，根蕟不曾移。","同類今齊茂，孤芳忽獨萎。","仍憐委地日，正是帶花時。","碎碧初凋葉，燋紅尚戀枝。","乾坤無厚薄，草木自榮衰。","欲問因何事，春風亦不知。"]', '["柯條未嘗損，根蕟不曾移。","同類今齊茂，孤芳忽独萎。","仍怜委地日，正是带花时。","碎碧初凋葉，燋紅尚戀枝。","乾坤無厚薄，草木自榮衰。","欲问因何事，春风亦不知。"]', '诗', 'shi', '', NULL, '薔薇花一叢獨死不知其故因有是篇 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89cf3ac5-7bba-4442-8f1b-645cf84ac489', '湖亭望水', '湖亭望水', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["久雨南湖漲，新晴北客過。","日沈紅有影，風定綠無波。","岸沒閭閻少，灘平船舫多。","可憐心賞處，其奈獨遊何。"]', '["久雨南湖漲，新晴北客過。","日沈紅有影，风定綠無波。","岸沒閭閻少，灘平船舫多。","可怜心賞处，其奈独游何。"]', '诗', 'shi', '', NULL, '湖亭望水 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3c8ce57-bb20-4883-bdb8-5f3b47dc24a9', '閑遊', '闲游', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["外事因慵廢，中懷與靜期。","尋泉上山遠，看筍出林遲。","白石磨樵斧，青竿理釣絲。","澄清深淺好，最愛夕陽時。"]', '["外事因慵廢，中懷與静期。","尋泉上山远，看筍出林遲。","白石磨樵斧，青竿理釣絲。","澄清深淺好，最愛夕陽时。"]', '诗', 'shi', '', NULL, '閑遊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85140ae8-d6c7-46cc-901f-fbea77c647e0', '憶微之傷仲遠', '憶微之傷仲远', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["幽獨辭羣久，漂流去國賒。","只將琴作伴，唯以酒爲家。","感逝因看水，傷離爲見花。","李三埋地底，元九謫天涯。","舉眼青雲遠，回頭白日斜。","可能勝賈誼，猶自滯長沙。"]', '["幽独辞羣久，漂流去国賒。","只將琴作伴，唯以酒爲家。","感逝因看水，傷離爲见花。","李三埋地底，元九謫天涯。","舉眼青云远，回头白日斜。","可能勝賈誼，猶自滯长沙。"]', '诗', 'shi', '', NULL, '憶微之傷仲遠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c324846f-0a23-402a-b4d6-a20b9e9dbaf7', '過鄭處士', '過鄭处士', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["聞道移居村塢間，竹林多處獨開關。","故來不是求他事，暫借南亭一望山。"]', '["闻道移居村塢间，竹林多处独开关。","故来不是求他事，暫借南亭一望山。"]', '诗', 'shi', '', NULL, '過鄭處士 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96acf8fa-be53-4cb8-988c-2f7924f700bd', '霖雨苦多江湖暴漲塊然獨望因題北亭', '霖雨苦多江湖暴漲塊然独望因題北亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自作潯陽客，無如苦雨何。","陰昏晴日少，閑悶睡時多。","湖闊將天合，雲低與水和。","籬根舟子語，巷口釣人歌。","霧島沈黃氣，風帆蹙白波。","門前車馬道，一宿變江河。"]', '["自作潯陽客，無如苦雨何。","陰昏晴日少，闲悶睡时多。","湖闊將天合，云低與水和。","籬根舟子語，巷口釣人歌。","霧島沈黄氣，风帆蹙白波。","门前车马道，一宿变江河。"]', '诗', 'shi', '', NULL, '霖雨苦多江湖暴漲塊然獨望因題北亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('822813b7-e1a1-42f1-9da0-366edd6779e3', '春末夏初閑遊江郭二首 一', '春末夏初闲游江郭二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閑出乘輕屐，徐行蹋輭沙。","觀魚傍湓浦，看竹入楊家。","林迸穿籬筍，藤飄落水花。","雨埋釣舟小，風颺酒旗斜。","嫩剝青菱角，濃煎白茗芽。","淹留不知夕，城樹欲栖鴉。"]', '["闲出乘轻屐，徐行蹋輭沙。","观鱼傍湓浦，看竹入楊家。","林迸穿籬筍，藤飄落水花。","雨埋釣舟小，风颺酒旗斜。","嫩剝青菱角，濃煎白茗芽。","淹留不知夕，城樹欲栖鴉。"]', '诗', 'shi', '', NULL, '春末夏初閑遊江郭二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82dab979-e2bd-43cd-b739-b487a16af571', '春末夏初閑遊江郭二首 二', '春末夏初闲游江郭二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["柳影繁初合，鶯聲澀漸稀。","早梅迎夏結，殘絮送春飛。","西日韶光盡，南風暑氣微。","展張新小簟，熨帖舊生衣。","綠蟻杯香嫩，紅絲膾縷肥。","故園無此味，何必苦思歸。"]', '["柳影繁初合，鶯声澀漸稀。","早梅迎夏結，殘絮送春飞。","西日韶光尽，南风暑氣微。","展張新小簟，熨帖旧生衣。","綠蟻杯香嫩，紅絲膾縷肥。","故园無此味，何必苦思归。"]', '诗', 'shi', '', NULL, '春末夏初閑遊江郭二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8953d095-bef2-4238-ae11-19ea6b1c51a9', '紅藤杖', '紅藤杖', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南詔紅藤杖，西江白首人。","時時攜步月，處處把尋春。","勁健孤莖直，疎圓六節勻。","火山生處遠，瀘水洗來新。","粗細纔盈手，高低僅過身。","天邊望鄉客，何日拄歸秦。"]', '["南詔紅藤杖，西江白首人。","时时携步月，处处把尋春。","勁健孤莖直，疎圓六節勻。","火山生处远，瀘水洗来新。","粗細纔盈手，高低僅過身。","天邊望乡客，何日拄归秦。"]', '诗', 'shi', '', NULL, '紅藤杖 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c66e55dc-4c6b-48a9-b52c-3acab7618e34', '風雨中尋李十一因題船上', '风雨中尋李十一因題船上', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["匹馬來郊外，扁舟在水濱。","可憐衝雨客，來訪阻風人。","小榼酤清醑，行廚煮白鱗。","停杯看柳色，各憶故園春。"]', '["匹马来郊外，扁舟在水濱。","可怜衝雨客，来訪阻风人。","小榼酤清醑，行廚煮白鱗。","停杯看柳色，各憶故园春。"]', '诗', 'shi', '', NULL, '風雨中尋李十一因題船上 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5011d7b2-a92c-4901-a71a-2bb58e33a369', '題廬山山下湯泉', '題廬山山下湯泉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一眼湯泉流向東，浸泥澆草煖無功。","驪山溫水因何事，流入金鋪玉甃中。"]', '["一眼湯泉流向东，浸泥澆草煖無功。","驪山溫水因何事，流入金鋪玉甃中。"]', '诗', 'shi', '', NULL, '題廬山山下湯泉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b956b3c-61ae-4a70-8e58-e2af55cc0509', '寄蘄州簟與元九因題六韻', '寄蘄州簟與元九因題六韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["笛竹出蘄春，霜刀劈翠筠。","織成雙鎖簟，寄與獨眠人。","卷作筒中信，舒爲席上珍。","滑如鋪薤葉，冷似臥龍鱗。","清潤宜乘露，鮮華不受塵。","通州炎瘴地，此物最關身。"]', '["笛竹出蘄春，霜刀劈翠筠。","织成雙鎖簟，寄與独眠人。","卷作筒中信，舒爲席上珍。","滑如鋪薤葉，冷似臥龙鱗。","清潤宜乘露，鲜华不受塵。","通州炎瘴地，此物最关身。"]', '诗', 'shi', '', NULL, '寄蘄州簟與元九因題六韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e61250b0-0ed9-4eac-ae61-b9fc8a0f7684', '秋熱', '秋熱', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["西江風候接南威，暑氣常多秋氣微。","猶道江州最涼冷，至今九月著生衣。"]', '["西江风候接南威，暑氣常多秋氣微。","猶道江州最涼冷，至今九月著生衣。"]', '诗', 'shi', '', NULL, '秋熱 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('985bd20d-1941-42d2-bf84-5303635f7a75', '題元八谿居', '題元八谿居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["溪嵐漠漠樹重重，水檻山窗次第逢。","晚葉尚開紅躑躅，秋芳初結白芙蓉。","聲來枕上千年鶴，影落杯中五老峰。","更媿殷勤留客意，魚鮮飯細酒香濃。"]', '["溪嵐漠漠樹重重，水檻山窗次第逢。","晚葉尚开紅躑躅，秋芳初結白芙蓉。","声来枕上千年鹤，影落杯中五老峰。","更媿殷勤留客意，鱼鲜飯細酒香濃。"]', '诗', 'shi', '', NULL, '題元八谿居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bd3f25c-d4fb-4f43-9555-e942d29e8261', '晚出西郊', '晚出西郊', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["散吏閑如客，貧州冷似村。","早涼湖北岸，殘照郭西門。","嬾鑷從鬚白，休治任眼昏。","老來何所用，少興不多言。"]', '["散吏闲如客，貧州冷似村。","早涼湖北岸，殘照郭西门。","嬾鑷從鬚白，休治任眼昏。","老来何所用，少兴不多言。"]', '诗', 'shi', '', NULL, '晚出西郊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3759322-e75e-443c-a2f9-0a15daa8b91a', '階下蓮', '階下蓮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["葉展影飜當砌月，花開香散入簾風。","不如種在天池上，猶勝生於野水中。"]', '["葉展影飜當砌月，花开香散入簾风。","不如種在天池上，猶勝生於野水中。"]', '诗', 'shi', '', NULL, '階下蓮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9804a6d5-93a6-4454-86db-a1b1969c13c5', '端居詠懷', '端居詠懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["賈生俟罪心相似，張翰思歸事不如。","斜日早知驚鵩鳥，秋風悔不憶鱸魚。","胷襟曾貯匡時策，懷袖猶殘諫獵書。","從此萬緣都擺落，欲攜妻子買山居。"]', '["賈生俟罪心相似，張翰思归事不如。","斜日早知驚鵩鸟，秋风悔不憶鱸鱼。","胷襟曾貯匡时策，懷袖猶殘諫獵书。","從此万緣都擺落，欲携妻子買山居。"]', '诗', 'shi', '', NULL, '端居詠懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf4bac13-4f98-45fc-b2d5-f433b3fa698e', '夜宿江浦聞元八改官因寄此什', '夜宿江浦闻元八改官因寄此什', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["君遊丹陛已三遷，我汎滄浪欲二年。","劒珮曉趨雙鳳闕，煙波夜宿一漁船。","交親盡在青雲上，鄉國遙拋白日邊。","若報生涯應笑殺，結茅栽芋種畬田。"]', '["君游丹陛已三遷，我汎滄浪欲二年。","劒珮晓趨雙鳳闕，煙波夜宿一漁船。","交親尽在青云上，乡国遙拋白日邊。","若報生涯應笑殺，結茅栽芋種畬田。"]', '诗', 'shi', '', NULL, '夜宿江浦聞元八改官因寄此什 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d96c1ac-e222-4afa-aefa-34b42da5895c', '百花亭', '百花亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朱檻在空虛，涼風八月初。","山形如峴首，江色似桐廬。","佛寺乘船入，人家枕水居。","高亭仍有月，今夜宿何如。"]', '["朱檻在空虛，涼风八月初。","山形如峴首，江色似桐廬。","佛寺乘船入，人家枕水居。","高亭仍有月，今夜宿何如。"]', '诗', 'shi', '', NULL, '百花亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2110d36-8655-441b-83fb-63a32e6f0fdc', '江樓早秋', '江楼早秋', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南國雖多熱，秋來亦不遲。","湖光朝霽後，竹氣晚涼時。","樓閣宜佳客，江山入好詩。","清風水蘋葉，白露木蘭枝。","欲作雲泉計，須營伏臘資。","匡廬一步地，官滿更何之。"]', '["南国雖多熱，秋来亦不遲。","湖光朝霽後，竹氣晚涼时。","楼閣宜佳客，江山入好诗。","清风水蘋葉，白露木蘭枝。","欲作云泉計，須營伏臘資。","匡廬一步地，官满更何之。"]', '诗', 'shi', '', NULL, '江樓早秋 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b02709aa-dd6b-4764-b600-67b1d97e2a58', '送客之湖南', '送客之湖南', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["年年漸見南方物，事事堪傷北客情。","山鬼趫跳唯一足，峽猿哀怨過三聲。","帆開青草湖中去，衣濕黃梅雨裏行。","別後雙魚難定寄，近來潮不到湓城。"]', '["年年漸见南方物，事事堪傷北客情。","山鬼趫跳唯一足，峽猿哀怨過三声。","帆开青草湖中去，衣濕黄梅雨裏行。","別後雙鱼难定寄，近来潮不到湓城。"]', '诗', 'shi', '', NULL, '送客之湖南 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a621ca83-2def-47f5-807c-713d40ac2b0a', '百花亭晚望夜歸', '百花亭晚望夜归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["百花亭上晚裴回，雲影陰晴掩復開。","日色悠揚暎山盡，雨聲蕭颯渡江來。","鬢毛遇病雙如雪，心緒逢秋一似灰。","向夜欲歸愁未了，滿湖明月小船迴。"]', '["百花亭上晚裴回，云影陰晴掩复开。","日色悠揚暎山尽，雨声蕭颯渡江来。","鬢毛遇病雙如雪，心緒逢秋一似灰。","向夜欲归愁未了，满湖明月小船迴。"]', '诗', 'shi', '', NULL, '百花亭晚望夜歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('add5658a-0e8c-4ac2-b8b6-d86467bac247', '西樓', '西楼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小郡大江邊，危樓夕照前。","青蕪卑濕地，白露泬寥天。","鄉國此時阻，家書何處傳？","仍聞陳蔡戍，轉戰已三年。"]', '["小郡大江邊，危楼夕照前。","青蕪卑濕地，白露泬寥天。","乡国此时阻，家书何处傳？","仍闻陳蔡戍，轉戰已三年。"]', '诗', 'shi', '', NULL, '西樓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4337c15b-4c7e-4b6e-8a84-0e0c1806f484', '尋李道士山居兼呈元明府', '尋李道士山居兼呈元明府', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["盡日行還歇，遲遲獨上山。","攀藤老筋力，照水病容顏。","陶巷招居住，茅家許往還。","飽諳榮辱事，無意戀人間。"]', '["尽日行還歇，遲遲独上山。","攀藤老筋力，照水病容顏。","陶巷招居住，茅家許往還。","飽諳榮辱事，無意戀人间。"]', '诗', 'shi', '', NULL, '尋李道士山居兼呈元明府 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4550960-ded7-4ff2-b699-d62fccfe5357', '四十五', '四十五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["行年四十五，兩鬢半蒼蒼。","清瘦詩成癖，粗豪酒放狂。","老來尤委命，安處即爲鄉。","或擬廬山下，來春結草堂。"]', '["行年四十五，兩鬢半蒼蒼。","清瘦诗成癖，粗豪酒放狂。","老来尤委命，安处即爲乡。","或擬廬山下，来春結草堂。"]', '诗', 'shi', '', NULL, '四十五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d748ec83-83cd-4ff8-8af6-bf6b5f22ca09', '寄李相公崔侍郎錢舍人', '寄李相公崔侍郎錢舍人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曾陪鶴馭兩三仙，親侍龍輿四五年。","天上歡華春有限，世間漂泊海無邊。","榮枯事過都成夢，憂喜心忘便是禪。","官滿更歸何處去，香爐峰在宅門前。"]', '["曾陪鹤馭兩三仙，親侍龙輿四五年。","天上歡华春有限，世间漂泊海無邊。","榮枯事過都成梦，憂喜心忘便是禪。","官满更归何处去，香爐峰在宅门前。"]', '诗', 'shi', '', NULL, '寄李相公崔侍郎錢舍人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97ca629b-5875-4f77-b7cf-bcb0bc45dd91', '廳前桂', '廳前桂', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天台嶺上凌霜樹，司馬廳前委地叢。","一種不生明月裏，山中猶校勝塵中。"]', '["天台嶺上凌霜樹，司马廳前委地叢。","一種不生明月裏，山中猶校勝塵中。"]', '诗', 'shi', '', NULL, '廳前桂 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('761a0ac6-307d-421f-a18a-66997697b098', '尋王道士藥堂因有題贈', '尋王道士藥堂因有題贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["行行覓路緣松嶠，步步尋花到杏壇。","白石先生小有洞，黃芽姹女大還丹。","常悲東郭千家冢，欲乞西山五色丸。","但恐長生須有籍，仙臺試爲檢名看。"]', '["行行覓路緣松嶠，步步尋花到杏壇。","白石先生小有洞，黄芽姹女大還丹。","常悲东郭千家冢，欲乞西山五色丸。","但恐长生須有籍，仙台試爲檢名看。"]', '诗', 'shi', '', NULL, '尋王道士藥堂因有題贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('401dd560-9b66-4829-93db-1442d928b863', '秋晚', '秋晚', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["籬菊花稀砌桐落，樹陰離離日色薄。","單幕疎簾貧寂莫，涼風冷露秋蕭索。","光陰流轉忽已晚，顏色凋殘不如昨。","萊妻臥病月明時，不擣寒衣空擣藥。"]', '["籬菊花稀砌桐落，樹陰離離日色薄。","單幕疎簾貧寂莫，涼风冷露秋蕭索。","光陰流轉忽已晚，顏色凋殘不如昨。","萊妻臥病月明时，不擣寒衣空擣藥。"]', '诗', 'shi', '', NULL, '秋晚 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bc1faaf-76a2-4868-8938-ea3423f1a2b7', '南浦歲暮對酒送王十五歸京', '南浦歲暮对酒送王十五归京', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["臘後冰生覆湓水，夜來雲闇失廬山。","風飄細雪落如米，索索蕭蕭蘆葦間。","此地二年留我住，今朝一酌送君還。","相看漸老無過醉，聚散窮通總是閑。"]', '["臘後冰生覆湓水，夜来云闇失廬山。","风飄細雪落如米，索索蕭蕭蘆葦间。","此地二年留我住，今朝一酌送君還。","相看漸老無過醉，聚散窮通總是闲。"]', '诗', 'shi', '', NULL, '南浦歲暮對酒送王十五歸京 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93922b94-1754-4664-8857-5e6f0485996a', '除夜', '除夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["薄晚支頤坐，中宵枕臂眠。","一從身去國，再見日周天。","老度江南歲，春拋渭北田。","潯陽來早晚，明日是三年。"]', '["薄晚支頤坐，中宵枕臂眠。","一從身去国，再见日周天。","老度江南歲，春拋渭北田。","潯陽来早晚，明日是三年。"]', '诗', 'shi', '', NULL, '除夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee496564-ffbe-4860-b970-8759ce180734', '聞李十一出牧澧州崔二十二出牧果州因寄絕句', '闻李十一出牧澧州崔二十二出牧果州因寄絕句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["平生相見即眉開，靜念無如李與崔。","各是天涯爲刺史，緣何不覓九江來。"]', '["平生相见即眉开，静念無如李與崔。","各是天涯爲刺史，緣何不覓九江来。"]', '诗', 'shi', '', NULL, '聞李十一出牧澧州崔二十二出牧果州因寄絕句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77178613-d04c-4d95-8bb3-434254cf03a3', '元和十三年淮寇未平詔停歲仗憤然有感率爾成章', '元和十三年淮寇未平詔停歲仗憤然有感率爾成章', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["聞停歲仗軫皇情，應爲淮西寇未平。","不分氣從歌裏發，無明心向酒中生。","愚計忽思飛短檄，狂心便欲請長纓。","從來妄動多如此，自笑何曾得事成。"]', '["闻停歲仗軫皇情，應爲淮西寇未平。","不分氣從歌裏發，無明心向酒中生。","愚計忽思飞短檄，狂心便欲請长纓。","從来妄动多如此，自笑何曾得事成。"]', '诗', 'shi', '', NULL, '元和十三年淮寇未平詔停歲仗憤然有感率爾成章 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd3cff71-eb8f-496c-bc0e-5d58fe074c51', '庾樓新歲', '庾楼新歲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["歲時銷旅貌，風景觸鄉愁。","牢落江湖意，新年上庾樓。"]', '["歲时銷旅貌，风景觸乡愁。","牢落江湖意，新年上庾楼。"]', '诗', 'shi', '', NULL, '庾樓新歲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfd94a1e-4ae4-4b98-8a08-bc0c1058dcb5', '上香爐峰', '上香爐峰', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["倚石攀籮歇病身，青笻竹仗白紗巾。","他時畫出廬山障，便是香爐峰上人。"]', '["倚石攀籮歇病身，青笻竹仗白紗巾。","他时畫出廬山障，便是香爐峰上人。"]', '诗', 'shi', '', NULL, '上香爐峰 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d1fb2ec-f105-4bfa-a2e2-8aa70642b24a', '憶微之', '憶微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["與君何日出屯蒙，魚戀江湖鳥厭籠。","分手各拋滄海畔，折腰俱老綠衫中。","三年隔闊音塵斷，兩地飄零氣味同。","又被新年勸相憶，柳條黃輭欲春風。"]', '["與君何日出屯蒙，鱼戀江湖鸟厭籠。","分手各拋滄海畔，折腰俱老綠衫中。","三年隔闊音塵斷，兩地飄零氣味同。","又被新年勸相憶，柳條黄輭欲春风。"]', '诗', 'shi', '', NULL, '憶微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80e0ff2c-8ed6-493f-9cd5-361663872092', '雨夜贈元十八', '雨夜贈元十八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["卑濕沙頭宅，連陰雨夜天。","共聽檐溜滴，心事兩悠然。","把酒循環飲，移牀曲尺眠。","莫言非故舊，相識已三年。"]', '["卑濕沙头宅，連陰雨夜天。","共听檐溜滴，心事兩悠然。","把酒循环饮，移牀曲尺眠。","莫言非故旧，相識已三年。"]', '诗', 'shi', '', NULL, '雨夜贈元十八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9616ecd-6e76-4055-a4d0-cf043c07240f', '寒食江畔', '寒食江畔', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["草香沙暖水雲晴，風景令人憶帝京。","還似往年春氣味，不宜今日病心情。","聞鶯樹下沈吟立，信馬江頭取次行。","忽見紫桐花悵望，下邽明日是清明。"]', '["草香沙暖水云晴，风景令人憶帝京。","還似往年春氣味，不宜今日病心情。","闻鶯樹下沈吟立，信马江头取次行。","忽见紫桐花悵望，下邽明日是清明。"]', '诗', 'shi', '', NULL, '寒食江畔 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9c46473-4b70-4183-8b3e-2780334ff0f6', '三月三日登庾樓寄庾三十二', '三月三日登庾楼寄庾三十二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三日歡遊辭曲水，二年愁臥在長沙。","每登高處長相憶，何況茲樓屬庾家。"]', '["三日歡游辞曲水，二年愁臥在长沙。","每登高处长相憶，何況茲楼屬庾家。"]', '诗', 'shi', '', NULL, '三月三日登庾樓寄庾三十二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a326ca3e-4c74-4a79-9d10-624d0d4801dc', '聞李六景儉自河東令授唐鄧行軍司馬以詩賀之', '闻李六景儉自河东令授唐鄧行軍司马以诗賀之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["誰能淮上靜風波，聞道河東應此科。","不獨文詞供奏記，定將談笑解兵戈。","泥埋劒戟終難久，水借蛟龍可在多。","四十著緋軍司馬，男兒官職未蹉跎。"]', '["誰能淮上静风波，闻道河东應此科。","不独文词供奏記，定將談笑解兵戈。","泥埋劒戟終难久，水借蛟龙可在多。","四十著緋軍司马，男兒官職未蹉跎。"]', '诗', 'shi', '', NULL, '聞李六景儉自河東令授唐鄧行軍司馬以詩賀之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a29e44cd-00b6-47f3-9257-4318fff30637', '石榴樹', '石榴樹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["可憐顏色好陰涼，葉翦紅牋花撲霜。","繖蓋低垂金翡翠，熏籠亂搭繡衣裳。","春芽細炷千燈燄，夏蘂濃焚百[和]香。","見說上林無此樹，只教桃柳占年芳。"]', '["可怜顏色好陰涼，葉翦紅牋花撲霜。","繖蓋低垂金翡翠，熏籠亂搭繡衣裳。","春芽細炷千灯燄，夏蘂濃焚百[和]香。","见说上林無此樹，只教桃柳占年芳。"]', '诗', 'shi', '', NULL, '石榴樹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5f726ac-2edd-44c1-bebf-1cc8476fad4c', '大林寺桃花', '大林寺桃花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人間四月芳菲盡，山寺桃花始盛開。","長恨春歸無覓處，不知轉入此中來。"]', '["人间四月芳菲尽，山寺桃花始盛开。","长恨春归無覓处，不知轉入此中来。"]', '诗', 'shi', '', NULL, '大林寺桃花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4439ea65-172e-424a-9bb3-68b0959fae15', '詠懷', '詠懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自從委順任浮沈，漸覺年多功用深。","面上減除憂喜色，胷中消盡是非心。","妻兒不問唯耽酒，冠蓋皆慵只抱琴。","長笑靈均不知命，江蘺叢畔苦悲吟。"]', '["自從委順任浮沈，漸覺年多功用深。","面上減除憂喜色，胷中消尽是非心。","妻兒不问唯耽酒，冠蓋皆慵只抱琴。","长笑靈均不知命，江蘺叢畔苦悲吟。"]', '诗', 'shi', '', NULL, '詠懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5e2484e-2a17-4351-88db-e9684d3573d1', '早發楚城驛', '早發楚城驛', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雨過塵埃滅，沿江道徑平。","月乘殘夜出，人趁早涼行。","寂歷閑吟動，冥濛暗思生。","荷塘飜露氣，稻壟瀉泉聲。","宿犬聞鈴起，栖禽見火驚。","曨曨煙樹色，十里始天明。"]', '["雨過塵埃滅，沿江道徑平。","月乘殘夜出，人趁早涼行。","寂歷闲吟动，冥濛暗思生。","荷塘飜露氣，稻壟瀉泉声。","宿犬闻鈴起，栖禽见火驚。","曨曨煙樹色，十里始天明。"]', '诗', 'shi', '', NULL, '早發楚城驛 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6b6b4ec-58de-4278-8c78-417834559331', '箬峴東池', '箬峴东池', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["箬峴亭東有小池，早荷新荇綠參差。","中宵把火行人發，驚起雙栖白鷺鷥。"]', '["箬峴亭东有小池，早荷新荇綠參差。","中宵把火行人發，驚起雙栖白鷺鷥。"]', '诗', 'shi', '', NULL, '箬峴東池 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0195efd1-4268-4383-9e06-67f45793a6ad', '建昌江', '建昌江', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["建昌江水縣門前，立馬教人喚渡船。","忽似往年歸蔡渡，草風沙雨渭河邊。"]', '["建昌江水縣门前，立马教人喚渡船。","忽似往年归蔡渡，草风沙雨渭河邊。"]', '诗', 'shi', '', NULL, '建昌江 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76ccf07b-b4d6-410b-bcd2-f8b6cb98e59e', '哭從弟', '哭從弟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["傷心一尉便終身，叔母年高新婦貧。","一片綠衫消不得，腰金拖紫是何人。"]', '["傷心一尉便終身，叔母年高新婦貧。","一片綠衫消不得，腰金拖紫是何人。"]', '诗', 'shi', '', NULL, '哭從弟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f7279df-ad05-428c-be89-b8824385a416', '香爐峰下新卜山居草堂初成偶題東壁', '香爐峰下新卜山居草堂初成偶題东壁', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["五架三間新草堂，石階桂柱竹編牆。","南檐納日冬天暖，北戶迎風夏月涼。","灑砌飛泉纔有點，拂窗斜竹不成行。","來春更葺東廂屋，紙閣蘆簾著孟光。"]', '["五架三间新草堂，石階桂柱竹編牆。","南檐納日冬天暖，北戶迎风夏月涼。","灑砌飞泉纔有点，拂窗斜竹不成行。","来春更葺东廂屋，紙閣蘆簾著孟光。"]', '诗', 'shi', '', NULL, '香爐峰下新卜山居草堂初成偶題東壁 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3883ce5-26ed-4db9-a263-2dddf4de4ba8', '重題 一', '重題 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["喜入山林初息影，厭趨朝市久勞生。","早年薄有煙霞志，歲晚深諳世俗情。","已許虎溪雲裏臥，不爭龍尾道前行。","從茲耳界應清淨，免見啾啾毀譽聲。"]', '["喜入山林初息影，厭趨朝市久勞生。","早年薄有煙霞志，歲晚深諳世俗情。","已許虎溪云裏臥，不爭龙尾道前行。","從茲耳界應清淨，免见啾啾毀譽声。"]', '诗', 'shi', '', NULL, '重題 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9d19db4-eb31-4e16-aa78-a3ebf6b89aa5', '重題 二', '重題 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["長松樹下小溪頭，班鹿胎巾白布裘。","藥圃茶園爲產業，野麋林鶴是交遊。","雲生澗戶衣裳潤，嵐隱山廚火燭幽。","最愛一泉新引得，清泠屈曲繞階流。"]', '["长松樹下小溪头，班鹿胎巾白布裘。","藥圃茶园爲產業，野麋林鹤是交游。","云生澗戶衣裳潤，嵐隐山廚火燭幽。","最愛一泉新引得，清泠屈曲繞階流。"]', '诗', 'shi', '', NULL, '重題 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15c0f584-e3f4-413e-a6c2-5bb40a2b737f', '重題 三', '重題 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日高睡足猶慵起，小閣重衾不怕寒。","遺愛寺鐘欹枕聽，香爐峰雪撥簾看。","匡廬便是逃名地，司馬仍爲送老官。","心泰身寧是歸處，故鄉何獨在長安。"]', '["日高睡足猶慵起，小閣重衾不怕寒。","遺愛寺鐘欹枕听，香爐峰雪撥簾看。","匡廬便是逃名地，司马仍爲送老官。","心泰身寧是归处，故乡何独在长安。"]', '诗', 'shi', '', NULL, '重題 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbcd667c-130c-4d4e-9a13-ab045b73bad2', '重題 四', '重題 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["宦途自此心長別，世事從今口不言。","豈止形骸同土木，兼將壽夭任乾坤。","胷中壯氣猶須遣，身外浮榮何足論。","還有一條遺恨事，高家門館未酬恩。"]', '["宦途自此心长別，世事從今口不言。","豈止形骸同土木，兼將壽夭任乾坤。","胷中壯氣猶須遣，身外浮榮何足論。","還有一條遺恨事，高家门館未酬恩。"]', '诗', 'shi', '', NULL, '重題 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('470a3c60-1f44-4fed-8cc0-3e990c21c080', '山中問月', '山中问月', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["爲問長安月，誰教不相離。","昔隨飛蓋處，今照入山時。","借助秋懷曠，留連夜臥遲。","如歸舊鄉國，似對好親知。","松下行爲伴，谿頭坐有期。","千巖將萬壑，無處不相隨。"]', '["爲问长安月，誰教不相離。","昔隨飞蓋处，今照入山时。","借助秋懷曠，留連夜臥遲。","如归旧乡国，似对好親知。","松下行爲伴，谿头坐有期。","千巖將万壑，無处不相隨。"]', '诗', 'shi', '', NULL, '山中問月 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6b08353-3068-494d-a351-933db9ae3a7b', '正月十五日夜東林寺學禪偶懷藍田楊主簿因呈智禪師', '正月十五日夜东林寺学禪偶懷藍田楊主簿因呈智禪師', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["新年三五東林夕，星漢迢迢鐘梵遲。","花縣當君行樂夜，松房是我坐禪時。","忽看月滿還相憶，始歎春來自不知。","不覺定中微念起，明朝更問鴈門師。"]', '["新年三五东林夕，星漢迢迢鐘梵遲。","花縣當君行乐夜，松房是我坐禪时。","忽看月满還相憶，始歎春来自不知。","不覺定中微念起，明朝更问鴈门師。"]', '诗', 'shi', '', NULL, '正月十五日夜東林寺學禪偶懷藍田楊主簿因呈智禪師 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3c3ba91-4636-4863-b8a9-de9910bada57', '臨水坐', '臨水坐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昔爲東掖垣中客，今作西方社內人。","手把楊枝臨水坐，閑思往事似前身。"]', '["昔爲东掖垣中客，今作西方社內人。","手把楊枝臨水坐，闲思往事似前身。"]', '诗', 'shi', '', NULL, '臨水坐 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3045218-2fe6-49ec-a26a-bfce9dc3a26b', '山居', '山居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["山齋方獨往，塵事莫相仍。","藍轝辭鞍馬，緇徒換友朋。","朝餐唯藥菜，夜伴只紗燈。","除却青衫在，其餘便是僧。"]', '["山斋方独往，塵事莫相仍。","藍轝辞鞍马，緇徒換友朋。","朝餐唯藥菜，夜伴只紗灯。","除却青衫在，其餘便是僧。"]', '诗', 'shi', '', NULL, '山居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f2706a9-bfe1-4618-ab0d-c50b32c10350', '遺愛寺', '遺愛寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["弄日臨谿坐，尋花繞寺行。","時時聞鳥語，處處是泉聲。"]', '["弄日臨谿坐，尋花繞寺行。","时时闻鸟語，处处是泉声。"]', '诗', 'shi', '', NULL, '遺愛寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbbfdddd-99af-47b4-bf51-3dd025bc3797', '山中與元九書因題書後', '山中與元九书因題书後', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憶昔封書與君夜，金鑾殿後欲明天。","今夜封書在何處，廬山庵裏晚燈前。","籠鳥檻猿俱未死，人間相見是何年。"]', '["憶昔封书與君夜，金鑾殿後欲明天。","今夜封书在何处，廬山庵裏晚灯前。","籠鸟檻猿俱未死，人间相见是何年。"]', '诗', 'shi', '', NULL, '山中與元九書因題書後 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5629f4fe-8e88-4d38-8e2f-bd6770e9ee96', '黃石巖下作', '黄石巖下作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["久別鵷鸞侶，深隨鳥獸羣。","教他遠親故，何處覓知聞？","昔日青雲意，今移向白雲。"]', '["久別鵷鸾侶，深隨鸟獸羣。","教他远親故，何处覓知闻？","昔日青云意，今移向白云。"]', '诗', 'shi', '', NULL, '黃石巖下作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7515bda6-96de-416e-b3ea-691e9648df25', '戲贈李十三判官', '戲贈李十三判官', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["垂鞭相送醉醺醺，遙見廬山指似君。","想君初覺從軍樂，未愛香爐峰上雲。"]', '["垂鞭相送醉醺醺，遙见廬山指似君。","想君初覺從軍乐，未愛香爐峰上云。"]', '诗', 'shi', '', NULL, '戲贈李十三判官 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('147e96f5-0fc7-4b4d-ad78-3c36fbc88cbc', '醉中戲贈鄭使君', '醉中戲贈鄭使君', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["密座移紅毯，酡顏照淥杯。","雙娥留且住，五馬任先迴。","醉耳歌催醒，愁眉笑引開。","平生少年興，臨老暫重來。"]', '["密座移紅毯，酡顏照淥杯。","雙娥留且住，五马任先迴。","醉耳歌催醒，愁眉笑引开。","平生少年兴，臨老暫重来。"]', '诗', 'shi', '', NULL, '醉中戲贈鄭使君 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('524f548b-de66-4b9d-95cb-34f50c1d3135', '江亭夕望', '江亭夕望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憑高望遠思悠哉，晚上江亭夜未迴。","日欲沒時紅浪沸，月初生處白煙開。","辭枝雪蘂將春去，滿鑷霜毛送老來。","爭敢三年作歸計，心知不及賈生才。"]', '["憑高望远思悠哉，晚上江亭夜未迴。","日欲沒时紅浪沸，月初生处白煙开。","辞枝雪蘂將春去，满鑷霜毛送老来。","爭敢三年作归計，心知不及賈生才。"]', '诗', 'shi', '', NULL, '江亭夕望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77e25ac8-1e34-4634-bc11-e5e9f75fb67d', '酬元員外三月三十日慈恩寺相憶見寄', '酬元員外三月三十日慈恩寺相憶见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["悵望慈恩三月盡，紫桐花落鳥關關。","誠知曲水春相憶，其奈長沙老未還。","赤嶺猨聲催白首，黃茅瘴色換朱顏。","誰言南國無霜雪，盡在愁人鬢髮間。"]', '["悵望慈恩三月尽，紫桐花落鸟关关。","誠知曲水春相憶，其奈长沙老未還。","赤嶺猨声催白首，黄茅瘴色換朱顏。","誰言南国無霜雪，尽在愁人鬢髮间。"]', '诗', 'shi', '', NULL, '酬元員外三月三十日慈恩寺相憶見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd8a7069-64a9-4ada-855d-b083598328ae', '偶然二首 一', '偶然二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["楚懷邪亂靈均直，放棄合宜何惻惻。","漢文明聖賈生賢，謫向長沙堪歎息。","人事多端何足怪，天文至信猶差忒。","月離于畢合滂沱，有時不雨何能測。"]', '["楚懷邪亂靈均直，放棄合宜何惻惻。","漢文明聖賈生賢，謫向长沙堪歎息。","人事多端何足怪，天文至信猶差忒。","月離于畢合滂沱，有时不雨何能測。"]', '诗', 'shi', '', NULL, '偶然二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7724db5-6f4a-4481-bebb-d1f23b35ac16', '偶然二首 二', '偶然二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["火發城頭魚水裏，救火竭池魚失水。","乖龍藏在牛[領]中，雷擊龍來牛枉死。","人道蓍神龜骨靈，試卜魚牛那至此。","六十四卦七十鑽，畢竟不能知所以。"]', '["火發城头鱼水裏，救火竭池鱼失水。","乖龙藏在牛[領]中，雷擊龙来牛枉死。","人道蓍神龟骨靈，試卜鱼牛那至此。","六十四卦七十鑽，畢竟不能知所以。"]', '诗', 'shi', '', NULL, '偶然二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2502008f-3e3f-44be-b6b0-ca781fd515be', '中秋月', '中秋月', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["萬里清光不可思，添愁益恨繞天涯。","誰人隴外久征戍，何處庭前新別離？","失寵故姬歸院夜，沒蕃老將上樓時。","照他幾許人腸斷，玉兔銀蟾遠不知。"]', '["万里清光不可思，添愁益恨繞天涯。","誰人隴外久征戍，何处庭前新別離？","失寵故姬归院夜，沒蕃老將上楼时。","照他幾許人腸斷，玉兔銀蟾远不知。"]', '诗', 'shi', '', NULL, '中秋月 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e2a6b80-7713-4eb1-af64-67bfd3f1d705', '謝李六郎中寄新蜀茶', '謝李六郎中寄新蜀茶', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["故情周匝向交親，新茗分張及病身。","紅紙一封書後信，綠芽十片火前春。","湯添勺水煎魚眼，末下刀圭攪麴塵。","不寄他人先寄我，應緣我是別茶人。"]', '["故情周匝向交親，新茗分張及病身。","紅紙一封书後信，綠芽十片火前春。","湯添勺水煎鱼眼，末下刀圭攪麴塵。","不寄他人先寄我，應緣我是別茶人。"]', '诗', 'shi', '', NULL, '謝李六郎中寄新蜀茶 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68907371-e59e-4d7e-9f18-77259b825333', '攜諸山客同上香爐峰遇雨而還霑濡狼籍互相笑謔題此解嘲', '携諸山客同上香爐峰遇雨而還霑濡狼籍互相笑謔題此解嘲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蕭灑登山去，龍鍾遇雨迴。","磴危攀薜荔，石滑踐莓苔。","韤汙君相謔，鞵穿我自咍。","莫欺泥土脚，曾蹋玉階來。"]', '["蕭灑登山去，龙鍾遇雨迴。","磴危攀薜荔，石滑踐莓苔。","韤汙君相謔，鞵穿我自咍。","莫欺泥土脚，曾蹋玉階来。"]', '诗', 'shi', '', NULL, '攜諸山客同上香爐峰遇雨而還霑濡狼籍互相笑謔題此解嘲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94dae647-be26-47ee-8f87-376641b86951', '彭蠡湖晚歸', '彭蠡湖晚归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["彭蠡湖天晚，桃花水氣春。","鳥飛千白點，日沒半紅輪。","何必爲遷客，無勞是病身。","但來臨此望，少有不愁人。"]', '["彭蠡湖天晚，桃花水氣春。","鸟飞千白点，日沒半紅輪。","何必爲遷客，無勞是病身。","但来臨此望，少有不愁人。"]', '诗', 'shi', '', NULL, '彭蠡湖晚歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b84ab8ee-824c-4e77-9fa1-3bd3337d21a5', '酬贈李鍊師見招', '酬贈李鍊師见招', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["幾年司諫直承明，今日求真禮上清。","曾犯龍鱗容不死，欲騎鶴背覓長生。","劉綱有婦仙同得，伯道無兒累更輕。","若許移家相近住，便驅雞犬上層城。"]', '["幾年司諫直承明，今日求真禮上清。","曾犯龙鱗容不死，欲騎鹤背覓长生。","劉綱有婦仙同得，伯道無兒累更轻。","若許移家相近住，便驱雞犬上層城。"]', '诗', 'shi', '', NULL, '酬贈李鍊師見招 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13ab9d59-6814-44f8-ad21-5772015ddb32', '西河雨夜送客', '西河雨夜送客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雲黑雨翛翛，江昏水闇流。","有風催解纜，無月伴登樓。","酒罷無多興，帆開不少留。","唯看一點火，遙認是行舟。"]', '["云黑雨翛翛，江昏水闇流。","有风催解纜，無月伴登楼。","酒罷無多兴，帆开不少留。","唯看一点火，遙認是行舟。"]', '诗', 'shi', '', NULL, '西河雨夜送客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8809aae3-6d96-42a6-8ce0-c87c3913afb4', '登西樓憶行簡', '登西楼憶行簡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["每因樓上西南望，始覺人間道路長。","礙日暮山青蔟蔟，漫天秋水白茫茫。","風波不見三年面，書信難傳萬里腸。","早晚東歸來下峽，穩乘船舫過瞿唐。"]', '["每因楼上西南望，始覺人间道路长。","礙日暮山青蔟蔟，漫天秋水白茫茫。","风波不见三年面，书信难傳万里腸。","早晚东归来下峽，穩乘船舫過瞿唐。"]', '诗', 'shi', '', NULL, '登西樓憶行簡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81271a1a-24ce-4c02-a61c-f656db67a430', '羅子', '羅子', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有女名羅子，生來纔兩春。","我今年已長，日夜二毛新。","顧念嬌啼面，思量老病身。","直應頭似雪，始得見成人。"]', '["有女名羅子，生来纔兩春。","我今年已长，日夜二毛新。","顧念嬌啼面，思量老病身。","直應头似雪，始得见成人。"]', '诗', 'shi', '', NULL, '羅子 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de6fe581-6600-41a0-a22e-727abd365047', '讀僧靈徹詩', '读僧靈徹诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["東林寺裏西廊下，石片鐫題數首詩。","言句怪來還校別，看名知是老湯師。"]', '["东林寺裏西廊下，石片鐫題數首诗。","言句怪来還校別，看名知是老湯師。"]', '诗', 'shi', '', NULL, '讀僧靈徹詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81e97a91-4e6d-434b-9e34-b96dfb28bfa2', '聽李士良琵琶', '听李士良琵琶', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["聲似胡兒彈舌語，愁如塞月恨邊雲。","閑人暫聽猶眉斂，可使和蕃公主聞。"]', '["声似胡兒彈舌語，愁如塞月恨邊云。","闲人暫听猶眉斂，可使和蕃公主闻。"]', '诗', 'shi', '', NULL, '聽李士良琵琶 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c37d3b2-f990-4cee-b255-893e9be92b47', '昭君怨', '昭君怨', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["明妃風貌最娉婷，合在椒房應四星。","只得當年備宮掖，何曾專夜奉幃屏。","見疎從道迷圖畫，知屈那教配虜庭。","自是君恩薄如紙，不須一向恨丹青。"]', '["明妃风貌最娉婷，合在椒房應四星。","只得當年備宮掖，何曾專夜奉幃屏。","见疎從道迷圖畫，知屈那教配虜庭。","自是君恩薄如紙，不須一向恨丹青。"]', '诗', 'shi', '', NULL, '昭君怨 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18922750-0af6-4fd1-bc1c-8e3a8b93d757', '閑吟', '闲吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自從苦學空門法，銷盡平生種種心。","唯有詩魔降未得，每逢風月一閑吟。"]', '["自從苦学空门法，銷尽平生種種心。","唯有诗魔降未得，每逢风月一闲吟。"]', '诗', 'shi', '', NULL, '閑吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98bbb2c1-4961-44e7-a1ae-0934d4f0662f', '戲問山石榴', '戲问山石榴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小樹山榴近砌栽，半含紅萼帶花來。","爭知司馬夫人妬，移到庭前便不開。"]', '["小樹山榴近砌栽，半含紅萼带花来。","爭知司马夫人妬，移到庭前便不开。"]', '诗', 'shi', '', NULL, '戲問山石榴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77500c0a-0e78-4401-a15c-0c74f3bfe67a', '編集拙詩成一十五卷因題卷末戲贈元九李二十', '編集拙诗成一十五卷因題卷末戲贈元九李二十', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一篇長恨有風情，十首秦吟近正聲。","每被老元偷格律，苦教短李伏歌行。","世間富貴應無分，身後文章合有名。","莫怪氣粗言語大，新排十五卷詩成。"]', '["一篇长恨有风情，十首秦吟近正声。","每被老元偷格律，苦教短李伏歌行。","世间富貴應無分，身後文章合有名。","莫怪氣粗言語大，新排十五卷诗成。"]', '诗', 'shi', '', NULL, '編集拙詩成一十五卷因題卷末戲贈元九李二十 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c87cd7a-1cf9-4eb9-8e3e-4681ff1b8605', '湖上閑望', '湖上闲望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["藤花浪拂紫茸條，菰葉風飜綠剪刀。","閑弄水芳生楚思，時時合眼詠離騷。"]', '["藤花浪拂紫茸條，菰葉风飜綠剪刀。","闲弄水芳生楚思，时时合眼詠離騷。"]', '诗', 'shi', '', NULL, '湖上閑望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('774b34e7-eef6-4332-9a27-1d3bc457a4f9', '江南謫居十韻', '江南謫居十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自哂沈冥客，曾爲獻納臣。","壯心徒許國，薄命不如人。","纔展凌雲翅，俄成失水鱗。","葵枯猶向日，蓬斷即辭春。","澤畔長愁地，天邊欲老身。","蕭條殘活計，冷落舊交親。","草合門無徑，煙消甑有塵。","憂方知酒聖，貧始覺錢神。","虎尾難容足，羊腸易覆輪。","行藏與通塞，一切任陶鈞。"]', '["自哂沈冥客，曾爲獻納臣。","壯心徒許国，薄命不如人。","纔展凌云翅，俄成失水鱗。","葵枯猶向日，蓬斷即辞春。","澤畔长愁地，天邊欲老身。","蕭條殘活計，冷落旧交親。","草合门無徑，煙消甑有塵。","憂方知酒聖，貧始覺錢神。","虎尾难容足，羊腸易覆輪。","行藏與通塞，一切任陶鈞。"]', '诗', 'shi', '', NULL, '江南謫居十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('844c38f2-4b10-43c2-bab9-b2d20fb39b30', '江樓夜吟元九律詩成三十韻', '江楼夜吟元九律诗成三十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昨夜江樓上，吟君數十篇。","詞飄朱檻底，韻墮淥江前。","清楚音諧律，精微思入玄。","收將白雪麗，奪盡碧雲妍。","寸截金爲句，雙雕玉作聯。","八風淒間發，五彩爛相宣。","冰扣聲聲冷，珠排字字圓。","文頭交比繡，筋骨軟於綿。","澒湧同波浪，錚鏦過管弦。","醴泉流出地，鈞樂下從天。","神鬼聞如泣，魚龍聽似禪。","星迴疑聚集，月落爲留連。","雁感無鳴者，猨愁亦悄然。","交流遷客淚，停住賈人船。","闇被歌姬乞，潛聞思婦傳。","斜行題粉壁，短卷寫紅箋。","肉味經時忘，頭風當日痊。","老張知定伏，短李愛應顛。","道屈才方振，身閑業始專。","天教聲烜赫，理合命迍邅。","顧我文章劣，知他氣力全。","工夫雖共到，巧拙尚相懸。","各有詩千首，俱拋海一邊。","白頭吟處變，青眼望中穿。","酬荅朝妨食，披尋夜廢眠。","老償文債負，宿結字因緣。","每歎陳夫子，常嗟李謫仙。","名高折人爵，思苦減天年。","不得當時遇，空令後代憐。","相悲今若此，湓浦與通川。"]', '["昨夜江楼上，吟君數十篇。","词飄朱檻底，韻墮淥江前。","清楚音諧律，精微思入玄。","收將白雪丽，奪尽碧云妍。","寸截金爲句，雙雕玉作聯。","八风淒间發，五彩爛相宣。","冰扣声声冷，珠排字字圓。","文头交比繡，筋骨軟於綿。","澒湧同波浪，錚鏦過管弦。","醴泉流出地，鈞乐下從天。","神鬼闻如泣，鱼龙听似禪。","星迴疑聚集，月落爲留連。","雁感無鳴者，猨愁亦悄然。","交流遷客泪，停住賈人船。","闇被歌姬乞，潛闻思婦傳。","斜行題粉壁，短卷寫紅箋。","肉味經时忘，头风當日痊。","老張知定伏，短李愛應顛。","道屈才方振，身闲業始專。","天教声烜赫，理合命迍邅。","顧我文章劣，知他氣力全。","工夫雖共到，巧拙尚相懸。","各有诗千首，俱拋海一邊。","白头吟处变，青眼望中穿。","酬荅朝妨食，披尋夜廢眠。","老償文債負，宿結字因緣。","每歎陳夫子，常嗟李謫仙。","名高折人爵，思苦減天年。","不得當时遇，空令後代怜。","相悲今若此，湓浦與通川。"]', '诗', 'shi', '', NULL, '江樓夜吟元九律詩成三十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c126b307-a5b5-4ca5-8bf0-f2dc281d193c', '潯陽歲晚寄元八郎中庾三十二員外', '潯陽歲晚寄元八郎中庾三十二員外', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閱水年將暮，燒金道未成。","丹砂不肯死，白髮自須生。","病肺慙杯滿，衰顏忌鏡明。","春深舊鄉夢，歲晚故交情。","一別浮雲散，雙瞻列宿榮。","螭頭階下立，龍尾道前行。","封事頻聞奏，除書數見名。","虛懷事僚友，平步取公卿。","漏盡雞人報，朝迴幼女迎。","可憐白司馬，老大在湓城。"]', '["閱水年將暮，燒金道未成。","丹砂不肯死，白髮自須生。","病肺慙杯满，衰顏忌镜明。","春深旧乡梦，歲晚故交情。","一別浮云散，雙瞻列宿榮。","螭头階下立，龙尾道前行。","封事頻闻奏，除书數见名。","虛懷事僚友，平步取公卿。","漏尽雞人報，朝迴幼女迎。","可怜白司马，老大在湓城。"]', '诗', 'shi', '', NULL, '潯陽歲晚寄元八郎中庾三十二員外 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08afd58f-844d-4862-9dc7-1bd76827b0db', '元九以綠絲布白輕褣見寄製成衣服以詩報知', '元九以綠絲布白轻褣见寄製成衣服以诗報知', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["綠絲文布素輕褣，珍重京華手自封。","貧友遠勞君寄附，病妻親爲我裁縫。","袴花白似秋雲薄，衫色青於春草濃。","欲著却休知不稱，折腰無復舊形容。"]', '["綠絲文布素轻褣，珍重京华手自封。","貧友远勞君寄附，病妻親爲我裁縫。","袴花白似秋云薄，衫色青於春草濃。","欲著却休知不稱，折腰無复旧形容。"]', '诗', 'shi', '', NULL, '元九以綠絲布白輕褣見寄製成衣服以詩報知 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e7bba2d-b113-4e16-a249-d88b1d8fbd6f', '清明日送韋侍御貶虔州', '清明日送韋侍御貶虔州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["寂寞清明日，蕭條司馬家。","留餳和冷粥，出火煮新茶。","欲別能無酒，相留亦有花。","南遷更何處，此地已天涯。"]', '["寂寞清明日，蕭條司马家。","留餳和冷粥，出火煮新茶。","欲別能無酒，相留亦有花。","南遷更何处，此地已天涯。"]', '诗', 'shi', '', NULL, '清明日送韋侍御貶虔州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('876758ef-70c7-4fcd-8747-1df2849f3340', '九江春望', '九江春望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["淼茫積水非吾土，飄泊浮萍自我身。","身外信緣爲活計，眼前隨事覓交親。","鑪煙豈異終南色，湓草寧殊渭北春。","此地何妨便終老，譬如元是九江人。"]', '["淼茫積水非吾土，飄泊浮萍自我身。","身外信緣爲活計，眼前隨事覓交親。","鑪煙豈異終南色，湓草寧殊渭北春。","此地何妨便終老，譬如元是九江人。"]', '诗', 'shi', '', NULL, '九江春望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99ed4dc5-b915-4fc3-829b-9bbe9c484337', '晚題東林寺雙池', '晚題东林寺雙池', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["向晚雙池好，初晴百物新。","褭枝翻翠羽，濺水躍紅鱗。","萍汎同遊子，蓮開當麗人。","臨流一惆悵，還憶曲江春。"]', '["向晚雙池好，初晴百物新。","褭枝翻翠羽，濺水躍紅鱗。","萍汎同游子，蓮开當丽人。","臨流一惆悵，還憶曲江春。"]', '诗', 'shi', '', NULL, '晚題東林寺雙池 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14197d9d-151b-407c-8999-9ffd8f0bbac5', '贈內子', '贈內子', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白髮長興歎，青娥亦伴愁。","寒衣補燈下，小女戲牀頭。","闇澹屏幃故，淒涼枕席秋。","貧中有等級，猶勝嫁黔婁。"]', '["白髮长兴歎，青娥亦伴愁。","寒衣補灯下，小女戲牀头。","闇澹屏幃故，淒涼枕席秋。","貧中有等級，猶勝嫁黔婁。"]', '诗', 'shi', '', NULL, '贈內子 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f577eb9b-cee3-459c-944d-234d43061766', '送客春遊嶺南二十韻', '送客春游嶺南二十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["已訝遊何遠，仍嗟別太頻。","離容君蹙促，贈語我殷勤。","迢遰天南面，蒼茫海北漘。","訶陵國分界，交趾郡爲鄰。","蓊鬱三光晦，溫暾四氣勻。","陰晴變寒暑，昏曉錯星辰。","瘴地難爲老，蠻陬不易馴。","土民稀白首，洞主盡黃巾。","戰艦猶驚浪，戎車未息塵。","紅旗圍卉服，紫綬裹文身。","麪苦桄榔裛，漿酸橄欖新。","牙檣迎海舶，銅鼓賽江神。","不凍貪泉暖，無霜毒草春。","雲煙蟒蛇氣，刀劒鰐魚鱗。","路足羈棲客，官多謫逐臣。","天黃生颶母，雨黑長楓人。","迴使先傳語，征軒早返輪。","須防杯裏蠱，莫愛橐中珍。","北與南殊俗，身將貨孰親。","嘗聞君子誡，憂道不憂貧。"]', '["已訝游何远，仍嗟別太頻。","離容君蹙促，贈語我殷勤。","迢遰天南面，蒼茫海北漘。","訶陵国分界，交趾郡爲鄰。","蓊鬱三光晦，溫暾四氣勻。","陰晴变寒暑，昏晓錯星辰。","瘴地难爲老，蠻陬不易馴。","土民稀白首，洞主尽黄巾。","戰艦猶驚浪，戎车未息塵。","紅旗圍卉服，紫綬裹文身。","麪苦桄榔裛，漿酸橄欖新。","牙檣迎海舶，銅鼓賽江神。","不凍貪泉暖，無霜毒草春。","云煙蟒蛇氣，刀劒鰐鱼鱗。","路足羈棲客，官多謫逐臣。","天黄生颶母，雨黑长楓人。","迴使先傳語，征軒早返輪。","須防杯裏蠱，莫愛橐中珍。","北與南殊俗，身將貨孰親。","嘗闻君子誡，憂道不憂貧。"]', '诗', 'shi', '', NULL, '送客春遊嶺南二十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14ee2327-fdd6-4c71-91d1-08367b5b96a1', '自題', '自題', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["功名宿昔人多許，寵辱斯須自不如。","一旦失恩先左降，三年隨例未量移。","馬頭覓角生何日，石火敲光住幾時。","前事是身俱若此，空門不去欲何之。"]', '["功名宿昔人多許，寵辱斯須自不如。","一旦失恩先左降，三年隨例未量移。","马头覓角生何日，石火敲光住幾时。","前事是身俱若此，空门不去欲何之。"]', '诗', 'shi', '', NULL, '自題 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bc0118e-9f8e-4778-815b-0190138c80b0', '自悲', '自悲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["火宅煎熬地，霜松摧折身。","因知羣動內，易死不過人。"]', '["火宅煎熬地，霜松摧折身。","因知羣动內，易死不過人。"]', '诗', 'shi', '', NULL, '自悲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ba839ae-d335-462b-980a-b1584012051b', '尋郭道士不遇', '尋郭道士不遇', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["郡中乞假來相訪，洞裏朝元去不逢。","看院祗留雙白鶴，入門惟見一青松。","藥爐有火丹應伏，雲碓無人水自舂。","欲問參同契中事，更期何日得從容。"]', '["郡中乞假来相訪，洞裏朝元去不逢。","看院祗留雙白鹤，入门惟见一青松。","藥爐有火丹應伏，云碓無人水自舂。","欲问參同契中事，更期何日得從容。"]', '诗', 'shi', '', NULL, '尋郭道士不遇 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e4a33e3-9369-45e2-a358-92489a952703', '潯陽春三首 春生', '潯陽春三首 春生', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["春生何處闇周遊，海角天涯徧始休。","先遣和風報消息，續教啼鳥說來由。","展張草色長河畔，點綴花房小樹頭。","若到故園應覓我，爲傳淪落在江州。"]', '["春生何处闇周游，海角天涯徧始休。","先遣和风報消息，續教啼鸟说来由。","展張草色长河畔，点綴花房小樹头。","若到故园應覓我，爲傳淪落在江州。"]', '诗', 'shi', '', NULL, '潯陽春三首 春生 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9af4579c-e4a0-41ff-b22a-123f8908bafb', '潯陽春三首 春來', '潯陽春三首 春来', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["春來觸地故鄉情，忽見風光憶兩京。","金谷蹋花香騎入，曲江碾草鈿車行。","誰家綠酒歡連夜，何處紅樓睡失明。","獨有不眠不醉客，經春冷坐古湓城。"]', '["春来觸地故乡情，忽见风光憶兩京。","金谷蹋花香騎入，曲江碾草鈿车行。","誰家綠酒歡連夜，何处紅楼睡失明。","独有不眠不醉客，經春冷坐古湓城。"]', '诗', 'shi', '', NULL, '潯陽春三首 春來 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab2ffc31-ab68-4178-88b1-bd317a490331', '潯陽春三首 春去', '潯陽春三首 春去', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一從澤畔爲遷客，兩度江頭送暮春。","白髮更添今日鬢，青衫不改去年身。","百川未有迴流水，一老終無却少人。","四十六時三月盡，送春爭得不殷勤。"]', '["一從澤畔爲遷客，兩度江头送暮春。","白髮更添今日鬢，青衫不改去年身。","百川未有迴流水，一老終無却少人。","四十六时三月尽，送春爭得不殷勤。"]', '诗', 'shi', '', NULL, '潯陽春三首 春去 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02add0b5-8fe7-4920-8f97-ff81b24c4fa2', '夢微之', '梦微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晨起臨風一惆悵，通川湓水斷相聞。","不知憶我因何事，昨夜三迴夢見君。"]', '["晨起臨风一惆悵，通川湓水斷相闻。","不知憶我因何事，昨夜三迴梦见君。"]', '诗', 'shi', '', NULL, '夢微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('824ed317-d044-40fc-8811-b6ab635716f8', '贈韋鍊師', '贈韋鍊師', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["潯陽遷客爲居士，身似浮雲心似灰。","上界女仙無嗜欲，何因相顧兩裴回。","共疑過去人間世，曾作誰家夫婦來。"]', '["潯陽遷客爲居士，身似浮云心似灰。","上界女仙無嗜欲，何因相顧兩裴回。","共疑過去人间世，曾作誰家夫婦来。"]', '诗', 'shi', '', NULL, '贈韋鍊師 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9972f7bb-ae5b-49e4-87df-381386af66b6', '問劉十九', '问劉十九', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["綠螘新醅酒，紅泥小火壚。","晚來天欲雪，能飲一杯無。"]', '["綠螘新醅酒，紅泥小火壚。","晚来天欲雪，能饮一杯無。"]', '诗', 'shi', '', NULL, '問劉十九 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e871507-9990-491c-a177-798d6094c020', '得行簡書聞欲下峽先以詩寄', '得行簡书闻欲下峽先以诗寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝來又得東川信，欲取春初發梓州。","書報九江聞暫喜，路經三峽想還愁。","瀟湘瘴霧加餐飯，灩澦驚波穩泊舟。","欲寄兩行迎爾淚，長江不肯向西流。"]', '["朝来又得东川信，欲取春初發梓州。","书報九江闻暫喜，路經三峽想還愁。","瀟湘瘴霧加餐飯，灩澦驚波穩泊舟。","欲寄兩行迎爾泪，长江不肯向西流。"]', '诗', 'shi', '', NULL, '得行簡書聞欲下峽先以詩寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97897a5d-9917-4e93-a4f4-89e4270e9025', '南湖早春', '南湖早春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風迴雲斷雨初晴，返照湖邊暖復明。","亂點碎紅山杏發，平鋪新綠水蘋生。","翅低白雁飛仍重，舌澀黃鸝語未成。","不道江南春不好，年年衰病減心情。"]', '["风迴云斷雨初晴，返照湖邊暖复明。","亂点碎紅山杏發，平鋪新綠水蘋生。","翅低白雁飞仍重，舌澀黄鸝語未成。","不道江南春不好，年年衰病減心情。"]', '诗', 'shi', '', NULL, '南湖早春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f636bb45-eda9-4f6f-be18-8ec5f82ea72f', '元十八從事南海欲出廬山臨別舊居有戀泉聲之什因以投和兼伸別情', '元十八從事南海欲出廬山臨別旧居有戀泉声之什因以投和兼伸別情', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["賢侯辟士禮從容，莫戀泉聲問所從。","雨露初承黃紙詔，煙霞欲別紫霄峰。","傷弓未息新驚鳥，得水難留久臥龍。","我正退藏君變化，一杯可易得相逢。"]', '["賢侯辟士禮從容，莫戀泉声问所從。","雨露初承黄紙詔，煙霞欲別紫霄峰。","傷弓未息新驚鸟，得水难留久臥龙。","我正退藏君变化，一杯可易得相逢。"]', '诗', 'shi', '', NULL, '元十八從事南海欲出廬山臨別舊居有戀泉聲之什因以投和兼伸別情 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5883f045-1f80-4c5a-8570-960a997c61c8', '題韋家泉池', '題韋家泉池', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["泉落青山出白雲，縈村繞郭幾家分。","自從引作池中水，深淺方圓一任君。"]', '["泉落青山出白云，縈村繞郭幾家分。","自從引作池中水，深淺方圓一任君。"]', '诗', 'shi', '', NULL, '題韋家泉池 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25d13241-414a-4a80-a9aa-7d4c41e8dd64', '醉中對紅葉', '醉中对紅葉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["臨風杪秋樹，對酒長年人。","醉貌如霜葉，雖紅不是春。"]', '["臨风杪秋樹，对酒长年人。","醉貌如霜葉，雖紅不是春。"]', '诗', 'shi', '', NULL, '醉中對紅葉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bf37dca-3495-4cbf-b831-30d9a048d499', '遣懷', '遣懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["羲和走馭趂年光，不許人間日月長。","遂使四時都似電，爭教兩鬢不成霜。","榮銷枯去無非命，壯盡衰來亦是常。","已共身心要約定，窮通生死不驚忙。"]', '["羲和走馭趂年光，不許人间日月长。","遂使四时都似電，爭教兩鬢不成霜。","榮銷枯去無非命，壯尽衰来亦是常。","已共身心要約定，窮通生死不驚忙。"]', '诗', 'shi', '', NULL, '遣懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0ad553b-a42b-4e76-b0f6-87bde5294748', '點額魚', '点額鱼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["龍門點額意何如，紅尾青鬐却返初。","見說在天行雨苦，爲龍未必勝爲魚。"]', '["龙门点額意何如，紅尾青鬐却返初。","见说在天行雨苦，爲龙未必勝爲鱼。"]', '诗', 'shi', '', NULL, '點額魚 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50b4f3d6-41a5-410b-b73a-2fcd3ace71ee', '聞龜兒詠詩', '闻龟兒詠诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憐渠已解詠詩章，搖膝支頤學二郎。","莫學二郎吟太苦，纔年四十鬢如霜。"]', '["怜渠已解詠诗章，搖膝支頤学二郎。","莫学二郎吟太苦，纔年四十鬢如霜。"]', '诗', 'shi', '', NULL, '聞龜兒詠詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa33260e-61e3-4cf1-87d1-972857cfd177', '對酒', '对酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["未濟卦中休卜命，參同契裏莫勞心。","無如飲此銷愁物，一餉愁消直萬金。"]', '["未濟卦中休卜命，參同契裏莫勞心。","無如饮此銷愁物，一餉愁消直万金。"]', '诗', 'shi', '', NULL, '對酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7695bbf-bb09-493a-b5ed-ce267733efdb', '東牆夜合樹去秋爲風雨所摧今年花時悵然有感', '东牆夜合樹去秋爲风雨所摧今年花时悵然有感', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["碧荑紅縷今何在，風雨飄將去不回。","惆悵去年牆下地，今春唯有薺花開。"]', '["碧荑紅縷今何在，风雨飄將去不回。","惆悵去年牆下地，今春唯有薺花开。"]', '诗', 'shi', '', NULL, '東牆夜合樹去秋爲風雨所摧今年花時悵然有感 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15c70067-d772-491a-8a1c-f1cc09a40c68', '病起', '病起', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["病不出門無限時，今朝強出與誰期。","經年不上江樓醉，勞動春風颺酒旗。"]', '["病不出门無限时，今朝強出與誰期。","經年不上江楼醉，勞动春风颺酒旗。"]', '诗', 'shi', '', NULL, '病起 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6306f2e4-9344-4dd5-b44b-7faf84c8d942', '夢亡友劉太白同遊彰敬寺', '梦亡友劉太白同游彰敬寺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三千里外臥江州，十五年前哭老劉。","昨夜夢中彰敬寺，死生魂魄暫同遊。"]', '["三千里外臥江州，十五年前哭老劉。","昨夜梦中彰敬寺，死生魂魄暫同游。"]', '诗', 'shi', '', NULL, '夢亡友劉太白同遊彰敬寺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d950cef-da89-4d32-b2bb-7667a1066141', '與果上人歿時題此訣別兼簡二林僧社', '與果上人歿时題此訣別兼簡二林僧社', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["本結菩提香火社，爲嫌煩惱電泡身。","不須惆悵從師去，先請西方作主人。"]', '["本結菩提香火社，爲嫌煩惱電泡身。","不須惆悵從師去，先請西方作主人。"]', '诗', 'shi', '', NULL, '與果上人歿時題此訣別兼簡二林僧社 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba3acbe6-e4d9-4e33-b152-e57b43a0f089', '贈寫真者', '贈寫真者', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["子騁丹青日，予當醜老時。","無勞役神思，更畫病容儀。","迢遞麒麟閣，圖功未有期。","區區尺素上，焉用寫真爲。"]', '["子騁丹青日，予當醜老时。","無勞役神思，更畫病容儀。","迢遞麒麟閣，圖功未有期。","區區尺素上，焉用寫真爲。"]', '诗', 'shi', '', NULL, '贈寫真者 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66a99fa4-5242-4372-9c99-3d5a1fac58e0', '劉十九同宿', '劉十九同宿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紅旗破賊非吾事，黃紙除書無我名。","唯共嵩陽劉處士，圍棊賭酒到天明。"]', '["紅旗破賊非吾事，黄紙除书無我名。","唯共嵩陽劉处士，圍棊賭酒到天明。"]', '诗', 'shi', '', NULL, '劉十九同宿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30ca5f9d-0e0e-4ad1-ab92-e5838694631c', '十二年冬江西溫暖喜元八寄金石稜到因題此詩', '十二年冬江西溫暖喜元八寄金石稜到因題此诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今冬臘候不嚴凝，暖霧溫風氣上騰。","山脚崦中纔有雪，江流慢處亦無冰。","欲將何藥防春瘴，只有元家金石稜。"]', '["今冬臘候不嚴凝，暖霧溫风氣上腾。","山脚崦中纔有雪，江流慢处亦無冰。","欲將何藥防春瘴，只有元家金石稜。"]', '诗', 'shi', '', NULL, '十二年冬江西溫暖喜元八寄金石稜到因題此詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('879b0db4-44f2-40c2-bf75-2ee5f6c7f945', '閑意', '闲意', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不爭榮耀任沈淪，日與時疎共道親。","北省朋僚音信斷，東林長老往還頻。","病停夜食閑如社，慵擁朝裘暖似春。","漸老濺諳閑氣味，終身不擬作忙人。"]', '["不爭榮耀任沈淪，日與时疎共道親。","北省朋僚音信斷，东林长老往還頻。","病停夜食闲如社，慵擁朝裘暖似春。","漸老濺諳闲氣味，終身不擬作忙人。"]', '诗', 'shi', '', NULL, '閑意 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11c8685e-44f0-42b3-9d97-af559c8d773a', '送友人上峽赴東川辟命', '送友人上峽赴东川辟命', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["見說瞿塘峽，斜銜灩澦根。","難於尋鳥路，險過上龍門。","羊角風頭急，桃花水色渾。","山迴若鼇轉，舟入似鯨吞。","岸合愁天斷，波跳恐地翻。","憐君經此去，爲感主人恩。"]', '["见说瞿塘峽，斜銜灩澦根。","难於尋鸟路，險過上龙门。","羊角风头急，桃花水色渾。","山迴若鼇轉，舟入似鯨吞。","岸合愁天斷，波跳恐地翻。","怜君經此去，爲感主人恩。"]', '诗', 'shi', '', NULL, '送友人上峽赴東川辟命 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6895b115-1b41-4602-9cf5-c6b59ed8ae40', '夜送孟司功', '夜送孟司功', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["潯陽白司馬，夜送孟功曹。","江闇管弦急，樓明燈火高。","湖波翻似箭，霜草殺如刀。","且莫開征櫂，陰風正怒號。"]', '["潯陽白司马，夜送孟功曹。","江闇管弦急，楼明灯火高。","湖波翻似箭，霜草殺如刀。","且莫开征櫂，陰风正怒號。"]', '诗', 'shi', '', NULL, '夜送孟司功 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2d2ab26-d4dd-4dc0-bb9b-40cff81eefaf', '衰病', '衰病', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老辭遊冶尋花伴，病別荒狂舊酒徒。","更恐五年三歲後，些些譚笑亦應無。"]', '["老辞游冶尋花伴，病別荒狂旧酒徒。","更恐五年三歲後，些些譚笑亦應無。"]', '诗', 'shi', '', NULL, '衰病 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48542e21-ea60-4ced-829b-a9d04a4e1fa8', '題詩屏風絕句', '題诗屏风絕句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["相憶采君詩作障，自書自勘不辭勞。","障成定被人爭寫，從此南中紙價高。"]', '["相憶采君诗作障，自书自勘不辞勞。","障成定被人爭寫，從此南中紙價高。"]', '诗', 'shi', '', NULL, '題詩屏風絕句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b5ee9a9-e629-4f47-9787-ff75de3e5eb8', '荅微之', '荅微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["君寫我詩盈寺壁，我題君句滿屏風。","與君相遇知何處，兩葉浮萍大海中。"]', '["君寫我诗盈寺壁，我題君句满屏风。","與君相遇知何处，兩葉浮萍大海中。"]', '诗', 'shi', '', NULL, '荅微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7331c724-e098-4760-a87c-2b1fa13c2d5a', '偶宴有懷', '偶宴有懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["遇興尋文客，因歡命酒徒。","春遊憶親故，夜會似京都。","詩思閑仍在，鄉愁醉暫無。","狂來欲起舞，慙見白髭鬚。"]', '["遇兴尋文客，因歡命酒徒。","春游憶親故，夜會似京都。","诗思闲仍在，乡愁醉暫無。","狂来欲起舞，慙见白髭鬚。"]', '诗', 'shi', '', NULL, '偶宴有懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d5a6da0-206f-4654-ae5b-353ee86cd2cd', '山中酬江州崔使君見寄', '山中酬江州崔使君见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["眷眄情無恨，優容禮有餘。","三年爲郡吏，一半許山居。","酒熟心相待，詩來手自書。","庾樓春好醉，明月且回車。"]', '["眷眄情無恨，優容禮有餘。","三年爲郡吏，一半許山居。","酒熟心相待，诗来手自书。","庾楼春好醉，明月且回车。"]', '诗', 'shi', '', NULL, '山中酬江州崔使君見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d34117d1-2a4d-47d7-96ad-4d380ffe0210', '山枇杷', '山枇杷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["深山老去惜年華，況對東谿野枇杷。","火樹風來翻絳燄，瓊枝日出曬紅紗。","回看桃李都無色，映得芙蓉不是花。","爭奈結根深石底，無因移得到人家。"]', '["深山老去惜年华，況对东谿野枇杷。","火樹风来翻絳燄，瓊枝日出曬紅紗。","回看桃李都無色，映得芙蓉不是花。","爭奈結根深石底，無因移得到人家。"]', '诗', 'shi', '', NULL, '山枇杷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f365d15-a922-45b3-9d17-3b15984fd485', '聞李尚書拜相因以長句寄賀微之', '闻李尚书拜相因以长句寄賀微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憐君不久在通川，知已新提造化權。","夔卨定求才濟世，張雷應辨氣衝天。","那知淪落天涯日，正是陶鈞海內年。","肯向泥中拋折劒，不收重鑄作龍泉。"]', '["怜君不久在通川，知已新提造化權。","夔卨定求才濟世，張雷應辨氣衝天。","那知淪落天涯日，正是陶鈞海內年。","肯向泥中拋折劒，不收重鑄作龙泉。"]', '诗', 'shi', '', NULL, '聞李尚書拜相因以長句寄賀微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5349017e-b49f-4848-8322-91c844644449', '歲暮', '歲暮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["窮陰急景坐相催，壯齒韶顏去不回。","舊病重因年老發，新愁多是夜長來。","膏明自爇緣多事，雁默先烹爲不才。","禍福細尋無會處，不如且進手中杯。"]', '["窮陰急景坐相催，壯齒韶顏去不回。","旧病重因年老發，新愁多是夜长来。","膏明自爇緣多事，雁默先烹爲不才。","禍福細尋無會处，不如且進手中杯。"]', '诗', 'shi', '', NULL, '歲暮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d77cd906-d59c-42b4-ae6b-7e49952fb2e6', '雨中赴劉十九二林之期及到寺劉已先去因以四韻寄之', '雨中赴劉十九二林之期及到寺劉已先去因以四韻寄之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雲中臺殿泥中路，既阻同遊嬾却還。","將謂獨愁猶對雨，不知多興已尋山。","纔應行到千峰裏，只校來遲半日間。","最惜杜鵑花爛熳，春風吹盡不同攀。"]', '["云中台殿泥中路，既阻同游嬾却還。","將謂独愁猶对雨，不知多兴已尋山。","纔應行到千峰裏，只校来遲半日间。","最惜杜鵑花爛熳，春风吹尽不同攀。"]', '诗', 'shi', '', NULL, '雨中赴劉十九二林之期及到寺劉已先去因以四韻寄之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84941cd9-2bf2-459b-a86e-8da00543c303', '薔薇正開春酒初熟因招劉十九張大夫崔二十四同飲', '薔薇正开春酒初熟因招劉十九張大夫崔二十四同饮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["甕頭竹葉經春熟，階底薔薇入夏開。","似火淺深紅壓架，如餳氣味綠黏臺。","試將詩句相招去，倘有風情或可來。","明日早花應更好，心期同醉卯時杯。"]', '["甕头竹葉經春熟，階底薔薇入夏开。","似火淺深紅壓架，如餳氣味綠黏台。","試將诗句相招去，倘有风情或可来。","明日早花應更好，心期同醉卯时杯。"]', '诗', 'shi', '', NULL, '薔薇正開春酒初熟因招劉十九張大夫崔二十四同飲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c2ac815-b560-49c4-a755-362b2eecba02', '李白墓', '李白墓', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["采石江邊李白墳，遶田無限草連雲。","可憐荒壠窮泉骨，曾有驚天動地文。","但是詩人多薄命，就中淪落不過君。"]', '["采石江邊李白墳，遶田無限草連云。","可怜荒壠窮泉骨，曾有驚天动地文。","但是诗人多薄命，就中淪落不過君。"]', '诗', 'shi', '', NULL, '李白墓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aad436c9-6c04-497c-b925-77eb354ff204', '對酒', '对酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["漫把參同契，難燒伏火砂。","有時成白首，無處問黃芽。","幻世如泡影，浮生抵眼花。","唯將綠醅酒，且替紫河車。"]', '["漫把參同契，难燒伏火砂。","有时成白首，無处问黄芽。","幻世如泡影，浮生抵眼花。","唯將綠醅酒，且替紫河车。"]', '诗', 'shi', '', NULL, '對酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7158d0ec-d042-44dc-bb57-d7f9efce6247', '戲荅諸少年', '戲荅諸少年', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["顧我長年頭似雪，饒君壯歲氣如雲。","朱顏今日雖欺我，白髮他時不放君。"]', '["顧我长年头似雪，饒君壯歲氣如云。","朱顏今日雖欺我，白髮他时不放君。"]', '诗', 'shi', '', NULL, '戲荅諸少年 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('069f2deb-b4ec-4ea8-9929-edf1871e4b6d', '風雨晚泊', '风雨晚泊', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["苦竹林邊蘆葦叢，停舟一望思無窮。","青苔撲地連春雨，白浪掀天盡日風。","忽忽百年行欲半，茫茫萬事坐成空。","此生飄蕩何時定，一縷鴻毛天地中。"]', '["苦竹林邊蘆葦叢，停舟一望思無窮。","青苔撲地連春雨，白浪掀天尽日风。","忽忽百年行欲半，茫茫万事坐成空。","此生飄蕩何时定，一縷鴻毛天地中。"]', '诗', 'shi', '', NULL, '風雨晚泊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba297457-d7c2-401e-a172-f5ff83138bbf', '題崔使君新樓', '題崔使君新楼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憂人何處可消憂，碧甕紅欄湓水頭。","從此潯陽風月夜，崔公樓替庾公樓。"]', '["憂人何处可消憂，碧甕紅欄湓水头。","從此潯陽风月夜，崔公楼替庾公楼。"]', '诗', 'shi', '', NULL, '題崔使君新樓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa66d71c-0527-46e9-b1cc-d08016c8cb75', '山中戲問韋侍御', '山中戲问韋侍御', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我抱棲雲志，君懷濟世才。","常吟反招隱，那得入山來。"]', '["我抱棲云志，君懷濟世才。","常吟反招隐，那得入山来。"]', '诗', 'shi', '', NULL, '山中戲問韋侍御 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('812e131e-eb6a-435a-9756-f8ea5c93d54a', '贈曇禪師', '贈曇禪師', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["五年不入慈恩寺，今日尋師始一來。","欲知火宅焚燒苦，方寸如今化作灰。"]', '["五年不入慈恩寺，今日尋師始一来。","欲知火宅焚燒苦，方寸如今化作灰。"]', '诗', 'shi', '', NULL, '贈曇禪師 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb387f5d-fcb6-44db-8658-4fe9f244be58', '寄微之', '寄微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["帝城行樂日紛紛，天畔窮愁我與君。","秦女笑歌春不見，巴猨啼哭夜常聞。","何處琵琶弦似語，誰家[咼]墮髻如雲。","人生多少歡娛事，那獨千分無一分。"]', '["帝城行乐日紛紛，天畔窮愁我與君。","秦女笑歌春不见，巴猨啼哭夜常闻。","何处琵琶弦似語，誰家[咼]墮髻如云。","人生多少歡娛事，那独千分無一分。"]', '诗', 'shi', '', NULL, '寄微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0167d8b4-1f81-4c79-8d56-c1a57e4e7dbe', '醉吟二首 一', '醉吟二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["空王百法學未得，姹女丹砂燒即飛。","事事無成身老也，醉鄉不去欲何歸。"]', '["空王百法学未得，姹女丹砂燒即飞。","事事無成身老也，醉乡不去欲何归。"]', '诗', 'shi', '', NULL, '醉吟二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3e985fc-9090-4736-b744-27679a833c3d', '醉吟二首 二', '醉吟二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["兩鬢千莖新似雪，十分一醆欲如泥。","酒狂又引詩魔發，日午悲吟到日西。"]', '["兩鬢千莖新似雪，十分一醆欲如泥。","酒狂又引诗魔發，日午悲吟到日西。"]', '诗', 'shi', '', NULL, '醉吟二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f5b9f54-8b1c-4db9-ae06-94f25c12e347', '曉寢', '晓寢', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["轉枕重安寢，回頭一欠伸。","紙窗明覺曉，布被暖知春。","莫強疎慵性，須安老大身。","雞鳴一覺睡，不博早朝人。"]', '["轉枕重安寢，回头一欠伸。","紙窗明覺晓，布被暖知春。","莫強疎慵性，須安老大身。","雞鳴一覺睡，不博早朝人。"]', '诗', 'shi', '', NULL, '曉寢 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb2928c7-b8f6-44d2-b86a-c4853b9fa6da', '荅元八郎中楊十二博士', '荅元八郎中楊十二博士', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["身覺浮雲無所著，心同止水有何情。","但知瀟灑疎朝市，不要崎嶇隱姓名。","盡日觀魚臨澗坐，有時隨鹿上山行。","誰能拋得人間事，來共騰騰過此生。"]', '["身覺浮云無所著，心同止水有何情。","但知瀟灑疎朝市，不要崎嶇隐姓名。","尽日观鱼臨澗坐，有时隨鹿上山行。","誰能拋得人间事，来共腾腾過此生。"]', '诗', 'shi', '', NULL, '荅元八郎中楊十二博士 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83283b10-324c-472e-8a17-bd6bf8e8d093', '湖亭與行簡宿', '湖亭與行簡宿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["潯陽少有風情客，招宿湖亭盡却回。","水檻虛涼風月好，夜深誰共阿憐來。"]', '["潯陽少有风情客，招宿湖亭尽却回。","水檻虛涼风月好，夜深誰共阿怜来。"]', '诗', 'shi', '', NULL, '湖亭與行簡宿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f8e55f9-e589-4bfd-8dcd-40ae58c8e4bb', '八月十五日夜湓亭望月', '八月十五日夜湓亭望月', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昔年八月十五夜，曲江池畔杏園邊。","今年八月十五夜，湓浦沙頭水館前。","西北望鄉何處是，東南見月幾迴圓。","臨風一歎無人會，今夜清光似往年。"]', '["昔年八月十五夜，曲江池畔杏园邊。","今年八月十五夜，湓浦沙头水館前。","西北望乡何处是，东南见月幾迴圓。","臨风一歎無人會，今夜清光似往年。"]', '诗', 'shi', '', NULL, '八月十五日夜湓亭望月 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06824978-5d50-4300-a304-63ea91fdfeca', '贈江客', '贈江客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江柳影寒新雨地，塞鴻聲急欲霜天。","愁君獨向沙頭宿，水遶蘆花月滿船。"]', '["江柳影寒新雨地，塞鴻声急欲霜天。","愁君独向沙头宿，水遶蘆花月满船。"]', '诗', 'shi', '', NULL, '贈江客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a34dc8d-e6aa-4130-9616-28c12f531874', '殘暑招客', '殘暑招客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雲截山腰斷，風驅雨脚迴。","早陰江上散，殘熱日中來。","却取生衣著，重拈竹簟開。","誰能淘晚熱，閑飲兩三杯。"]', '["云截山腰斷，风驱雨脚迴。","早陰江上散，殘熱日中来。","却取生衣著，重拈竹簟开。","誰能淘晚熱，闲饮兩三杯。"]', '诗', 'shi', '', NULL, '殘暑招客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e197445-4c06-4b2d-9fe6-4e5217654288', '潯陽秋懷贈許明府', '潯陽秋懷贈許明府', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["霜紅二林葉，風白九江波。","暝色投煙鳥，秋聲帶雨荷。","馬閑無處出，門冷少人過。","鹵莽還鄉夢，依稀望闕歌。","共思除醉外，無計奈愁何。","試問陶家酒，新篘得幾多。"]', '["霜紅二林葉，风白九江波。","暝色投煙鸟，秋声带雨荷。","马闲無处出，门冷少人過。","鹵莽還乡梦，依稀望闕歌。","共思除醉外，無計奈愁何。","試问陶家酒，新篘得幾多。"]', '诗', 'shi', '', NULL, '潯陽秋懷贈許明府 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d1db9cd-036a-4a04-896f-e07c31372726', '九日醉吟', '九日醉吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有恨頭還白，無情菊自黃。","一爲州司馬，三見歲重陽。","劒匣塵埃滿，籠禽日月長。","身從漁父笑，門任雀羅張。","問疾因留客，聽吟偶置觴。","歎時論倚伏，懷舊數存亡。","奈老應無計，治愁或有方。","無過學王績，唯以醉爲鄉。"]', '["有恨头還白，無情菊自黄。","一爲州司马，三见歲重陽。","劒匣塵埃满，籠禽日月长。","身從漁父笑，门任雀羅張。","问疾因留客，听吟偶置觴。","歎时論倚伏，懷旧數存亡。","奈老應無計，治愁或有方。","無過学王績，唯以醉爲乡。"]', '诗', 'shi', '', NULL, '九日醉吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96897153-b390-4f61-aa6b-cbdb367eb3b6', '問韋山人山甫', '问韋山人山甫', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["身名身事兩蹉跎，試就先生問若何。","從此神仙學得否，白鬚雖有未爲多。"]', '["身名身事兩蹉跎，試就先生问若何。","從此神仙学得否，白鬚雖有未爲多。"]', '诗', 'shi', '', NULL, '問韋山人山甫 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d92569af-16f9-4545-a82a-d5c2eebed9c6', '送蕭鍊師步虛詞十首卷後以二絕繼之 一', '送蕭鍊師步虛词十首卷後以二絕繼之 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["欲上瀛州臨別時，贈君十首步虛詞。","天仙若愛應相問，可道江州司馬詩。"]', '["欲上瀛州臨別时，贈君十首步虛词。","天仙若愛應相问，可道江州司马诗。"]', '诗', 'shi', '', NULL, '送蕭鍊師步虛詞十首卷後以二絕繼之 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('885da177-4564-400e-b2e0-0b248ea011b5', '送蕭鍊師步虛詞十首卷後以二絕繼之 二', '送蕭鍊師步虛词十首卷後以二絕繼之 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["花紙瑤緘松墨字，把將天上共誰開。","試呈王母如堪唱，發遣雙成更取來。"]', '["花紙瑤緘松墨字，把將天上共誰开。","試呈王母如堪唱，發遣雙成更取来。"]', '诗', 'shi', '', NULL, '送蕭鍊師步虛詞十首卷後以二絕繼之 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4993c67c-b791-47a1-8c18-a873b8cb399d', '贈李兵馬使', '贈李兵马使', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["身得貳師餘氣概，家藏都尉舊詩章。","江南別有樓船將，燕頷虬鬚不姓楊。"]', '["身得貳師餘氣概，家藏都尉旧诗章。","江南別有楼船將，燕頷虬鬚不姓楊。"]', '诗', 'shi', '', NULL, '贈李兵馬使 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('854c3dcd-7749-41b5-a058-92d5b6589acb', '題遺愛寺前溪松', '題遺愛寺前溪松', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["偃亞長松樹，侵臨小石溪。","靜將流水對，高共遠峰齊。","翠蓋煙籠密，花幢雪壓低。","與僧清影坐，借鶴穩枝棲。","筆寫形難似，琴偷韻易迷。","暑天風槭槭，晴夜露淒淒。","獨契依爲舍，閑行遶作蹊。","棟梁君莫採，留著伴幽棲。"]', '["偃亞长松樹，侵臨小石溪。","静將流水对，高共远峰齊。","翠蓋煙籠密，花幢雪壓低。","與僧清影坐，借鹤穩枝棲。","笔寫形难似，琴偷韻易迷。","暑天风槭槭，晴夜露淒淒。","独契依爲舍，闲行遶作蹊。","棟梁君莫採，留著伴幽棲。"]', '诗', 'shi', '', NULL, '題遺愛寺前溪松 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a6cfaeb-5597-4192-9df1-014ddaf06389', '廬山草堂夜雨獨宿寄牛二李七庾三十二員外', '廬山草堂夜雨独宿寄牛二李七庾三十二員外', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["丹霄攜手三君子，白髮垂頭一病翁。","蘭省花時錦帳下，廬山雨夜草菴中。","終身膠漆心應在，半路雲泥跡不同。","唯有無生三昧觀，榮枯一照兩成空。"]', '["丹霄携手三君子，白髮垂头一病翁。","蘭省花时錦帳下，廬山雨夜草菴中。","終身膠漆心應在，半路云泥跡不同。","唯有無生三昧观，榮枯一照兩成空。"]', '诗', 'shi', '', NULL, '廬山草堂夜雨獨宿寄牛二李七庾三十二員外 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ac2a6df-2062-4923-8ff2-9cc102c5760e', '聞楊十二新拜省郎遙以詩賀', '闻楊十二新拜省郎遙以诗賀', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["文昌新入有光輝，紫界宮牆白粉闈。","曉日雞人傳漏箭，春風侍女護朝衣。","雪飄歌句高難和，鶴拂煙霄老慣飛。","官職聲名俱入手，近來詩客似君稀。"]', '["文昌新入有光輝，紫界宮牆白粉闈。","晓日雞人傳漏箭，春风侍女護朝衣。","雪飄歌句高难和，鹤拂煙霄老慣飞。","官職声名俱入手，近来诗客似君稀。"]', '诗', 'shi', '', NULL, '聞楊十二新拜省郎遙以詩賀 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96209cc2-5434-42f4-950e-6fd6249188da', '三月三日懷微之', '三月三日懷微之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["良時光景長虛擲，壯歲風情已闇銷。","忽憶同爲校書日，每年同醉是今朝。"]', '["良时光景长虛擲，壯歲风情已闇銷。","忽憶同爲校书日，每年同醉是今朝。"]', '诗', 'shi', '', NULL, '三月三日懷微之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c98a2e83-2d67-4e39-b6c8-4c043cd7cb9c', '贈韋八', '贈韋八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["辭君歲久見君初，白髮驚嗟兩有餘。","容鬢別來今至此，心情料取合何如。","曾同曲水花亭醉，亦共華陽竹院居。","豈料天南相見夜，哀猨瘴霧宿匡廬。"]', '["辞君歲久见君初，白髮驚嗟兩有餘。","容鬢別来今至此，心情料取合何如。","曾同曲水花亭醉，亦共华陽竹院居。","豈料天南相见夜，哀猨瘴霧宿匡廬。"]', '诗', 'shi', '', NULL, '贈韋八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e4db3d0-3aaa-4a5d-b981-9c1e0fa3440e', '春江閑步贈張山人', '春江闲步贈張山人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江景又妍和，牽愁發浩歌。","晴沙金屑色，春水麴塵波。","紅簇交枝杏，青含卷葉荷。","藉莎憐輭暖，憩樹愛婆娑。","書信朝賢斷，知音野老多。","相逢不閑語，爭奈日長何。"]', '["江景又妍和，牽愁發浩歌。","晴沙金屑色，春水麴塵波。","紅簇交枝杏，青含卷葉荷。","藉莎怜輭暖，憩樹愛婆娑。","书信朝賢斷，知音野老多。","相逢不闲語，爭奈日长何。"]', '诗', 'shi', '', NULL, '春江閑步贈張山人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('960e4335-105b-44d9-a388-616cacfbbe60', '春聽琵琶兼簡長孫司戶', '春听琵琶兼簡长孫司戶', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["四弦不似琵琶聲，亂寫真珠細撼鈴。","指底商風悲颯颯，舌頭胡語苦醒醒。","如言都尉思京國，似訴明妃厭虜庭。","遷客共君想勸諫，春腸易斷不須聽。"]', '["四弦不似琵琶声，亂寫真珠細撼鈴。","指底商风悲颯颯，舌头胡語苦醒醒。","如言都尉思京国，似訴明妃厭虜庭。","遷客共君想勸諫，春腸易斷不須听。"]', '诗', 'shi', '', NULL, '春聽琵琶兼簡長孫司戶 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fc4668d-074d-4173-ab58-099c207d6c87', '吳宮辭', '吳宮辞', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一入吳王殿，無人覩翠娥。","樓高時見舞，宮靜夜聞歌。","半露胷如雪，斜迴臉似波。","妍媸各有分，誰敢妬恩多。"]', '["一入吳王殿，無人覩翠娥。","楼高时见舞，宮静夜闻歌。","半露胷如雪，斜迴臉似波。","妍媸各有分，誰敢妬恩多。"]', '诗', 'shi', '', NULL, '吳宮辭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc98aeb4-a468-4903-8d47-212044d90b4f', '送韋侍御量移金州司馬', '送韋侍御量移金州司马', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["春歡雨露同霑澤，冬歎風霜獨滿衣。","留滯多時如我少，遷移好處似君稀。","臥龍雲到須先起，蟄燕雷驚尚未飛。","莫恨東西溝水別，滄溟長短擬同歸。"]', '["春歡雨露同霑澤，冬歎风霜独满衣。","留滯多时如我少，遷移好处似君稀。","臥龙云到須先起，蟄燕雷驚尚未飞。","莫恨东西溝水別，滄溟长短擬同归。"]', '诗', 'shi', '', NULL, '送韋侍御量移金州司馬 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c52b31d-acbb-4f8e-93c9-76cdc9fb511a', '自到潯陽生三女子因詮真理用遣妄懷', '自到潯陽生三女子因詮真理用遣妄懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["宦途本自安身拙，世累由來向老多。","遠謫四年徒已矣，晚生三女擬如何。","預愁嫁娶真成患，細念因緣盡是魔。","賴學空王治苦法，須拋煩惱入頭陀。"]', '["宦途本自安身拙，世累由来向老多。","远謫四年徒已矣，晚生三女擬如何。","預愁嫁娶真成患，細念因緣尽是魔。","賴学空王治苦法，須拋煩惱入头陀。"]', '诗', 'shi', '', NULL, '自到潯陽生三女子因詮真理用遣妄懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f41d25ac-e2d9-4de5-9369-9456cc5d5549', '江西裴常侍以優禮見待又蒙贈詩輙敘鄙誠用伸感謝', '江西裴常侍以優禮见待又蒙贈诗輙敘鄙誠用伸感謝', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一從簪笏事金貂，每借溫顏放折腰。","長覺身輕離泥滓，忽驚手重捧瓊瑤。","馬因迴顧雖增價，桐遇知音已半焦。","他日秉鈞如見念，壯心直氣未全銷。"]', '["一從簪笏事金貂，每借溫顏放折腰。","长覺身轻離泥滓，忽驚手重捧瓊瑤。","马因迴顧雖增價，桐遇知音已半焦。","他日秉鈞如见念，壯心直氣未全銷。"]', '诗', 'shi', '', NULL, '江西裴常侍以優禮見待又蒙贈詩輙敘鄙誠用伸感謝 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2232345-1eea-47ab-b252-bc20d75b246f', '自江州司馬授忠州刺史仰荷聖澤聊書鄙誠', '自江州司马授忠州刺史仰荷聖澤聊书鄙誠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["炎瘴拋身遠，泥塗索脚難。","網初鱗撥剌，籠久翅摧殘。","雷電頒時令，陽和變歲寒。","遺簪承舊念，剖竹授新官。","鄉覺前程近，心隨外事寬。","生還應有分，西笑問長安。"]', '["炎瘴拋身远，泥塗索脚难。","網初鱗撥剌，籠久翅摧殘。","雷電頒时令，陽和变歲寒。","遺簪承旧念，剖竹授新官。","乡覺前程近，心隨外事寬。","生還應有分，西笑问长安。"]', '诗', 'shi', '', NULL, '自江州司馬授忠州刺史仰荷聖澤聊書鄙誠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdc39e64-a590-48f5-8959-845a39d52ec6', '除忠州寄謝崔相公', '除忠州寄謝崔相公', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["提拔出泥知力竭，吹噓生翅見情深。","劒鋒缺折難衝斗，桐尾燒焦豈望琴。","感舊兩行年老淚，酬恩一寸歲寒心。","忠州好惡何須問，鳥得辭籠不擇林。"]', '["提拔出泥知力竭，吹噓生翅见情深。","劒鋒缺折难衝斗，桐尾燒焦豈望琴。","感旧兩行年老泪，酬恩一寸歲寒心。","忠州好惡何須问，鸟得辞籠不擇林。"]', '诗', 'shi', '', NULL, '除忠州寄謝崔相公 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5106359e-7828-4a8b-b252-46a3210cc985', '初除官蒙裴常侍贈鶻銜瑞草緋袍魚袋因謝惠貺兼抒離情', '初除官蒙裴常侍贈鶻銜瑞草緋袍鱼袋因謝惠貺兼抒離情', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["新授銅符未著緋，因君裝束始光輝。","惠深范叔綈袍贈，榮過蘇秦佩印歸。","魚綴白金隨步躍，鶻銜紅綬遶身飛。","明朝戀別朱門淚，不敢多垂恐汙衣。"]', '["新授銅符未著緋，因君裝束始光輝。","惠深范叔綈袍贈，榮過蘇秦佩印归。","鱼綴白金隨步躍，鶻銜紅綬遶身飞。","明朝戀別朱门泪，不敢多垂恐汙衣。"]', '诗', 'shi', '', NULL, '初除官蒙裴常侍贈鶻銜瑞草緋袍魚袋因謝惠貺兼抒離情 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('918bd6c6-e5dd-400c-8373-faf39b3d1daf', '洪州逢熊孺登', '洪州逢熊孺登', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["靖安院裏辛夷下，醉笑狂吟氣最麤。","莫問別來多少苦，低頭看取白髭鬚。"]', '["靖安院裏辛夷下，醉笑狂吟氣最麤。","莫问別来多少苦，低头看取白髭鬚。"]', '诗', 'shi', '', NULL, '洪州逢熊孺登 白居易 shi');
